export const ATLAS_INPUTS: ExerciseInput[] = [{"id":"atlas-adductor-ball-squeeze","name":"Adductor Ball Squeeze","equipment":"other","primaryMuscles":["adductors"],"secondaryMuscles":["abs"],"category":"isolation","instructions":["Lie on your back and bend your knees; place a soft pilates ball between your knees.","Exhale and squeeze the ball with your knees in a controlled way; keep your lower back and shoulders relaxed.","Release the squeeze and return to the start; apply light pressure without causing pain."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/adductor-ball-squeeze.webp"]}},{"id":"atlas-adductor-squeeze-bridge","name":"Adductor Squeeze Bridge","equipment":"other","primaryMuscles":["adductors"],"secondaryMuscles":["glutes"],"category":"compound","instructions":["Lie on the back with knees bent, feet planted, and a small soft ball between the knees.","Gently squeeze the ball while lifting the hips into a bridge without flaring the knees.","Lower the hips slowly while keeping the ball in place."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/adductor-squeeze-bridge.webp"]}},{"id":"atlas-archer-push-up","name":"Archer Push-Up","equipment":"bodyweight","primaryMuscles":["chest"],"secondaryMuscles":["triceps","shoulders"],"category":"compound","isBodyweight":true,"instructions":["Place your hands wider than your shoulders and take a plank position; keep the body in a straight line from head to heels.","Bend one elbow and lower your chest toward that hand while extending the opposite arm out to the side.","Push back to the center under control; work both sides equally and put your knees down if needed."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/archer-push-up.webp"]}},{"id":"atlas-assisted-chin-up","name":"Assisted Chin-Up (Machine)","equipment":"machine","primaryMuscles":["lats"],"secondaryMuscles":["biceps","back"],"category":"compound","instructions":["Set the counterweight and step carefully onto the assist platform. Take a shoulder-width underhand grip with palms facing you; keep shoulders away from your ears.","Pull your elbows down beside your torso to raise your chin toward handle height. Keep your body steady and avoid kicking or swinging.","Lower slowly until your arms are extended under control, then step off the platform carefully."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/assisted-chin-up.webp"]}},{"id":"atlas-assisted-dip","name":"Assisted Dip (Machine)","equipment":"machine","primaryMuscles":["chest"],"secondaryMuscles":["triceps","shoulders"],"category":"compound","instructions":["Sit or kneel on the assist platform, hold the parallel handles, and select enough assistance to move smoothly.","Bend your elbows to lower your body within a comfortable range while keeping your torso steady.","Press through the handles to return to the top; stop if you feel shoulder pain or cannot control the descent."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/assisted-dip.webp"]}},{"id":"atlas-assisted-pull-up","name":"Assisted Pull-Up (Machine)","equipment":"machine","primaryMuscles":["lats"],"secondaryMuscles":["biceps","back"],"category":"compound","instructions":["Adjust the support of the assisted pull-up machine and grip the bar slightly wider than shoulder width.","Pull your elbows down and lift your body up in a controlled manner.","Extend your arms slowly; do not shrug your shoulders toward your ears."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/assisted-pull-up.webp"]}},{"id":"atlas-back-extension-45-degree","name":"45-Degree Back Extension","equipment":"bodyweight","primaryMuscles":["lower_back"],"secondaryMuscles":["glutes","hamstrings"],"category":"compound","isBodyweight":true,"instructions":["Set the hip pad so it sits just below the pelvis; secure your feet.","Bend the torso forward from the hips, keeping the back neutral and the movement controlled.","Rise until the torso is in line with the legs; do not arch the lower back beyond that point."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/back-extension-45-degree.webp"]}},{"id":"atlas-band-pull-apart","name":"Band Pull-Apart","equipment":"band","primaryMuscles":["back"],"secondaryMuscles":["shoulders"],"category":"compound","instructions":["Hold a light band at chest height with your arms in front and your elbows soft.","Open your arms to the sides while bringing your shoulder blades toward each other; do not raise your shoulders.","Slowly bring the band back to the start while keeping tension; keep your torso still."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/band-pull-apart.webp"]}},{"id":"atlas-band-resisted-lateral-neck-flexion","name":"Band-Resisted Lateral Neck Flexion","equipment":"band","primaryMuscles":["neck"],"secondaryMuscles":[],"category":"isolation","instructions":["Sit upright; place a very light band beside your head and tie it to a fixed point at head height.","Tilt your head sideways only through a small, comfortable range to gently resist the band; keep your shoulders relaxed.","Slowly return to the neutral position; stop immediately if you feel pain, numbness or dizziness."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/band-resisted-lateral-neck-flexion.webp"]}},{"id":"atlas-band-resisted-neck-extension","name":"Band-Resisted Neck Extension","equipment":"band","primaryMuscles":["neck"],"secondaryMuscles":[],"category":"isolation","instructions":["Sit upright; place a very light band behind your head and anchor it in front of you at head height.","Bring your head back from neutral by only a few degrees to gently resist the band; do not lean back excessively.","Return to the neutral position in a controlled way; stop immediately if you feel pain, numbness or dizziness."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/band-resisted-neck-extension.webp"]}},{"id":"atlas-band-resisted-neck-flexion","name":"Band-Resisted Neck Flexion","equipment":"band","primaryMuscles":["neck"],"secondaryMuscles":[],"category":"isolation","instructions":["Sit upright; place a very light band on your forehead and anchor it behind you at head height.","Tilt your neck forward only a few degrees to gently resist the band; keep your shoulders relaxed.","Return to the neutral position in a controlled way; stop immediately if you feel pain, numbness or dizziness."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/band-resisted-neck-flexion.webp"]}},{"id":"atlas-banded-clamshell","name":"Banded Clamshell","equipment":"band","primaryMuscles":["abductors"],"secondaryMuscles":["glutes"],"category":"isolation","instructions":["Lie on your side, bend your knees and place a light band above your knees; keep your feet stacked.","Open your top knee in a controlled way without rolling your torso and hips backward.","Slowly close the knee against the resistance of the band; work both sides."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/banded-clamshell.webp"]}},{"id":"atlas-banded-monster-walk","name":"Banded Monster Walk","equipment":"band","primaryMuscles":["abductors"],"secondaryMuscles":["glutes"],"category":"isolation","instructions":["Place a mini band above your knees; bend your knees slightly and squat a little from the hips.","Keeping the band tense, take a controlled step to the side; track your knees in the direction of your feet.","Do not let the band go slack as you bring the other foot closer; travel equally in both directions."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/banded-monster-walk.webp"]}},{"id":"atlas-barbell-board-press","name":"Board Press (Barbell)","equipment":"barbell","primaryMuscles":["triceps"],"secondaryMuscles":["chest","shoulders","forearms"],"category":"compound","instructions":["Set the bar in a rack with safeties, lie on a flat bench, and have a spotter hold a stable board on your mid-chest; use a load you can control.","Grip the bar around shoulder width and lower it slowly until it gently touches the board; keep your wrists above your elbows and do not bounce.","Press the bar to near-straight arms, then have the spotter help return it to the rack."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/barbell-board-press.webp"]}},{"id":"atlas-barbell-bulgarian-split-squat","name":"Bulgarian Split Squat (Barbell)","equipment":"barbell","primaryMuscles":["quads","glutes"],"secondaryMuscles":["hamstrings"],"category":"compound","instructions":["Set a stable bench behind you and place the bar across your upper back, not your neck; rest the top of one foot on the bench and set the front foot far enough forward to keep the heel down.","Brace your trunk and lower mostly straight down by bending both knees; keep the front knee tracking with the toes and stop at a depth you can control.","Drive through the whole front foot to stand. Complete the repetitions on one side before switching; use a rack and a light load until balance is steady."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/barbell-bulgarian-split-squat.webp"]}},{"id":"atlas-barbell-clean","name":"Barbell Clean","equipment":"barbell","primaryMuscles":["glutes","quads","traps"],"secondaryMuscles":["hamstrings","shoulders","abs","lower_back"],"category":"compound","instructions":["Stand with the bar over mid-foot, grip just outside your legs, and brace with your shoulders slightly ahead of the bar and your back neutral.","Push through the floor and extend your hips and knees while keeping the bar close; pull under it and receive it on your shoulders in a full squat with elbows forward.","Keep the bar secure in the front rack and stand by extending your hips and knees; lower the bar safely before resetting."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/barbell-clean.webp"]}},{"id":"atlas-barbell-clean-and-jerk","name":"Clean and Jerk","equipment":"barbell","primaryMuscles":["glutes","quads","shoulders"],"secondaryMuscles":["hamstrings","traps","triceps","abs"],"category":"compound","instructions":["Stand with the bar over mid-foot, grip just outside your legs, and brace with your shoulders slightly ahead of the bar.","Lift the bar close to your body and receive it on your shoulders in a stable front-rack position.","Dip slightly through the knees, drive the bar overhead, and split or push under it; recover your feet under your hips, lock out, then lower the bar with control."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/barbell-clean-and-jerk.webp"]}},{"id":"atlas-barbell-clean-and-press","name":"Clean and Press (Barbell)","equipment":"barbell","primaryMuscles":["shoulders"],"secondaryMuscles":["quads","glutes","hamstrings","traps","triceps","abs","lower_back"],"category":"compound","instructions":["Stand with the bar over mid-foot, feet about shoulder-width apart, and grip just outside your legs. Brace your trunk and keep your back neutral.","Drive through the floor and extend your hips and knees, keeping the bar close; pull under it and catch it securely on your front shoulders with elbows forward, then stand tall.","Without dipping your knees, press the bar overhead until your elbows are straight and the bar is balanced over mid-foot. Lower it under control to the front rack, then return it safely to the floor."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/barbell-clean-and-press.webp"]}},{"id":"atlas-barbell-clean-from-blocks","name":"Clean from Blocks (Barbell)","equipment":"barbell","primaryMuscles":["glutes","quads","traps"],"secondaryMuscles":["hamstrings","shoulders","abs","lower_back"],"category":"compound","instructions":["Set stable lifting blocks so the bar rests motionless around knee height; stand close with a clean-width grip, neutral back and shoulders slightly ahead of the bar.","Push through the floor and extend your knees while keeping the bar close; finish the hip drive, pull under, and receive the bar on your shoulders in a balanced squat with elbows forward.","Stand with the bar secure in the front rack, then return it under control to the blocks before resetting."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/barbell-clean-from-blocks.webp"]}},{"id":"atlas-barbell-clean-pull","name":"Clean Pull (Barbell)","equipment":"barbell","primaryMuscles":["quads","glutes"],"secondaryMuscles":["hamstrings","traps","lower_back","forearms"],"category":"compound","instructions":["Stand with the bar over mid-foot and take a clean-width grip; brace with your back neutral, shoulders slightly ahead of the bar and arms long.","Push through the floor and extend your knees while keeping the bar close; maintain your back angle until the bar passes the knees.","From lower to mid-thigh, extend your hips, knees and ankles vertically and shrug to accelerate the bar; do not pull under or catch it. Lower the bar safely before resetting."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/barbell-clean-pull.webp"]}},{"id":"atlas-barbell-finger-curl","name":"Finger Curl (Barbell)","equipment":"barbell","primaryMuscles":["forearms"],"secondaryMuscles":[],"category":"isolation","instructions":["Sit on a bench and rest your forearms on your thighs, palms up, with your wrists just beyond your knees; hold a very light barbell securely.","Keeping your forearms supported and wrists nearly still, open your fingers so the bar rolls toward the last finger joints without slipping free.","Close your fingers to curl the bar back into your palms, then repeat with control."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/barbell-finger-curl.webp"]}},{"id":"atlas-barbell-floor-press","name":"Floor Press (Barbell)","equipment":"barbell","primaryMuscles":["chest"],"secondaryMuscles":["triceps","shoulders"],"category":"compound","instructions":["Lie on a mat with knees bent and feet flat; use a rack or a spotter to position the bar safely over mid-chest.","Lower the bar under control until your upper arms lightly touch the floor, keeping wrists above elbows.","Press the bar back over mid-chest until your arms are nearly straight; do not bounce your elbows off the floor."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/barbell-floor-press.webp"]}},{"id":"atlas-barbell-forward-lunge","name":"Forward Lunge (Barbell)","equipment":"barbell","primaryMuscles":["quads","glutes"],"secondaryMuscles":["hamstrings","abs"],"category":"compound","instructions":["Set the bar in a rack at shoulder height, position it across your upper back, and stand with feet about hip-width apart.","Step one foot forward and lower under control until both knees bend comfortably; keep the front foot planted and knee tracking with the toes.","Push through the front foot to return to standing, then repeat on the other side. Re-rack the bar securely when finished."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/barbell-forward-lunge.webp"]}},{"id":"atlas-barbell-front-foot-elevated-reverse-lunge","name":"Front-Foot-Elevated Reverse Lunge (Barbell)","equipment":"barbell","primaryMuscles":["quads"],"secondaryMuscles":["glutes","hamstrings"],"category":"compound","instructions":["Set the bar in a rack at a height that lets you unrack and rerack safely. Place a low, stable platform in front of you and stand with both feet fully supported on it, bar resting across your upper back.","Brace your torso and step one foot backward off the platform. Lower under control until the back knee nears the floor, keeping the whole front foot planted and your torso upright.","Drive through the front foot to return to the platform. Complete the repetitions on one side, then switch legs; use a platform height and load you can control."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/barbell-front-foot-elevated-reverse-lunge.webp"]}},{"id":"atlas-barbell-hack-squat","name":"Hack Squat (Barbell)","equipment":"barbell","primaryMuscles":["quads"],"secondaryMuscles":["glutes","hamstrings","calves"],"category":"compound","instructions":["Stand with a loaded barbell just behind your calves, feet about shoulder-width apart; hinge and bend your knees to grip the bar just outside your legs with arms straight and back neutral.","Brace your trunk and drive through the floor, extending your knees and hips together while keeping the bar close behind your legs until you stand tall.","Bend your hips and knees under control to lower the bar behind your legs back to the floor; reset your grip and posture before the next repetition."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/barbell-hack-squat.webp"]}},{"id":"atlas-barbell-hang-clean","name":"Hang Clean (Barbell)","equipment":"barbell","primaryMuscles":["glutes","quads","traps"],"secondaryMuscles":["hamstrings","shoulders","abs","lower_back"],"category":"compound","instructions":["Stand tall with the bar just above your knees or at mid-thigh, hands just outside the legs, and knees softly bent; brace your trunk.","Hinge slightly, then extend your hips and knees quickly while keeping the bar close; pull under it and receive it on your shoulders in a full squat with elbows forward.","Stand by extending your hips and knees while keeping the bar in the front rack, then lower it under control to reset."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/barbell-hang-clean.webp"]}},{"id":"atlas-barbell-lateral-lunge","name":"Lateral Lunge (Barbell)","equipment":"barbell","primaryMuscles":["quads","adductors"],"secondaryMuscles":["glutes","hamstrings","calves"],"category":"compound","instructions":["Secure the bar across your upper back, not your neck, and stand in a wide stance with your feet flat and toes slightly turned out.","Send your hips toward one side as you bend that knee and keep the opposite leg long; keep your chest open and let the bent knee track in the same direction as the toes.","Press through the bent leg to return to the wide stance, then repeat to the other side."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/barbell-lateral-lunge.webp"]}},{"id":"atlas-barbell-lying-triceps-extension","name":"Lying Triceps Extension (Barbell)","equipment":"barbell","primaryMuscles":["triceps"],"secondaryMuscles":[],"category":"isolation","instructions":["Lie on a flat bench with your feet planted. Hold a manageable barbell with a narrow overhand grip above your shoulders and angle your upper arms slightly back.","Keeping your upper arms mostly still, bend your elbows to lower the bar slowly toward your forehead without touching it; keep your wrists straight.","Extend your elbows to raise the bar to the start position without flaring your elbows or letting them drift apart."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/barbell-lying-triceps-extension.webp"]}},{"id":"atlas-barbell-overhead-squat","name":"Overhead Squat (Barbell)","equipment":"barbell","primaryMuscles":["quads","glutes","shoulders"],"secondaryMuscles":["abs","lower_back","traps"],"category":"compound","instructions":["Take a wide grip and get the bar to a stable overhead lockout from a rack or a light snatch; set your feet about shoulder-width and brace your trunk.","Keep the bar balanced over your mid-foot and your elbows locked as you squat until your hip crease passes below the knees; keep your heels down and knees tracking with your toes.","Drive through the floor to stand while keeping the bar overhead and your trunk steady, then return the bar to the rack under control."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/barbell-overhead-squat.webp"]}},{"id":"atlas-barbell-pin-press","name":"Pin Press (Barbell)","equipment":"barbell","primaryMuscles":["triceps"],"secondaryMuscles":["chest","shoulders"],"category":"compound","instructions":["Set rack safeties at a height where the bar can settle over your mid-chest, and lie on a flat bench with your feet planted. Use a spotter and a load you can control.","Grip the bar around shoulder width, lower it under control until it rests on the pins, and let it become still without bouncing.","Press from the dead stop to near-straight arms while keeping your upper back and hips on the bench, then return the bar safely to the rack."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/barbell-pin-press.webp"]}},{"id":"atlas-barbell-pullover","name":"Barbell Pullover","equipment":"barbell","primaryMuscles":["lats"],"secondaryMuscles":["chest","shoulders","triceps"],"category":"compound","instructions":["Lie along a flat bench with your feet planted and hold a lightly loaded barbell above your chest using a close overhand grip. Keep a soft, fixed bend in your elbows; use a spotter when needed.","Keeping your upper back on the bench and ribs controlled, lower the bar in a smooth arc behind your head only as far as your shoulders remain comfortable. Do not force a deep stretch.","Pull the bar back over your chest by bringing your upper arms forward; keep the same elbow bend and avoid arching your lower back."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/barbell-pullover.webp"]}},{"id":"atlas-barbell-rear-delt-row","name":"Rear-Delt Row (Barbell)","equipment":"barbell","primaryMuscles":["shoulders"],"secondaryMuscles":["back","traps","biceps"],"category":"compound","instructions":["Stand with feet about hip-width apart, grip the bar wider than shoulder width with an overhand grip, and hinge forward while keeping your spine neutral. Start with the bar hanging below your chest.","Keeping your torso angle steady, lead with your elbows out to the sides and row the bar toward your upper chest; use a light, controlled load and avoid swinging.","Lower the bar slowly until your arms are extended, maintaining the hip hinge and a neutral back."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/barbell-rear-delt-row.webp"]}},{"id":"atlas-barbell-reverse-lunge","name":"Reverse Lunge (Barbell)","equipment":"barbell","primaryMuscles":["quads","glutes"],"secondaryMuscles":["hamstrings","abs"],"category":"compound","instructions":["Set the bar securely across your upper back and stand with feet about hip-width apart.","Step one foot backward and lower under control, keeping the front foot planted and the front knee aligned with the toes.","Push through the front foot to return to standing; complete the repetitions on one side, then switch."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/barbell-reverse-lunge.webp"]}},{"id":"atlas-barbell-reverse-wrist-curl","name":"Reverse Wrist Curl (Barbell)","equipment":"barbell","primaryMuscles":["forearms"],"secondaryMuscles":[],"category":"isolation","instructions":["Sit with your forearms supported on your thighs or a bench and hold a light barbell with palms facing down.","Keeping your forearms still, lift the backs of your hands by extending your wrists.","Lower your wrists slowly to a comfortable range; use a light load and avoid bouncing."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/barbell-reverse-wrist-curl.webp"]}},{"id":"atlas-barbell-seated-calf-raise","name":"Seated Calf Raise (Barbell)","equipment":"barbell","primaryMuscles":["calves"],"secondaryMuscles":[],"category":"isolation","instructions":["Sit near the front of a stable bench with the balls of your feet on a low, stable step and your heels free; place a padded, manageable barbell across your lower thighs just above the knees.","Keep your torso steady and raise your heels by pressing through the balls of your feet; pause briefly at the top.","Lower your heels slowly through a comfortable range without bouncing, then repeat."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/barbell-seated-calf-raise.webp"]}},{"id":"atlas-barbell-seated-shoulder-press","name":"Seated Shoulder Press (Barbell)","equipment":"barbell","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps"],"category":"compound","instructions":["Set a rack so the bar starts just below shoulder height. Sit with your back against an upright bench, feet flat, and grip the bar slightly wider than shoulder-width; unrack it to the front of your shoulders.","Brace your torso and press the bar vertically overhead while keeping your elbows slightly forward and your back against the pad.","Lower the bar under control to chin height in front of you, then return it to the rack before changing the setup."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/barbell-seated-shoulder-press.webp"]}},{"id":"atlas-barbell-shrug-behind-the-back","name":"Shrug Behind The Back (Barbell)","equipment":"barbell","primaryMuscles":["traps"],"secondaryMuscles":["forearms"],"category":"isolation","instructions":["Hold a light bar behind you with your arms straight and your palms facing backward.","Raise your shoulders straight up; do not bend your elbows or roll your shoulders in circles.","Pause briefly and slowly lower your shoulders; make sure the bar does not hit your legs."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/barbell-shrug-behind-the-back.webp"]}},{"id":"atlas-barbell-snatch","name":"Barbell Snatch","equipment":"barbell","primaryMuscles":["glutes","quads","shoulders"],"secondaryMuscles":["hamstrings","traps","abs","lower_back"],"category":"compound","instructions":["Stand with the bar over mid-foot and take a wide overhand snatch grip; brace your trunk with the bar close to your shins.","Push through the floor and extend your hips and knees, keeping the bar close; then pull under and receive it overhead in a stable squat with arms locked.","Stand to full hip and knee extension while keeping the bar balanced overhead, then lower it safely."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/barbell-snatch.webp"]}},{"id":"atlas-barbell-standing-calf-raise","name":"Standing Calf Raise (Barbell)","equipment":"barbell","primaryMuscles":["calves"],"secondaryMuscles":[],"category":"isolation","instructions":["Set a manageable barbell in a rack around shoulder height. Place it across your upper back, not your neck, grip just outside your shoulders, then stand and step back with feet about hip-width apart.","Keeping your torso steady and knees slightly soft, press through the balls of both feet to raise your heels as high as comfortable.","Pause briefly, then lower your heels slowly to the floor without bouncing."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/barbell-standing-calf-raise.webp"]}},{"id":"atlas-barbell-step-up","name":"Barbell Step-Up","equipment":"barbell","primaryMuscles":["quads","glutes"],"secondaryMuscles":["hamstrings","calves"],"category":"compound","instructions":["Set a stable platform in front of you and position the bar securely across your upper back, not on your neck; stand tall and brace.","Place one whole foot on the platform, keep the knee tracking over the toes, and press through that foot to rise without pushing off strongly with the trailing leg.","Stand balanced on the platform, then step down slowly under control and repeat on the other side."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/barbell-step-up.webp"]}},{"id":"atlas-barbell-thruster","name":"Barbell Thruster","equipment":"barbell","primaryMuscles":["quads","glutes"],"secondaryMuscles":["shoulders","triceps"],"category":"compound","instructions":["Set a manageable barbell in a front-rack position across your shoulders, hands just outside shoulder width, and elbows pointing forward. Stand with feet about shoulder-width apart.","Keep your torso upright as you squat to a controlled depth, with the bar supported across your shoulders.","Drive through your feet to stand and continue the motion into a barbell press overhead. Lower the bar to the shoulders under control before the next squat."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/barbell-thruster.webp"]}},{"id":"atlas-barbell-walking-lunge","name":"Walking Lunge (Barbell)","equipment":"barbell","primaryMuscles":["quads","glutes"],"secondaryMuscles":["hamstrings","abs"],"category":"compound","instructions":["Set the bar securely across your upper back and stand with feet about hip-width apart.","Step forward and bend both knees to lower under control; keep the front knee tracking in line with the foot.","Push through the front foot to rise and bring the rear leg through into the next step; use a clear, open path."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/barbell-walking-lunge.webp"]}},{"id":"atlas-battle-rope-alternating-waves","name":"Battle Rope Alternating Waves","equipment":"other","primaryMuscles":["shoulders"],"secondaryMuscles":["forearms","abs"],"category":"cardio","instructions":["Stand facing the anchor with feet stable and hold one rope end in each hand.","Alternate raising and lowering your arms to send waves toward the anchor at a steady rhythm.","Keep your torso braced and knees soft; use short intervals and stop if your form breaks down."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/battle-rope-alternating-waves.webp"]}},{"id":"atlas-battle-rope-double-arm-slam","name":"Battle Rope Double-Arm Slam","equipment":"other","primaryMuscles":["shoulders","abs"],"secondaryMuscles":["forearms","triceps"],"category":"cardio","instructions":["Face the anchor in a stable stance and hold one rope end in each hand.","Raise both hands overhead, then drive them down together while bending your hips and knees slightly.","Return to the ready position under control; keep the ropes in your hands and repeat smoothly."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/battle-rope-double-arm-slam.webp"]}},{"id":"atlas-bayesian-cable-curl","name":"Bayesian Curl (Cable)","equipment":"cable","primaryMuscles":["biceps"],"secondaryMuscles":["forearms"],"category":"isolation","instructions":["Attach a single handle to a low pulley; step slightly forward so the cable stays behind you.","Keeping your elbow fixed slightly behind your torso, curl the handle toward your shoulder.","Extend your arm slowly; if you feel tension or pain in the shoulder, change the starting position."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/bayesian-cable-curl.webp"]}},{"id":"atlas-bear-crawl","name":"Bear Crawl","equipment":"bodyweight","primaryMuscles":["abs","shoulders"],"secondaryMuscles":["quads","glutes"],"category":"cardio","isBodyweight":true,"instructions":["Start on hands and toes with knees hovering just above the mat; keep your back level and trunk braced.","Move one hand and the opposite foot forward a short distance, keeping your hips low.","Alternate sides in a slow crawl without rocking your hips; pause if your form breaks down."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/bear-crawl.webp"]}},{"id":"atlas-bear-plank-shoulder-tap","name":"Bear-Plank Shoulder Tap","equipment":"bodyweight","primaryMuscles":["abs"],"secondaryMuscles":["shoulders"],"category":"compound","isBodyweight":true,"instructions":["Start on hands and knees, then hover knees just above the mat with back level.","Shift slightly and tap one hand to the opposite shoulder without rocking hips.","Replace the hand, steady yourself and alternate sides."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/bear-plank-shoulder-tap.webp"]}},{"id":"atlas-behind-the-back-barbell-wrist-curl","name":"Behind-the-Back Wrist Curl (Barbell)","equipment":"barbell","primaryMuscles":["forearms"],"secondaryMuscles":[],"category":"isolation","instructions":["Hold a light bar behind you with your arms extended comfortably and your palms facing backward.","Keeping your shoulders still, raise the bar by curling your wrists in a controlled way.","Lower your wrists slowly back to the start; stop if you feel pain or numbness."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/behind-the-back-barbell-wrist-curl.webp"]}},{"id":"atlas-belt-squat","name":"Belt Squat (Machine)","equipment":"machine","primaryMuscles":["quads"],"secondaryMuscles":["glutes","hamstrings"],"category":"compound","instructions":["Stand on the platform, attach the belt securely at the hip crease, and hold the machine handles for balance.","Bend your hips and knees to squat under control, keeping your torso upright and knees tracking with your toes.","Drive through the platform to stand; follow the machine placard to engage its lock before stepping off."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/belt-squat.webp"]}},{"id":"atlas-bench-lat-stretch","name":"Bench Lat Stretch","equipment":"bodyweight","primaryMuscles":["lats"],"secondaryMuscles":["shoulders"],"category":"mobility","isBodyweight":true,"instructions":["Kneel in front of a sturdy bench and place your forearms on it around shoulder width.","Keep your head aligned with your torso, send your hips back, and lower your chest gently toward the floor.","Breathe into the stretch along your sides, then return upright without forcing your shoulders."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/bench-lat-stretch.webp"]}},{"id":"atlas-bent-over-dumbbell-reverse-fly","name":"Bent-Over Reverse Fly (Dumbbell)","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":["back"],"category":"isolation","instructions":["Hinge at the hips with a steady back and let light dumbbells hang below the shoulders.","Lift both arms outward with softly bent elbows until near shoulder height.","Lower slowly without swinging the torso."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/bent-over-dumbbell-reverse-fly.webp"]}},{"id":"atlas-bent-over-one-arm-landmine-row","name":"Bent-Over One-Arm Landmine Row","equipment":"barbell","primaryMuscles":["back"],"secondaryMuscles":["lats","biceps","lower_back"],"category":"compound","instructions":["Secure one end of a barbell in a landmine sleeve or a stable corner and load the free end. Stand over the loaded end in a staggered stance, hinge forward with a neutral back, and brace your free hand on the forward knee. Grip the bar just behind the plates.","Keep your torso still and row the loaded end toward your waist, keeping the working elbow close to your side. Do not twist or jerk the bar.","Lower the bar under control until your arm is extended, complete the set, then switch sides."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/bent-over-one-arm-landmine-row.webp"]}},{"id":"atlas-bird-dog","name":"Bird Dog","equipment":"bodyweight","primaryMuscles":["lower_back"],"secondaryMuscles":["abs","glutes"],"category":"compound","isBodyweight":true,"instructions":["Place your hands under your shoulders and your knees under your hips; keep your back neutral.","Extend the opposite arm and leg without rotating the torso and hold your balance briefly.","Return to the start under control and switch sides; do not let your lower back sag."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/bird-dog.webp"]}},{"id":"atlas-bird-dog-dumbbell-row","name":"Bird-Dog Row (Dumbbell)","equipment":"dumbbell","primaryMuscles":["lats"],"secondaryMuscles":["back","abs"],"category":"compound","instructions":["Set one hand and the opposite knee on a stable bench; extend the other leg behind.","Hold a light dumbbell and row it toward your ribs while keeping your torso level.","Lower slowly, complete the side, then switch."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/bird-dog-dumbbell-row.webp"]}},{"id":"atlas-bodyweight-crab-reach","name":"Bodyweight Crab Reach","equipment":"bodyweight","primaryMuscles":["glutes","abs"],"secondaryMuscles":["shoulders","back"],"category":"mobility","isBodyweight":true,"instructions":["Sit with hands behind you and feet flat; lift your hips into a stable crab tabletop.","Keep your head neutral and reach one arm overhead as you rotate through the upper back.","Return the hand to the floor, lower with control and alternate sides."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/bodyweight-crab-reach.webp"]}},{"id":"atlas-bodyweight-curtsy-lunge","name":"Bodyweight Curtsy Lunge","equipment":"bodyweight","primaryMuscles":["glutes"],"secondaryMuscles":["quads","adductors"],"category":"compound","isBodyweight":true,"instructions":["Stand tall with feet hip-width apart.","Step one leg diagonally behind the other and bend both knees comfortably.","Press through the front foot to stand and switch sides."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/bodyweight-curtsy-lunge.webp"]}},{"id":"atlas-bodyweight-inchworm","name":"Bodyweight Inchworm","equipment":"bodyweight","primaryMuscles":["abs"],"secondaryMuscles":["shoulders","hamstrings"],"category":"compound","isBodyweight":true,"instructions":["Stand tall, hinge at the hips and place your hands on the floor in front of your feet.","Walk your hands forward until you reach a stable high plank.","Walk your hands back and stand without forcing a hamstring stretch."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/bodyweight-inchworm.webp"]}},{"id":"atlas-bodyweight-jumping-jack","name":"Bodyweight Jumping Jack","equipment":"bodyweight","primaryMuscles":["calves"],"secondaryMuscles":["shoulders"],"category":"cardio","isBodyweight":true,"instructions":["Stand with feet together and arms by your sides.","Jump the feet apart while raising both arms overhead.","Jump back to the starting stance and land softly; step out instead to reduce impact."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/bodyweight-jumping-jack.webp"]}},{"id":"atlas-bodyweight-lateral-bound","name":"Bodyweight Lateral Bound","equipment":"bodyweight","primaryMuscles":["glutes"],"secondaryMuscles":["quads","abductors"],"category":"compound","isBodyweight":true,"instructions":["Balance on one leg with the knee slightly bent.","Push sideways and land on the opposite leg with a soft knee.","Pause to regain balance before bounding back; shorten the distance if needed."],"formCues":[],"media":{}},{"id":"atlas-bodyweight-plank-jack","name":"Bodyweight Plank Jack","equipment":"bodyweight","primaryMuscles":["abs"],"secondaryMuscles":["abductors","shoulders"],"category":"compound","isBodyweight":true,"instructions":["Set a high plank with hands under shoulders and feet together.","Hop both feet outward while keeping your torso steady and hips level.","Hop the feet together softly; step instead if needed."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/bodyweight-plank-jack.webp"]}},{"id":"atlas-bodyweight-plank-to-downward-dog","name":"Bodyweight Plank to Downward Dog","equipment":"bodyweight","primaryMuscles":["abs"],"secondaryMuscles":["shoulders","hamstrings"],"category":"compound","isBodyweight":true,"instructions":["Start in a high plank with hands under shoulders and feet hip-width apart.","Push the floor away and lift your hips back into an inverted V; bend knees softly if needed.","Return to plank without letting your lower back sag."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/bodyweight-plank-to-downward-dog.webp"]}},{"id":"atlas-bodyweight-side-plank-hip-dip","name":"Bodyweight Side-Plank Hip Dip","equipment":"bodyweight","primaryMuscles":["abs"],"secondaryMuscles":["shoulders"],"category":"compound","isBodyweight":true,"instructions":["Set a forearm side plank with your elbow below your shoulder and feet stacked.","Lower your hip a short distance without rolling your chest forward.","Lift your hip back into line and repeat; switch sides."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/bodyweight-side-plank-hip-dip.webp"]}},{"id":"atlas-bodyweight-skater-squat","name":"Bodyweight Skater Squat","equipment":"bodyweight","primaryMuscles":["glutes","quads"],"secondaryMuscles":["abductors"],"category":"compound","isBodyweight":true,"instructions":["Stand on one leg with the other knee bent behind you.","Bend the standing knee and send the free knee toward the floor behind your body.","Press through the standing foot to rise; hold a support if balance is limited."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/bodyweight-skater-squat.webp"]}},{"id":"atlas-bodyweight-squat-jump","name":"Bodyweight Squat Jump","equipment":"bodyweight","primaryMuscles":["quads","glutes"],"secondaryMuscles":["calves"],"category":"compound","isBodyweight":true,"instructions":["Stand with feet about shoulder-width apart and sit into a comfortable squat.","Drive through both feet to jump vertically, using your arms naturally for balance.","Land softly with knees tracking over toes, then reset before repeating."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/bodyweight-squat-jump.webp"]}},{"id":"atlas-bodyweight-squat-thrust","name":"Bodyweight Squat Thrust","equipment":"bodyweight","primaryMuscles":["abs"],"secondaryMuscles":["shoulders","quads","glutes"],"category":"compound","isBodyweight":true,"instructions":["Crouch and place both hands on the floor beneath your shoulders.","Step or hop both feet back into a stable high plank without letting the lower back sag.","Bring the feet back beneath you and stand; step one foot at a time to reduce impact."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/bodyweight-squat-thrust.webp"]}},{"id":"atlas-bodyweight-triceps-extension","name":"Bodyweight Triceps Extension","equipment":"other","primaryMuscles":["triceps"],"secondaryMuscles":["shoulders"],"category":"isolation","instructions":["Grip a sturdy, non-slip bar at shoulder width; keep your torso straight and lean backward.","Keeping your elbows forward and fixed, bend your arms enough to bring your forehead close to the bar.","Use your triceps to extend your elbows and return to the start; adjust your foot position to change the difficulty."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/bodyweight-triceps-extension.webp"]}},{"id":"atlas-burpee","name":"Burpee","equipment":"bodyweight","primaryMuscles":["quads","abs"],"secondaryMuscles":["shoulders","glutes","calves","chest"],"category":"cardio","isBodyweight":true,"instructions":["Stand with feet about hip-width apart, then squat and place your hands on the floor.","Step or hop both feet back to a firm high plank while keeping your trunk braced.","Bring your feet forward and stand; add a small jump only if you can land quietly, or step to reduce impact."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/burpee.webp"]}},{"id":"atlas-butterfly-stretch","name":"Butterfly Stretch","equipment":"bodyweight","primaryMuscles":["adductors"],"secondaryMuscles":[],"category":"mobility","isBodyweight":true,"instructions":["Sit tall on a mat, bring the soles of your feet together, and let your knees relax outward.","Keeping your spine long, hinge forward slightly from the hips until you feel a gentle inner-thigh stretch.","Breathe comfortably, avoid pressing your knees down, and return upright."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/butterfly-stretch.webp"]}},{"id":"atlas-cable-crossover","name":"Cable Crossover","equipment":"cable","primaryMuscles":["chest"],"secondaryMuscles":["shoulders"],"category":"compound","instructions":["Attach handles to two high pulleys and stand balanced in the middle; lean your torso slightly forward.","Keeping your elbows soft, bring your arms together forward and downward.","Open your arms to the sides under control; stay in a comfortable stretch range without swinging the weight."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/cable-crossover.webp"]}},{"id":"atlas-cable-deadlift","name":"Cable Deadlift","equipment":"cable","primaryMuscles":["glutes","hamstrings"],"secondaryMuscles":["quads","lower_back","forearms"],"category":"compound","instructions":["Attach a straight bar to the lowest pulley and stand over the cable with your feet about hip-width apart; hinge at the hips and bend your knees enough to grip the bar with straight arms and a neutral spine.","Brace your trunk and push through the floor, extending your hips and knees together while keeping the bar close to your legs.","Stand tall without leaning back, then hinge and bend your knees to lower the bar under control until you reach the start position."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/cable-deadlift.webp"]}},{"id":"atlas-cable-flat-bench-fly","name":"Flat Bench Fly (Cable)","equipment":"cable","primaryMuscles":["chest"],"secondaryMuscles":["shoulders"],"category":"compound","instructions":["Place a flat bench between two cable stacks, set both pulleys low, and lie back with one handle in each hand; keep a slight bend in your elbows.","Open your arms out to the sides in a controlled arc until you feel a comfortable chest stretch, keeping your shoulders supported on the bench.","Bring the handles together above your mid-chest without changing the elbow bend, then return slowly and avoid forcing your shoulders behind your torso."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/cable-flat-bench-fly.webp"]}},{"id":"atlas-cable-front-raise","name":"Front Raise (Cable)","equipment":"cable","primaryMuscles":["shoulders"],"secondaryMuscles":["traps","abs"],"category":"isolation","instructions":["Set a single handle at the lowest pulley and stand facing away from the cable tower with the handle beside the front of one thigh.","Brace your torso and raise the handle forward in a smooth arc to about shoulder height, keeping a soft bend in the elbow and avoiding a shrug.","Lower the handle slowly to the start position; complete the set, then switch arms."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/cable-front-raise.webp"]}},{"id":"atlas-cable-hip-abduction","name":"Hip Abduction (Cable)","equipment":"cable","primaryMuscles":["abductors"],"secondaryMuscles":["glutes"],"category":"isolation","instructions":["Attach the ankle cuff to the low cable and stand balanced next to the machine.","Keeping your torso still, open the working leg out to the side in a controlled way.","Return the leg to the starting position without swinging it; work both sides."],"formCues":[],"media":{}},{"id":"atlas-cable-hip-adduction","name":"Hip Adduction (Cable)","equipment":"cable","primaryMuscles":["adductors"],"secondaryMuscles":["glutes"],"category":"isolation","instructions":["Attach the ankle strap to the low pulley; stand sideways to the machine and hold on for support.","Pull the working leg inward in front of your body in a controlled way; do not rotate your hips.","Return to the start against the resistance; work both sides."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/cable-hip-adduction.webp"]}},{"id":"atlas-cable-incline-triceps-extension","name":"Incline Triceps Extension (Cable)","equipment":"cable","primaryMuscles":["triceps"],"secondaryMuscles":[],"category":"isolation","instructions":["Set an incline bench facing away from a low pulley, attach a rope, and lie back with your head nearest the pulley and feet planted.","Hold the rope above your shoulders with your upper arms angled upward; bend your elbows to bring the rope just behind your head without touching it.","Keeping your upper arms steady, extend your elbows to raise the rope above your forehead, then bend them slowly to return."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/cable-incline-triceps-extension.webp"]}},{"id":"atlas-cable-oblique-crunch","name":"Oblique Crunch (Cable)","equipment":"cable","primaryMuscles":["abs"],"secondaryMuscles":[],"category":"compound","instructions":["Set a high cable attachment and stand side-on to the machine; hold the handle near your upper chest with a comfortable stance.","Brace your trunk and bend sideways toward the cable in a short, controlled range while keeping your hips steady.","Return slowly against the cable and complete both sides; keep your head relaxed and do not pull on your neck."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/cable-oblique-crunch.webp"]}},{"id":"atlas-cable-preacher-curl","name":"Preacher Curl (Cable)","equipment":"cable","primaryMuscles":["biceps"],"secondaryMuscles":["forearms"],"category":"compound","instructions":["Attach a straight bar to the lowest pulley and place a preacher bench in front of the cable stack; sit with your chest and upper arms supported on the pad and grip the bar underhand at about shoulder width.","Keeping your upper arms on the pad and wrists straight, curl the bar toward your shoulders without rocking your torso.","Lower the bar slowly until your elbows are nearly extended while keeping tension on the cable; do not forcefully lock your elbows."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/cable-preacher-curl.webp"]}},{"id":"atlas-cable-reverse-crunch","name":"Reverse Crunch (Cable)","equipment":"cable","primaryMuscles":["abs"],"secondaryMuscles":[],"category":"compound","instructions":["Attach ankle cuffs to a low pulley, lie on a mat with your feet facing the cable stack, and bend your knees to about 90 degrees; rest your arms beside you and keep light cable tension.","Brace your abdomen and draw your knees toward your chest, curling your pelvis slightly off the mat without swinging your legs.","Lower your pelvis and legs slowly to the start while keeping control of the cable; do not let the weight stack slam."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/cable-reverse-crunch.webp"]}},{"id":"atlas-cable-reverse-curl","name":"Reverse Curl (Cable)","equipment":"cable","primaryMuscles":["forearms"],"secondaryMuscles":["biceps"],"category":"compound","instructions":["Attach a short straight bar to a low pulley. Stand facing the stack, hold the bar with a shoulder-width overhand grip, and keep your wrists straight.","Keeping your upper arms beside your torso, bend your elbows and curl the bar toward your lower chest without swinging your body.","Lower the bar slowly until your elbows are nearly straight, maintaining the overhand grip and steady cable tension."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/cable-reverse-curl.webp"]}},{"id":"atlas-cable-romanian-deadlift","name":"Romanian Deadlift (Cable)","equipment":"cable","primaryMuscles":["hamstrings","glutes"],"secondaryMuscles":["lower_back"],"category":"compound","instructions":["Attach a straight bar to the low pulley and face the stack. Hold the bar against the front of your thighs with feet hip-width apart and knees softly bent.","Push your hips backward and hinge forward while keeping your spine long and the bar close to your legs; lower until you feel a comfortable hamstring stretch.","Press through your feet and extend your hips to stand. Keep the knees softly bent, avoid rounding your back, and do not lean backward at the top."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/cable-romanian-deadlift.webp"]}},{"id":"atlas-cable-rope-rear-delt-row","name":"Rope Rear-Delt Row (Cable)","equipment":"cable","primaryMuscles":["shoulders"],"secondaryMuscles":["back","traps","biceps"],"category":"compound","instructions":["Attach a rope to a high pulley and stand facing it in a stable staggered stance. Step back until the cable is taut, then hold both rope ends with your arms reaching forward.","Keep your torso upright and shoulders away from your ears. Row the rope toward your upper chest while driving your elbows out to the sides at about shoulder height.","Pause briefly without leaning back, then extend your arms forward under control to return to the start."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/cable-rope-rear-delt-row.webp"]}},{"id":"atlas-cable-shotgun-row","name":"Shotgun Row (Cable)","equipment":"cable","primaryMuscles":["lats"],"secondaryMuscles":["back","biceps","shoulders","traps","abs"],"category":"compound","instructions":["Attach a single handle to a low pulley. Face the stack in a split stance with the working-side foot forward, hinge slightly, and brace your free hand on the forward thigh; let the working arm reach toward the pulley.","Keep your hips and torso steady as you draw the shoulder blade back and row the handle toward your lower ribs, driving the elbow close behind you.","Extend your arm forward slowly to return to the start without twisting your torso, then repeat on the other side."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/cable-shotgun-row.webp"]}},{"id":"atlas-cable-shoulder-press","name":"Shoulder Press (Cable)","equipment":"cable","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps"],"category":"compound","instructions":["Set both pulleys low, attach one handle to each, and stand centered between the stacks with a handle at each shoulder; keep your feet about shoulder-width apart and brace your trunk.","Press both handles overhead in a controlled path, keeping your wrists above your elbows and your torso upright without arching your lower back.","Lower the handles slowly to shoulder height without shrugging, then repeat."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/cable-shoulder-press.webp"]}},{"id":"atlas-cable-shrug","name":"Cable Shrug","equipment":"cable","primaryMuscles":["traps"],"secondaryMuscles":["forearms"],"category":"isolation","instructions":["Attach a straight bar to a low pulley and stand tall holding it in front of your thighs.","Raise your shoulders toward your ears without bending your elbows or rolling your shoulders.","Lower your shoulders slowly while keeping the cable under control."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/cable-shrug.webp"]}},{"id":"atlas-cable-triceps-kickback","name":"Triceps Kickback (Cable)","equipment":"cable","primaryMuscles":["triceps"],"secondaryMuscles":[],"category":"isolation","instructions":["Set a single handle to a low pulley. Hinge slightly and brace your free hand on your thigh; keep the working upper arm beside your torso.","Straighten your elbow to move the handle back until the arm is nearly straight; keep the shoulder and upper arm still.","Bend your elbow slowly to return, then complete the same number of repetitions on the other side."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/cable-triceps-kickback.webp"]}},{"id":"atlas-cable-upright-row","name":"Upright Row (Cable)","equipment":"cable","primaryMuscles":["traps"],"secondaryMuscles":["shoulders"],"category":"compound","instructions":["Attach a straight bar to the lowest pulley and stand close to the stack with an overhand grip; begin with the bar in front of your thighs, feet about shoulder-width apart.","Keep your torso upright and pull the bar close to your body, leading with your elbows; stop around mid-chest or shoulder height, whichever feels comfortable.","Lower the bar slowly to the start. Keep your elbows at or below shoulder level, and stop if the movement causes shoulder pinching or pain."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/cable-upright-row.webp"]}},{"id":"atlas-cable-woodchop","name":"Cable Woodchop","equipment":"cable","primaryMuscles":["abs"],"secondaryMuscles":["shoulders"],"category":"compound","instructions":["Set the cable above head height and grip the handle with both hands; set your feet balanced.","Keeping your arms slightly bent, rotate your torso diagonally downward in a controlled way; keep your hips still.","Return to the start slowly; do not swing the movement from your lower back and work both sides equally."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/cable-woodchop.webp"]}},{"id":"atlas-cable-wrist-curl","name":"Wrist Curl (Cable)","equipment":"cable","primaryMuscles":["forearms"],"secondaryMuscles":[],"category":"isolation","instructions":["Attach a short bar to a low pulley; support your forearms on your thighs and turn your palms up.","Without moving your forearms, raise the bar slightly by bending your wrists.","Lower the bar under control; stop the movement if you feel wrist pain."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/cable-wrist-curl.webp"]}},{"id":"atlas-cable-wrist-extension","name":"Wrist Extension (Cable)","equipment":"cable","primaryMuscles":["forearms"],"secondaryMuscles":[],"category":"isolation","instructions":["Attach a short bar to a low pulley; support your forearms on your thighs and turn your palms down.","With your forearms still, extend your wrists backward.","Lower the bar slowly; work within a small, pain-free range."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/cable-wrist-extension.webp"]}},{"id":"atlas-cable-y-raise","name":"Y Raise (Cable)","equipment":"cable","primaryMuscles":["shoulders"],"secondaryMuscles":["traps"],"category":"isolation","instructions":["Hold the two low cables crossed; start with your arms slightly bent in front of your torso.","Raise your arms up and out under control to form a Y shape; keep your shoulders away from your ears.","Lower the weights slowly to the start; use a light load and do not lean back."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/cable-y-raise.webp"]}},{"id":"atlas-calf-raise","name":"Standing Calf Raise","equipment":"bodyweight","primaryMuscles":["calves"],"secondaryMuscles":[],"category":"isolation","isBodyweight":true,"instructions":["Place the balls of the feet on a low, stable step and hold a support for balance.","Lower the heels through a comfortable range of motion.","Rise up onto the toes, pause briefly at the top and lower slowly."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/calf-raise.webp"]}},{"id":"atlas-captains-chair-knee-raise","name":"Captain's Chair Knee Raise","equipment":"other","primaryMuscles":["abs"],"secondaryMuscles":[],"category":"compound","instructions":["Rest your forearms on the pads and your back against the support; let your legs hang without swinging.","Brace your abdomen and draw both bent knees toward your torso in a controlled lift.","Lower your legs slowly to the start; shorten the range if you need to swing or feel discomfort."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/captains-chair-knee-raise.webp"]}},{"id":"atlas-cat-cow","name":"Cat-Cow","equipment":"bodyweight","primaryMuscles":["lower_back"],"secondaryMuscles":[],"category":"mobility","isBodyweight":true,"instructions":["Start on hands and knees with wrists below shoulders and knees below hips.","Gently round the spine and let the head follow without forcing the neck.","Slowly move into a comfortable, mild spinal extension, then return; avoid pushing into pain."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/cat-cow.webp"]}},{"id":"atlas-chest-supported-dumbbell-shrug","name":"Chest-Supported Shrug (Dumbbell)","equipment":"dumbbell","primaryMuscles":["traps"],"secondaryMuscles":["back"],"category":"isolation","instructions":["Lie face down on an incline bench and hold light dumbbells with your arms hanging down.","Without bending your elbows, raise your shoulders toward your ears under control.","Pause briefly and slowly lower your shoulders; do not strain your neck and do not swing the dumbbells."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/chest-supported-dumbbell-shrug.webp"]}},{"id":"atlas-childs-pose","name":"Child's Pose","equipment":"bodyweight","primaryMuscles":["lower_back"],"secondaryMuscles":["lats","glutes"],"category":"mobility","isBodyweight":true,"instructions":["Start on hands and knees on a mat with hands comfortably forward.","Gently shift your hips toward your heels and reach your arms ahead until you feel an easy stretch through your back.","Breathe slowly, return to hands and knees, and stay within a comfortable range."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/childs-pose.webp"]}},{"id":"atlas-chin-tuck","name":"Chin Tuck","equipment":"bodyweight","primaryMuscles":["neck"],"secondaryMuscles":[],"category":"isolation","isBodyweight":true,"instructions":["Sit upright and look straight ahead; relax your shoulders and keep your head neutral.","Without tilting your chin down, slide your head straight back in a line; make a small double-chin movement.","Hold briefly and release; repeat without forcing the movement and stop if you feel pain, numbness or dizziness."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/chin-tuck.webp"]}},{"id":"atlas-close-grip-dumbbell-press","name":"Close-Grip Press (Dumbbell)","equipment":"dumbbell","primaryMuscles":["triceps"],"secondaryMuscles":["chest","shoulders"],"category":"compound","instructions":["Lie on a flat bench with feet planted. Hold a pair of light dumbbells together over the lower chest with palms facing each other and elbows close to your sides.","Keep the dumbbells in gentle contact as you lower them under control to the lower chest; do not flare the elbows.","Press the dumbbells back up while keeping them together, then stop just short of locking the elbows."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/close-grip-dumbbell-press.webp"]}},{"id":"atlas-close-grip-front-lat-pulldown","name":"Close-Grip Front Lat Pulldown (Cable)","equipment":"cable","primaryMuscles":["lats"],"secondaryMuscles":["biceps","back"],"category":"compound","instructions":["Attach a close-grip V bar to the high pulley; secure the thigh pad and grip the handle.","Keeping your torso upright, pull your elbows down and close to your body; bring the bar to your upper chest.","Extend your arms under control; do not pull the bar behind your neck and do not swing your torso."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/close-grip-front-lat-pulldown.webp"]}},{"id":"atlas-close-grip-machine-chest-press","name":"Close-Grip Chest Press (Machine)","equipment":"machine","primaryMuscles":["triceps"],"secondaryMuscles":["chest","shoulders"],"category":"compound","instructions":["Adjust the seat so the close-grip handles begin near mid-chest; plant your feet and keep your back on the pad.","Press the handles forward with elbows close to your sides, stopping before locking them.","Let the handles return slowly until your elbows bend comfortably; keep your shoulders from rolling forward."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/close-grip-machine-chest-press.webp"]}},{"id":"atlas-close-grip-push-up","name":"Close-Grip Push-Up","equipment":"bodyweight","primaryMuscles":["triceps"],"secondaryMuscles":["chest","shoulders"],"category":"compound","isBodyweight":true,"instructions":["Get into a plank position with your hands at shoulder width or slightly narrower; keep your body straight.","Keeping your elbows close to your torso, lower your chest toward the floor under control.","Push the floor away to return to the start; if needed, put your knees on the floor and keep your wrists in a pain-free position."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/close-grip-push-up.webp"]}},{"id":"atlas-cossack-squat","name":"Cossack Squat","equipment":"bodyweight","primaryMuscles":["adductors"],"secondaryMuscles":["quads","glutes"],"category":"compound","isBodyweight":true,"instructions":["Set your feet wide apart; if needed, lightly hold a stable support for balance.","Send your hips to one side and bend that knee; keep the other leg comfortably straight.","Push through your foot to return to the center and move to the other side; stay in a pain-free, controllable depth."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/cossack-squat.webp"]}},{"id":"atlas-cross-body-cable-triceps-extension","name":"Cross-Body Triceps Extension (Cable)","equipment":"cable","primaryMuscles":["triceps"],"secondaryMuscles":["shoulders"],"category":"isolation","instructions":["Attach a single handle to a high pulley and grip it with your working hand; keep your elbow at your side.","Extend your forearm under control across your body and downward.","Return to the start with your elbow fixed; do not rotate your shoulder, and stop if you feel pain."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/cross-body-cable-triceps-extension.webp"]}},{"id":"atlas-cross-body-hammer-curl","name":"Cross-Body Hammer Curl","equipment":"dumbbell","primaryMuscles":["biceps"],"secondaryMuscles":["forearms"],"category":"isolation","instructions":["Hold the dumbbells with your palms facing each other; keep your elbows fixed at your sides.","Raise one dumbbell across the front of your torso toward the opposite shoulder; do not rotate your wrist.","Lower the weight under control and repeat with the other arm; do not round your shoulder forward."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/cross-body-hammer-curl.webp"]}},{"id":"atlas-cuban-press","name":"Cuban Press","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":["traps"],"category":"compound","instructions":["Hold very light dumbbells and bend your elbows at shoulder height; spread your upper arms out to the sides.","Keeping the elbow angle, slowly rotate your forearms upward; progress only within a comfortable range.","Return to the start under control; use a very light load in this movement and stop if your shoulder is uncomfortable."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/cuban-press.webp"]}},{"id":"atlas-cyclist-squat","name":"Cyclist Squat","equipment":"other","primaryMuscles":["quads"],"secondaryMuscles":["glutes"],"category":"compound","instructions":["Place the heels on a low, stable raised surface and set the feet in a narrow, balanced stance.","Keeping the torso upright, squat to a comfortable depth while the knees track in line with the toes.","Push through the soles of the feet to stand up under control; reduce the depth if you feel knee pain."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/cyclist-squat.webp"]}},{"id":"atlas-dead-hang","name":"Dead Hang","equipment":"bodyweight","primaryMuscles":["forearms"],"secondaryMuscles":["lats","traps"],"category":"compound","isBodyweight":true,"instructions":["Grip a secure pull-up bar with hands about shoulder-width apart and feet off the floor.","Hang with straight elbows and breathe steadily; keep the shoulders comfortable.","Step down safely before your grip gives out."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/dead-hang.webp"]}},{"id":"atlas-decline-dumbbell-fly","name":"Decline Fly (Dumbbell)","equipment":"dumbbell","primaryMuscles":["chest"],"secondaryMuscles":["shoulders"],"category":"compound","instructions":["Secure your feet under the decline bench pads and lie back with a light dumbbell in each hand above your chest; keep a small bend in your elbows.","Lower both arms outward in a wide arc until the dumbbells reach a comfortable chest-level stretch; keep the elbow bend steady.","Bring the dumbbells back above your chest by drawing your arms together; use a manageable load and avoid forcing the shoulder range."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/decline-dumbbell-fly.webp"]}},{"id":"atlas-decline-dumbbell-press","name":"Decline Press (Dumbbell)","equipment":"dumbbell","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"category":"compound","instructions":["Secure your feet safely on the declined bench and hold the dumbbells at the lower sides of your chest.","Press the dumbbells up over your chest under control; keep your wrists above your elbows.","Slowly lower the dumbbells to the sides of your chest; get help to put them down if needed."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/decline-dumbbell-press.webp"]}},{"id":"atlas-decline-dumbbell-triceps-extension","name":"Decline Triceps Extension (Dumbbell)","equipment":"dumbbell","primaryMuscles":["triceps"],"secondaryMuscles":["forearms"],"category":"isolation","instructions":["Set a decline bench to a mild angle, secure your feet beneath the pads, and lie back holding a light dumbbell in each hand above your shoulders with palms facing each other.","Keep your upper arms steady and bend your elbows to lower the dumbbells in a curved path beside your ears. Use a range you can control comfortably.","Extend your elbows to raise the dumbbells back over your shoulders without swinging or locking forcefully."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/decline-dumbbell-triceps-extension.webp"]}},{"id":"atlas-decline-ez-bar-triceps-extension","name":"Decline Triceps Extension (EZ Bar)","equipment":"barbell","primaryMuscles":["triceps"],"secondaryMuscles":["forearms"],"category":"isolation","instructions":["Lie on a decline bench with your feet secured and hold a manageable EZ bar above your chest using a narrow overhand grip.","Keep your upper arms steady and bend your elbows to lower the bar toward your forehead, stopping before it touches your head.","Extend your elbows to raise the bar back above your chest. Keep the motion controlled and avoid flaring your elbows."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/decline-ez-bar-triceps-extension.webp"]}},{"id":"atlas-decline-push-up","name":"Decline Push-Up","equipment":"bodyweight","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"category":"compound","isBodyweight":true,"instructions":["Place your feet on a sturdy bench and your hands on the floor at shoulder width; keep your body straight.","Bend your elbows under control and bring your chest toward the floor.","Push the floor away and return to the start; if your lower back sags, choose a lower elevation."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/decline-push-up.webp"]}},{"id":"atlas-decline-sit-up","name":"Decline Sit-Up","equipment":"bodyweight","primaryMuscles":["abs"],"secondaryMuscles":[],"category":"compound","isBodyweight":true,"instructions":["Secure your feet safely to the decline bench; cross your arms over your chest.","Brace your abs and raise your torso toward your knees; do not pull your neck with your hands.","Lower your torso to the bench in a controlled way; do not work at a depth that strains your lower back."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/decline-sit-up.webp"]}},{"id":"atlas-deficit-deadlift","name":"Deficit Deadlift","equipment":"barbell","primaryMuscles":["glutes","quads"],"secondaryMuscles":["hamstrings","lower_back"],"category":"compound","instructions":["Stand on a low, stable platform with the bar over mid-foot; hinge down and grip the bar with a neutral spine.","Brace and lift the bar close to the legs by extending the knees and hips together.","Lower the bar under control; use a light load and reduce the platform height if you cannot keep your back position."],"formCues":[],"media":{}},{"id":"atlas-deficit-push-up","name":"Deficit Push-Up","equipment":"other","primaryMuscles":["chest"],"secondaryMuscles":["triceps","shoulders"],"category":"compound","instructions":["Place sturdy push-up handles at shoulder width and take a plank position.","Bend your elbows under control and lower your chest slightly below the level of your hands; keep your body straight.","Push up from a depth that is pain-free and that you can control; if you feel discomfort in your shoulders, shorten the range of motion."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/deficit-push-up.webp"]}},{"id":"atlas-donkey-calf-raises","name":"Donkey Calf Raises","equipment":"other","primaryMuscles":["calves"],"secondaryMuscles":[],"category":"isolation","instructions":["Place the toes on a stable raised surface and support yourself with the hands on a sturdy bench; hinge forward at the hips.","Lower the heels within a comfortable range, then rise up onto the toes.","Pause briefly at the top and lower slowly; do not bounce or let go of the balance support."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/donkey-calf-raises.webp"]}},{"id":"atlas-donkey-kick","name":"Donkey Kick","equipment":"bodyweight","primaryMuscles":["glutes"],"secondaryMuscles":["hamstrings"],"category":"isolation","isBodyweight":true,"instructions":["Get on your hands and knees; stabilise the torso and keep the neck neutral.","Keeping one knee bent, lift the foot toward the ceiling without arching the lower back.","Bring the knee back toward the floor under control and switch sides; keep the hip movement small and balanced."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/donkey-kick.webp"]}},{"id":"atlas-double-kettlebell-front-squat","name":"Double Kettlebell Front Squat","equipment":"kettlebell","primaryMuscles":["quads","glutes"],"secondaryMuscles":["hamstrings","back"],"category":"compound","instructions":["Clean or safely bring one kettlebell to each shoulder. Hold both in the front rack with wrists neutral, elbows close, feet about shoulder-width, and trunk braced.","Bend the hips and knees to squat under control. Keep the torso upright, heels grounded, knees tracking with the toes, and bells steady at the shoulders.","Drive through the whole foot to stand. Use a load you can rack securely, and return the kettlebells to the floor with control."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/double-kettlebell-front-squat.webp"]}},{"id":"atlas-dumbbell-around-the-worlds","name":"Around the Worlds (Dumbbell)","equipment":"dumbbell","primaryMuscles":["chest"],"secondaryMuscles":["shoulders"],"category":"compound","instructions":["Lie on a flat bench with feet planted; hold a light dumbbell in each hand beside your hips, palms up, with a small bend in your elbows.","Keeping that elbow bend, sweep both arms outward and in a broad arc toward an overhead position; stop within a comfortable shoulder range.","Reverse the arc slowly and return the dumbbells beside your hips; keep your torso steady and use light weights."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/dumbbell-around-the-worlds.webp"]}},{"id":"atlas-dumbbell-bent-over-row","name":"Bent-Over Row (Dumbbell)","equipment":"dumbbell","primaryMuscles":["back"],"secondaryMuscles":["lats","biceps","shoulders"],"category":"compound","instructions":["Hinge forward with a dumbbell in each hand and let the arms hang beneath your shoulders.","Keeping your back neutral, row both weights toward your lower ribs with elbows close to your sides.","Lower the dumbbells slowly to the start without rounding your back."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/dumbbell-bent-over-row.webp"]}},{"id":"atlas-dumbbell-deadlift","name":"Dumbbell Deadlift","equipment":"dumbbell","primaryMuscles":["glutes","hamstrings"],"secondaryMuscles":["quads","lower_back","forearms"],"category":"compound","instructions":["Stand hip-width with one dumbbell outside each foot. Hinge and bend the knees to grasp the handles, brace your trunk, and keep your back neutral.","Push through the floor and extend your hips and knees together, keeping the dumbbells close to your legs as you stand.","Send your hips back and bend your knees to lower both dumbbells under control beside your feet; reset your brace before the next repetition."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/dumbbell-deadlift.webp"]}},{"id":"atlas-dumbbell-forearm-pronation-supination","name":"Forearm Pronation-Supination (Dumbbell)","equipment":"dumbbell","primaryMuscles":["forearms"],"secondaryMuscles":[],"category":"isolation","instructions":["Sit and rest your forearm on your thigh or a bench; hold a very light dumbbell by one end.","Keeping your elbow fixed, slowly turn your palm up, then down.","Return to the start under control; reduce the range or stop if your wrist hurts."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/dumbbell-forearm-pronation-supination.webp"]}},{"id":"atlas-dumbbell-forward-lunge","name":"Forward Lunge (Dumbbell)","equipment":"dumbbell","primaryMuscles":["quads","glutes"],"secondaryMuscles":["hamstrings","abs"],"category":"compound","instructions":["Stand tall with a dumbbell at each side and feet about hip-width apart.","Step one foot forward and lower under control, keeping the front foot flat and the front knee aligned with the toes.","Push through the front foot to return to standing, then change sides. Keep both dumbbells hanging at your sides."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/dumbbell-forward-lunge.webp"]}},{"id":"atlas-dumbbell-front-squat","name":"Front Squat (Dumbbell)","equipment":"dumbbell","primaryMuscles":["quads","glutes"],"secondaryMuscles":["hamstrings","back"],"category":"compound","instructions":["Stand about shoulder-width with toes slightly turned out. Hold a dumbbell at each shoulder, palms facing inward, elbows lifted, and brace your trunk.","Bend the hips and knees to lower under control, keeping the dumbbells at shoulder height, chest lifted, heels down, and knees tracking with the toes.","Press through the whole foot to stand tall; keep the torso upright and elbows lifted throughout."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/dumbbell-front-squat.webp"]}},{"id":"atlas-dumbbell-hip-thrust","name":"Hip Thrust (Dumbbell)","equipment":"dumbbell","primaryMuscles":["glutes"],"secondaryMuscles":["hamstrings","abs"],"category":"compound","instructions":["Sit with your upper back against the edge of a stable bench, knees bent and feet planted about hip-width apart. Hold one dumbbell securely across your hip crease; use a pad if needed.","Brace your trunk and press through your feet to lift your hips until your torso and thighs form a straight line. Keep your ribs down and avoid arching your lower back.","Lower your hips under control without letting the dumbbell roll, then repeat."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/dumbbell-hip-thrust.webp"]}},{"id":"atlas-dumbbell-kickstand-romanian-deadlift","name":"Kickstand Romanian Deadlift (Dumbbell)","equipment":"dumbbell","primaryMuscles":["hamstrings"],"secondaryMuscles":["glutes","lower_back"],"category":"compound","instructions":["Hold a dumbbell in each hand, stagger the feet and place most weight on the front foot.","Soften the front knee and push hips back, lowering weights near the leg.","Drive through the front foot and stand; keep the rear foot light."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/dumbbell-kickstand-romanian-deadlift.webp"]}},{"id":"atlas-dumbbell-lateral-lunge","name":"Lateral Lunge (Dumbbell)","equipment":"dumbbell","primaryMuscles":["adductors"],"secondaryMuscles":["quads","glutes"],"category":"compound","instructions":["Hold one dumbbell close to your chest and stand with feet under your hips.","Step wide to one side, bend that knee and send your hips back while the other leg stays long.","Push through the bent leg to return to standing, then repeat on the other side."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/dumbbell-lateral-lunge.webp"]}},{"id":"atlas-dumbbell-neutral-grip-bench-press","name":"Neutral-Grip Bench Press (Dumbbell)","equipment":"dumbbell","primaryMuscles":["chest"],"secondaryMuscles":["triceps","shoulders"],"category":"compound","instructions":["Lie on a flat bench with your feet planted; hold one dumbbell in each hand above the chest with palms facing each other.","Lower the dumbbells beside the chest with elbows comfortably close to the torso, keeping wrists straight.","Press the weights above the mid-chest without letting them collide or forcefully locking the elbows, then lower under control."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/dumbbell-neutral-grip-bench-press.webp"]}},{"id":"atlas-dumbbell-power-clean","name":"Power Clean (Dumbbell)","equipment":"dumbbell","primaryMuscles":["glutes","quads","traps"],"secondaryMuscles":["hamstrings","shoulders","abs"],"category":"compound","instructions":["Stand with your feet about hip-width apart and the dumbbells just outside your feet; bend at the hips and knees, keep your back neutral, and grip both weights.","Push through the floor and extend your hips and knees quickly while keeping the dumbbells close; pull under and catch them at your shoulders in a partial squat with elbows forward.","Stand tall with the dumbbells secure at the shoulders, then lower them to the floor under control."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/dumbbell-power-clean.webp"]}},{"id":"atlas-dumbbell-push-press","name":"Push Press (Dumbbell)","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":["quads","glutes","traps"],"category":"compound","instructions":["Stand with dumbbells at shoulder height and feet hip-width apart.","Dip a few inches by bending the knees, then drive through the floor and press overhead.","Lower to the shoulders and reset before the next repetition."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/dumbbell-push-press.webp"]}},{"id":"atlas-dumbbell-radial-deviation","name":"Radial Deviation (Dumbbell)","equipment":"dumbbell","primaryMuscles":["forearms"],"secondaryMuscles":[],"category":"isolation","instructions":["Rest your forearm on a bench with your wrist hanging off the edge; hold a light dumbbell upright.","Without moving your forearm, raise your wrist in the direction of your thumb through a small range.","Lower the dumbbell slowly to the start; work with a light load and stop if you feel wrist pain."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/dumbbell-radial-deviation.webp"]}},{"id":"atlas-dumbbell-renegade-row","name":"Renegade Row (Dumbbell)","equipment":"dumbbell","primaryMuscles":["lats"],"secondaryMuscles":["back","abs","biceps"],"category":"compound","instructions":["Grip two stable dumbbells in a high plank with feet wide.","Keep hips level and row one weight to the lower ribs.","Lower steadily and change arms; use a manageable load."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/dumbbell-renegade-row.webp"]}},{"id":"atlas-dumbbell-reverse-wrist-curl","name":"Reverse Wrist Curl (Dumbbell)","equipment":"dumbbell","primaryMuscles":["forearms"],"secondaryMuscles":[],"category":"isolation","instructions":["Sit and rest your forearm on your thigh; hold the dumbbell with your palm facing down.","Keeping your forearm still, raise the back of your hand upward in a controlled way.","Lower your wrist slowly; use a small, comfortable range of motion."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/dumbbell-reverse-wrist-curl.webp"]}},{"id":"atlas-dumbbell-scaption","name":"Dumbbell Scaption","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":[],"category":"isolation","instructions":["Stand tall with a light dumbbell in each hand at your sides, palms facing inward and thumbs pointing forward or slightly up; keep a soft bend in your elbows.","Keeping your torso still and shoulders relaxed, raise both arms diagonally forward from your sides to about shoulder height.","Lower the dumbbells slowly along the same path; avoid shrugging or arching your back."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/dumbbell-scaption.webp"]}},{"id":"atlas-dumbbell-seated-box-jump","name":"Seated Box Jump (Dumbbell)","equipment":"dumbbell","primaryMuscles":["quads"],"secondaryMuscles":["glutes","hamstrings","calves"],"category":"compound","instructions":["Sit tall on a stable bench facing a low, sturdy target box. Hold a very light dumbbell in each hand at your sides and plant both feet firmly on the floor.","Brace your trunk and lean forward slightly without rocking back. Drive through both feet and jump onto the box, keeping the dumbbells controlled at your sides.","Land with both feet fully supported and knees and hips softly bent. Stand tall, step down carefully, and return to the seated start before repeating."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/dumbbell-seated-box-jump.webp"]}},{"id":"atlas-dumbbell-seated-one-leg-calf-raise","name":"Seated One-Leg Calf Raise (Dumbbell)","equipment":"dumbbell","primaryMuscles":["calves"],"secondaryMuscles":[],"category":"isolation","instructions":["Sit near the end of a bench and place the ball of one foot on a stable step, with the heel free; keep the other foot comfortably grounded.","Rest one dumbbell securely on the working thigh just above the knee and hold it steady. Lower the heel toward the floor without letting it touch.","Raise the heel as high as comfortable, pause briefly, then lower under control; finish the side and switch legs."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/dumbbell-seated-one-leg-calf-raise.webp"]}},{"id":"atlas-dumbbell-side-bend","name":"Side Bend (Dumbbell)","equipment":"dumbbell","primaryMuscles":["abs"],"secondaryMuscles":["forearms"],"category":"compound","instructions":["Stand tall with one dumbbell at your side and the other hand resting on your thigh.","Slide the dumbbell down the outside of your leg with a small side bend; keep your chest facing forward.","Use your obliques to return upright without twisting or leaning forward."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/dumbbell-side-bend.webp"]}},{"id":"atlas-dumbbell-skull-crusher","name":"Skull Crusher (Dumbbell)","equipment":"dumbbell","primaryMuscles":["triceps"],"secondaryMuscles":[],"category":"isolation","instructions":["Lie on a bench and hold light dumbbells above your chest; straighten your arms.","Keeping your upper arms still, bend your elbows and lower the dumbbells toward the sides of your head.","Extend your elbows under control to return to the start; do not bring the weight close to your head and stay in a comfortable range."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/dumbbell-skull-crusher.webp"]}},{"id":"atlas-dumbbell-snatch","name":"Dumbbell Snatch","equipment":"dumbbell","primaryMuscles":["glutes","quads","shoulders"],"secondaryMuscles":["hamstrings","traps","abs"],"category":"compound","instructions":["Stand with feet about hip-width and place one dumbbell between them; hinge at the hips and bend your knees to grasp the handle with one hand.","Drive through the floor and extend your hips and knees, keeping the dumbbell close as you lift it overhead in one continuous motion.","Finish standing tall with the dumbbell over the middle of your body, then lower it under control to the floor before switching hands."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/dumbbell-snatch.webp"]}},{"id":"atlas-dumbbell-split-squat","name":"Split Squat (Dumbbell)","equipment":"dumbbell","primaryMuscles":["quads","glutes"],"secondaryMuscles":["hamstrings"],"category":"compound","instructions":["Hold a dumbbell at each side and take a stable split stance with both feet on the floor.","Bend both knees to lower under control; keep the front foot planted and the front knee in line with the toes.","Press through the front foot to rise without stepping; complete the set, then switch legs."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/dumbbell-split-squat.webp"]}},{"id":"atlas-dumbbell-squat","name":"Dumbbell Squat","equipment":"dumbbell","primaryMuscles":["quads","glutes"],"secondaryMuscles":["hamstrings","lower_back"],"category":"compound","instructions":["Stand about shoulder-width with a dumbbell hanging at each side; brace your trunk and keep your spine steady.","Bend your hips and knees to lower under control, keeping your heels grounded and knees tracking in line with your feet.","Press through your feet to stand tall again; keep the dumbbells by your sides and avoid bouncing at the bottom."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/dumbbell-squat.webp"]}},{"id":"atlas-dumbbell-squeeze-press","name":"Squeeze Press (Dumbbell)","equipment":"dumbbell","primaryMuscles":["chest"],"secondaryMuscles":["triceps","shoulders"],"category":"compound","instructions":["Lie on a flat bench and hold light dumbbells over your chest so that they touch each other.","Keep pressing the dumbbells together as you lower them to your chest under control.","Press up from chest level; set your shoulders on the bench and do not attempt this with heavy loads."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/dumbbell-squeeze-press.webp"]}},{"id":"atlas-dumbbell-standing-calf-raise","name":"Standing Calf Raise (Dumbbell)","equipment":"dumbbell","primaryMuscles":["calves"],"secondaryMuscles":[],"category":"isolation","instructions":["Stand tall with feet hip-width apart and hold a manageable dumbbell in each hand at your sides.","Keeping your knees nearly straight and torso steady, press through the balls of both feet to raise your heels as high as comfortable.","Pause briefly, then lower your heels slowly to the floor without bouncing."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/dumbbell-standing-calf-raise.webp"]}},{"id":"atlas-dumbbell-step-up","name":"Step Ups (Dumbbell)","equipment":"dumbbell","primaryMuscles":["quads"],"secondaryMuscles":["glutes"],"category":"compound","instructions":["Stand in front of a sturdy box of a manageable height, holding light dumbbells at your sides.","Place one foot fully on the box and rise with that leg, keeping the knee in line with the toes.","Lower the other foot under control and switch sides; make sure the box is stable."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/dumbbell-step-up.webp"]}},{"id":"atlas-dumbbell-tate-press","name":"Tate Press (Dumbbell)","equipment":"dumbbell","primaryMuscles":["triceps"],"secondaryMuscles":["chest"],"category":"compound","instructions":["Lie on a flat bench with light dumbbells above the chest, elbows bent and pointed outward.","Extend the elbows while keeping the upper arms steady.","Bend the elbows and lower the weights toward the upper chest."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/dumbbell-tate-press.webp"]}},{"id":"atlas-dumbbell-thruster","name":"Dumbbell Thruster","equipment":"dumbbell","primaryMuscles":["quads","glutes"],"secondaryMuscles":["shoulders","triceps"],"category":"compound","instructions":["Hold two dumbbells at shoulder height with feet shoulder-width apart.","Squat to a comfortable depth while keeping the weights steady at your shoulders.","Stand powerfully into an overhead press; lower the weights before the next squat."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/dumbbell-thruster.webp"]}},{"id":"atlas-dumbbell-z-press","name":"Z Press (Dumbbell)","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps"],"category":"compound","instructions":["Sit on the floor with your legs extended in front; find a position where you can keep your torso upright and bring the dumbbells to shoulder height.","Without leaning back from your lower back, press the dumbbells overhead under control.","Lower the weights slowly to your shoulders; reduce the load if your torso drifts backward."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/dumbbell-z-press.webp"]}},{"id":"atlas-elliptical-trainer","name":"Elliptical Trainer","equipment":"machine","primaryMuscles":["quads"],"secondaryMuscles":["calves","glutes","hamstrings","shoulders","biceps"],"category":"cardio","instructions":["Move the nearest pedal to its lowest position, hold the fixed handles, and step onto the pedals one foot at a time. Begin with an easy stride.","Stand tall with feet centered on the platforms and guide the moving arms as they travel opposite your legs; use the fixed handles for balance if needed.","Keep a smooth, comfortable stride. Slow to a controlled stop before stepping off, and wait for the pedals to settle."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/elliptical-trainer.webp"]}},{"id":"atlas-farmers-carry","name":"Farmer Carry","equipment":"dumbbell","primaryMuscles":["traps"],"secondaryMuscles":["forearms","abs"],"category":"compound","instructions":["Pick up weights you can control in each hand and stand tall with the shoulders relaxed back.","Walk with short, balanced steps without leaning to the side.","Put the weights down safely; do not shrug and make sure the path is clear."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/farmers-carry.webp"]}},{"id":"atlas-floor-crunch","name":"Floor Crunch","equipment":"bodyweight","primaryMuscles":["abs"],"secondaryMuscles":[],"category":"compound","isBodyweight":true,"instructions":["Lie on your back, bend your knees and plant your feet flat on the floor.","Brace your abs and lift your shoulder blades off the floor in a controlled way; do not pull your neck with your hands.","Pause briefly and slowly lower your torso back to the starting position."],"formCues":[],"media":{}},{"id":"atlas-flutter-kicks","name":"Flutter Kicks","equipment":"bodyweight","primaryMuscles":["abs"],"secondaryMuscles":[],"category":"compound","isBodyweight":true,"instructions":["Lie on your back with legs extended and hands beside your hips; brace your trunk and keep your lower back gently supported.","Lift both heels slightly, then alternate raising and lowering each leg in a small, controlled range.","Keep the movement smooth and stop or shorten the range if your lower back starts to arch."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/flutter-kicks.webp"]}},{"id":"atlas-forward-lunge","name":"Forward Lunge","equipment":"bodyweight","primaryMuscles":["quads","glutes"],"secondaryMuscles":["hamstrings","abs"],"category":"compound","isBodyweight":true,"instructions":["Stand tall with feet about hip-width apart, brace your trunk, and keep your shoulders relaxed.","Step one foot forward, plant it flat, and lower under control until both knees bend comfortably; keep the front knee tracking in line with the toes.","Push through the front foot to return to standing, then repeat on the other side. Keep your balance and use a comfortable range."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/forward-lunge.webp"]}},{"id":"atlas-frog-pump","name":"Frog Pump","equipment":"bodyweight","primaryMuscles":["glutes"],"secondaryMuscles":["hamstrings"],"category":"compound","isBodyweight":true,"instructions":["Lie on your back, press the soles of the feet together and let the knees fall comfortably to the sides.","Brace the abdomen slightly and lift the hips off the floor without over-arching the lower back.","Squeeze the glutes and hold briefly at the top, then lower to the floor under control."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/frog-pump.webp"]}},{"id":"atlas-front-foot-elevated-split-squat","name":"Front-Foot-Elevated Split Squat","equipment":"bodyweight","primaryMuscles":["quads"],"secondaryMuscles":["glutes"],"category":"compound","isBodyweight":true,"instructions":["Place your front foot fully on a low, stable step and take a long split stance.","Lower by bending both knees while keeping the front heel grounded.","Press through the front foot to stand; use a range you can control."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/front-foot-elevated-split-squat.webp"]}},{"id":"atlas-full-copenhagen-plank","name":"Full Copenhagen Plank","equipment":"bodyweight","primaryMuscles":["adductors"],"secondaryMuscles":["abs"],"category":"compound","isBodyweight":true,"instructions":["Get into a side plank position; place your top ankle on a sturdy bench and align your elbow under your shoulder.","Lift your hips to form a straight line from head to ankle; raise your bottom leg off the floor.","Hold the position briefly and in control, then lower; work both sides and release if you feel pain in the groin."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/full-copenhagen-plank.webp"]}},{"id":"atlas-glute-bridge","name":"Glute Bridge","equipment":"bodyweight","primaryMuscles":["glutes"],"secondaryMuscles":["hamstrings"],"category":"compound","isBodyweight":true,"instructions":["Lie on the back with knees bent and feet planted.","Lift the hips until the torso and thighs align, then lower."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/glute-bridge.webp"]}},{"id":"atlas-glute-bridge-march","name":"Glute Bridge March","equipment":"bodyweight","primaryMuscles":["glutes"],"secondaryMuscles":["abs","hamstrings"],"category":"compound","isBodyweight":true,"instructions":["Lie on a mat with knees bent and feet planted hip-width apart; lift the hips into a bridge.","Brace the abdomen and lift one foot a few inches while keeping the pelvis level.","Set the foot down, alternate sides, and lower the hips after the set; shorten the march if the hips wobble."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/glute-bridge-march.webp"]}},{"id":"atlas-glute-ham-raise","name":"Glute-Ham Raise (Machine)","equipment":"machine","primaryMuscles":["hamstrings"],"secondaryMuscles":["glutes"],"category":"compound","instructions":["Adjust the glute-ham developer so your knees rest on the pad and ankles are securely held.","Keep hips extended as you lower your torso forward, then curl back up using your hamstrings.","Use assistance or a shorter range if needed; avoid dropping quickly into the bottom."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/glute-ham-raise.webp"]}},{"id":"atlas-half-kneeling-band-chest-press","name":"Half-Kneeling Band Chest Press","equipment":"band","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"category":"compound","instructions":["Kneel with one knee down; anchor a band behind you at chest height and hold it beside your chest.","Brace your trunk and press forward without turning your torso.","Bend the elbow slowly and return; repeat, then switch sides."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/half-kneeling-band-chest-press.webp"]}},{"id":"atlas-half-kneeling-band-lat-pulldown","name":"Half-Kneeling Band Lat Pulldown","equipment":"band","primaryMuscles":["lats"],"secondaryMuscles":["biceps","back"],"category":"compound","instructions":["Anchor the band above head height; kneel on one knee and grip the band with one hand.","Pull your elbow toward your ribs; keep your torso upright and still.","Extend your arm back up under control; work both sides."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/half-kneeling-band-lat-pulldown.webp"]}},{"id":"atlas-half-kneeling-landmine-press","name":"Half-Kneeling Landmine Press","equipment":"barbell","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps","abs"],"category":"compound","instructions":["Set one knee down with the opposite foot forward and hold the bar end at shoulder height on that side.","Brace your trunk and press diagonally upward, keeping your ribs stacked over your pelvis.","Lower with control and complete the set before switching sides."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/half-kneeling-landmine-press.webp"]}},{"id":"atlas-half-kneeling-single-arm-dumbbell-press","name":"Half-Kneeling Single-Arm Press (Dumbbell)","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps","abs"],"category":"compound","instructions":["Kneel on one knee with the other foot planted; hold a dumbbell at the shoulder on the kneeling side.","Brace your trunk and press overhead without leaning or rotating.","Lower with control; finish the set and switch sides."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/half-kneeling-single-arm-dumbbell-press.webp"]}},{"id":"atlas-hamstring-walkout","name":"Hamstring Walkout","equipment":"bodyweight","primaryMuscles":["hamstrings"],"secondaryMuscles":["glutes"],"category":"isolation","isBodyweight":true,"instructions":["Lie on your back with the knees bent and the feet close to the hips; lift the hips into a bridge position.","Walk the heels forward in small steps, extending as far as you can while keeping the hips controlled and high.","Walk the heels back with steps and lower the hips; do not arch the lower back."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/hamstring-walkout.webp"]}},{"id":"atlas-hand-gripper-squeeze","name":"Hand Gripper Squeeze","equipment":"other","primaryMuscles":["forearms"],"secondaryMuscles":[],"category":"isolation","instructions":["Hold a hand gripper in one hand with the handles resting in your palm and fingers.","Squeeze until the handles meet or reach your comfortable limit; pause briefly.","Open your hand slowly and use a resistance you can control without pain."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/hand-gripper-squeeze.webp"]}},{"id":"atlas-hand-resisted-neck-isometric","name":"Hand-Resisted Neck Isometric","equipment":"bodyweight","primaryMuscles":["neck"],"secondaryMuscles":[],"category":"isolation","isBodyweight":true,"instructions":["Sit upright and keep your head neutral; lightly place your palm beside your temple.","Apply very light resistance with your hand without turning your head, and gently tense your neck muscles.","Hold briefly and release; stop immediately if you feel sharp pain, numbness or dizziness."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/hand-resisted-neck-isometric.webp"]}},{"id":"atlas-hanging-knee-raise","name":"Hanging Knee Raise","equipment":"other","primaryMuscles":["abs"],"secondaryMuscles":[],"category":"compound","instructions":["Hang from a sturdy bar; move your shoulders away from your ears and keep your torso stable.","Bend your knees, brace your abs and raise your knees toward your chest in a controlled way.","Lower your legs slowly without swinging; perform the movement in a pain-free range."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/hanging-knee-raise.webp"]}},{"id":"atlas-hanging-oblique-knee-raise","name":"Hanging Oblique Knee Raise","equipment":"bodyweight","primaryMuscles":["abs"],"secondaryMuscles":["forearms"],"category":"compound","isBodyweight":true,"instructions":["Hang from a secure pull-up bar with legs together and a firm grip.","Brace your trunk and raise both bent knees diagonally toward one side without swinging.","Lower to center with control, then raise toward the other side."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/hanging-oblique-knee-raise.webp"]}},{"id":"atlas-hanging-straight-leg-raise","name":"Hanging Straight-Leg Raise","equipment":"bodyweight","primaryMuscles":["abs"],"secondaryMuscles":[],"category":"compound","isBodyweight":true,"instructions":["Hang from a pull-up bar with an overhand grip and legs straight together.","Without swinging, raise both straight legs forward to about hip height.","Lower your legs slowly to a still hang; bend your knees to shorten the range if needed."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/hanging-straight-leg-raise.webp"]}},{"id":"atlas-hanging-windshield-wiper","name":"Hanging Windshield Wiper","equipment":"bodyweight","primaryMuscles":["abs"],"secondaryMuscles":["forearms"],"category":"compound","isBodyweight":true,"instructions":["Hang from a secure pull-up bar with a firm grip and shoulders active; brace your trunk.","Raise your legs in a range you can control, then rotate them a short distance to one side without swinging.","Return to center and lower with control; reduce the range or stop if you cannot prevent momentum."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/hanging-windshield-wiper.webp"]}},{"id":"atlas-heel-drop-calf-raise","name":"Heel-Drop Calf Raise","equipment":"bodyweight","primaryMuscles":["calves"],"secondaryMuscles":[],"category":"isolation","isBodyweight":true,"instructions":["Press the toes onto the edge of a stable step; take support from a railing or wall for balance.","Lower the heels in a controlled way below step level within a comfortable range.","Rise onto the toes and return slowly to the start; do not bounce and do not go to a depth that causes pain."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/heel-drop-calf-raise.webp"]}},{"id":"atlas-high-cable-double-biceps-curl","name":"High-Double-Biceps Curl (Cable)","equipment":"cable","primaryMuscles":["biceps"],"secondaryMuscles":["forearms"],"category":"isolation","instructions":["Stand between two high pulleys and hold a handle in each hand, arms open.","Curl handles toward the sides of your head, keeping upper arms steady.","Extend slowly to the open position; do not lean back."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/high-cable-double-biceps-curl.webp"]}},{"id":"atlas-hip-airplane","name":"Hip Airplane","equipment":"bodyweight","primaryMuscles":["glutes"],"secondaryMuscles":["abductors","hamstrings"],"category":"compound","isBodyweight":true,"instructions":["Stand on one foot with the knee slightly bent; hinge forward at the hips and extend the free leg backward.","With the torso steady, rotate the pelvis open and closed under control; extend the arms to the sides or take support for balance.","Return upright; keep the movement small and pain-free, then switch sides."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/hip-airplane.webp"]}},{"id":"atlas-hip-hike","name":"Hip Hike","equipment":"other","primaryMuscles":["abductors"],"secondaryMuscles":["glutes"],"category":"isolation","instructions":["Stand on one foot at the edge of a low, stable step; hold a railing for balance.","As your free foot drops down beside the step, let your hip lower slightly, then raise your hip with your standing leg.","Keep your torso upright and repeat in a small, controlled range; work both sides."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/hip-hike.webp"]}},{"id":"atlas-hollow-body-hold","name":"Hollow Body Hold","equipment":"bodyweight","primaryMuscles":["abs"],"secondaryMuscles":[],"category":"compound","isBodyweight":true,"instructions":["Lie on your back and gently press your lower back into the floor; start with your knees bent.","Lift your shoulders and feet slightly and hold the position by bracing your abs.","If your lower back starts to lift, bend your knees more; hold for a controlled time without holding your breath."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/hollow-body-hold.webp"]}},{"id":"atlas-incline-barbell-triceps-extension","name":"Incline Triceps Extension (Barbell)","equipment":"barbell","primaryMuscles":["triceps"],"secondaryMuscles":["forearms"],"category":"isolation","instructions":["Set the bench back to about 30, 45 degrees. Lie back with feet planted and hold a light barbell with a narrow overhand grip above your shoulders.","Keep your upper arms steady and angled slightly toward your head. Bend your elbows to lower the bar in a controlled arc behind your head, away from your face.","Extend your elbows to return the bar above your shoulders without letting your upper arms swing; use a load you can control throughout."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/incline-barbell-triceps-extension.webp"]}},{"id":"atlas-incline-bench-dumbbell-reverse-fly","name":"Incline Bench Reverse Fly (Dumbbell)","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":["back"],"category":"isolation","instructions":["Set a bench to a moderate incline and lie face-down with your chest supported; hold a light dumbbell in each hand with arms hanging below the shoulders.","Keeping a soft, steady elbow bend, raise both arms out to the sides until they approach shoulder height; keep your chest on the pad and avoid shrugging.","Lower the dumbbells slowly to the hanging start position without swinging your torso."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/incline-bench-dumbbell-reverse-fly.webp"]}},{"id":"atlas-incline-bench-pull","name":"Incline Bench Pull","equipment":"barbell","primaryMuscles":["back"],"secondaryMuscles":["lats","biceps"],"category":"compound","instructions":["Set a stable incline bench so your chest is supported and a barbell can hang freely below the bench edge. Lie face down with both feet grounded and grasp the bar with an overhand grip, arms extended.","Keep your chest on the pad and pull the bar toward the underside of your lower chest by driving your elbows back. Draw your shoulder blades together without shrugging.","Lower the bar under control until your arms extend. Keep your torso supported throughout and use only a load you can move without bouncing."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/incline-bench-pull.webp"]}},{"id":"atlas-incline-cable-chest-press","name":"Incline Chest Press (Cable)","equipment":"cable","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"category":"compound","instructions":["Set an incline bench between two cable stacks with both pulleys low. Sit down, take a handle in each hand, then lie back with the handles beside your upper chest.","Press the handles upward and slightly inward until your arms are nearly straight; keep your shoulders supported and avoid arching your lower back.","Pause before locking your elbows, then lower the handles slowly to the upper chest while keeping control of the cables."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/incline-cable-chest-press.webp"]}},{"id":"atlas-incline-cable-fly","name":"Incline Fly (Cable)","equipment":"cable","primaryMuscles":["chest"],"secondaryMuscles":["shoulders"],"category":"compound","instructions":["Place an incline bench between two cable stacks, set both pulleys low, and lie back with a handle in each hand; keep a slight bend in your elbows.","Open your arms out to the sides in a controlled arc until you feel a comfortable chest stretch; keep your shoulders supported on the bench.","Sweep your arms together above the upper chest without changing the elbow bend, then return slowly and avoid arching your lower back."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/incline-cable-fly.webp"]}},{"id":"atlas-incline-cable-lat-pulldown","name":"Incline Lat Pulldown (Cable)","equipment":"cable","primaryMuscles":["lats"],"secondaryMuscles":["chest","shoulders","back"],"category":"compound","instructions":["Set an incline bench facing away from the cable station so your head is near the pulley; adjust the pulley and bar so the cable stays taut overhead.","Sit back against the pad, plant your feet and hold the bar about shoulder-width with a soft bend in your elbows.","Keeping your back supported and elbows nearly fixed, sweep the bar down toward your upper thighs; return overhead slowly without shrugging or arching."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/incline-cable-lat-pulldown.webp"]}},{"id":"atlas-incline-dumbbell-press","name":"Incline Press (Dumbbell)","equipment":"dumbbell","primaryMuscles":["chest"],"secondaryMuscles":["triceps","shoulders"],"category":"compound","instructions":["Set a bench to a low incline and hold the dumbbells beside the upper chest.","Press both weights upward without letting them drift together; keep wrists stacked over elbows.","Lower until the upper arms are just below shoulder level, then repeat with control."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/incline-dumbbell-press.webp"]}},{"id":"atlas-inverted-row","name":"Inverted Row","equipment":"other","primaryMuscles":["back"],"secondaryMuscles":["lats","biceps"],"category":"compound","instructions":["Get under a sturdy, waist-height bar and grip it at shoulder width; keep your body straight.","Pull your chest toward the bar and bring your shoulder blades toward each other.","Extend your arms under control and return to the start; do not let your hips drop."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/inverted-row.webp"]}},{"id":"atlas-jump-rope","name":"Jump Rope","equipment":"other","primaryMuscles":["calves"],"secondaryMuscles":["forearms","shoulders"],"category":"cardio","instructions":["Hold one rope handle in each hand with the rope resting behind your heels.","Turn the rope with small wrist circles and make low hops as it passes under your feet.","Land softly on the balls of your feet and keep the jumps small."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/jump-rope.webp"]}},{"id":"atlas-kelso-shrug","name":"Kelso Shrug","equipment":"dumbbell","primaryMuscles":["traps"],"secondaryMuscles":["back"],"category":"compound","instructions":["Lie face down on an incline bench and hold light dumbbells with your arms hanging down.","Without bending your elbows, pull your shoulder blades toward each other.","Pause briefly and lower your shoulders forward under control; do not swing the weight."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/kelso-shrug.webp"]}},{"id":"atlas-kettlebell-deadlift","name":"Kettlebell Deadlift","equipment":"kettlebell","primaryMuscles":["glutes","hamstrings"],"secondaryMuscles":["quads"],"category":"compound","instructions":["Stand over a kettlebell and hinge to grip its handle.","Push through the feet to stand, then hinge back down."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/kettlebell-deadlift.webp"]}},{"id":"atlas-kettlebell-halo","name":"Kettlebell Halo","equipment":"kettlebell","primaryMuscles":["traps"],"secondaryMuscles":["shoulders"],"category":"compound","instructions":["Stand tall and hold a light kettlebell by its horns in front of your chest.","Circle it slowly around your head, keeping it close and ribs stacked over pelvis.","Return to the front and circle the other way within a comfortable range."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/kettlebell-halo.webp"]}},{"id":"atlas-kettlebell-suitcase-deadlift","name":"Suitcase Deadlift (Kettlebell)","equipment":"kettlebell","primaryMuscles":["glutes","quads"],"secondaryMuscles":["hamstrings","lower_back","abs"],"category":"compound","instructions":["Place the kettlebell beside the outside of one foot; set your feet hip-width apart and hinge at the hips and knees.","Keeping your spine neutral and your shoulders level, lift the kettlebell off the floor.","Lower the weight to the floor along the same controlled path; do not lean sideways and start with a light load."],"formCues":[],"media":{}},{"id":"atlas-kettlebell-windmill","name":"Kettlebell Windmill","equipment":"kettlebell","primaryMuscles":["abs"],"secondaryMuscles":["shoulders","glutes"],"category":"compound","instructions":["Press a light kettlebell overhead and turn the same-side foot slightly outward.","Keep your eyes on the bell, push your hip out and hinge sideways while the free hand tracks down your thigh.","Stand tall without letting the bell drift; use a very light load while learning."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/kettlebell-windmill.webp"]}},{"id":"atlas-knee-supported-copenhagen-plank","name":"Knee-Supported Copenhagen Plank","equipment":"bodyweight","primaryMuscles":["adductors"],"secondaryMuscles":["abs"],"category":"compound","isBodyweight":true,"instructions":["Get into a side plank position and place your top knee on a sturdy, non-slip bench.","Lift your hips off the floor to form a straight line from head to knee; hold briefly.","Lower in a controlled way; start with short holds and release if you feel pain in the knee or groin."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/knee-supported-copenhagen-plank.webp"]}},{"id":"atlas-knee-to-wall-ankle-rock","name":"Knee-to-Wall Ankle Rock","equipment":"bodyweight","primaryMuscles":["calves"],"secondaryMuscles":[],"category":"mobility","isBodyweight":true,"instructions":["Stand in a short split stance with the front toes a few centimetres from a wall; keep the foot pointing forward.","Move the front knee toward the wall over the toes while keeping the whole foot, especially the heel, on the floor.","Return smoothly. If the knee reaches the wall easily, move the front foot slightly farther away and repeat."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/knee-to-wall-ankle-rock.webp"]}},{"id":"atlas-kneeling-barbell-ab-rollout","name":"Kneeling Ab Rollout (Barbell)","equipment":"barbell","primaryMuscles":["abs"],"secondaryMuscles":["shoulders","lats","glutes"],"category":"compound","instructions":["Place a mat under your knees and kneel behind a loaded barbell with round plates that roll smoothly. Grip the bar at shoulder width with it directly below your shoulders; brace your abs and keep your back neutral.","Keeping your knees planted and hips aligned with your torso, roll the bar forward under control. Stop at the farthest position where you can keep your ribs down and lower back neutral.","Pull the bar back toward your knees by bracing your abs and lats; do not let your hips sag or use momentum."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/kneeling-barbell-ab-rollout.webp"]}},{"id":"atlas-kneeling-cable-lat-pulldown","name":"Kneeling Lat Pulldown (Cable)","equipment":"cable","primaryMuscles":["lats"],"secondaryMuscles":["biceps","back"],"category":"compound","instructions":["Attach a straight bar to a high pulley. Kneel facing the station with your knees about hip-width apart, hips extended, and arms overhead holding the bar wider than shoulder-width.","Keep your torso tall and pull the bar toward your upper chest by driving your elbows down beside your body.","Straighten your arms slowly and return the bar overhead under control."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/kneeling-cable-lat-pulldown.webp"]}},{"id":"atlas-kneeling-high-pulley-row","name":"Kneeling High Pulley Row (Cable)","equipment":"cable","primaryMuscles":["back"],"secondaryMuscles":["lats","biceps","shoulders"],"category":"compound","instructions":["Attach a rope to a high pulley and kneel facing the station a short distance back, with your torso upright and arms extended toward the pulley.","Pull both rope ends toward your upper chest, leading with the elbows out to the sides and drawing the shoulder blades together; keep the trunk steady.","Extend your arms slowly to return under control without rounding your back or shrugging."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/kneeling-high-pulley-row.webp"]}},{"id":"atlas-kneeling-machine-glute-press","name":"Kneeling Glute Press (Machine)","equipment":"machine","primaryMuscles":["glutes"],"secondaryMuscles":["hamstrings"],"category":"compound","instructions":["Adjust the chest support, kneeling pad, and resistance. Kneel on the lower pad, hold the handles, and place one foot on the rear platform with the knee bent.","Brace your trunk and press the platform backward by extending the working hip and knee; keep your lower back steady rather than arching.","Return the platform slowly until the knee bends comfortably, then finish the set and switch sides."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/kneeling-machine-glute-press.webp"]}},{"id":"atlas-l-sit-hold","name":"L-Sit Hold","equipment":"other","primaryMuscles":["abs"],"secondaryMuscles":["triceps","shoulders"],"category":"compound","instructions":["Support yourself on stable parallel bars with elbows straight and shoulders away from your ears.","Brace your trunk and lift both straight legs until they are about horizontal.","Hold while breathing steadily, then lower with control; bend the knees to scale."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/l-sit-hold.webp"]}},{"id":"atlas-landmine-rotation","name":"Landmine Rotation","equipment":"barbell","primaryMuscles":["abs"],"secondaryMuscles":["shoulders"],"category":"compound","instructions":["Secure one end of a barbell in a landmine base and hold the free end with both hands at chest height.","Stand with feet stable and guide the bar in a controlled arc across your body, rotating through the hips and trunk.","Reverse the arc smoothly; use a load that lets you keep control."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/landmine-rotation.webp"]}},{"id":"atlas-landmine-row","name":"Landmine Row","equipment":"barbell","primaryMuscles":["back"],"secondaryMuscles":["lats","biceps"],"category":"compound","instructions":["Place one end of the bar in a fixed landmine sleeve and take a suitable handle.","Lean your torso forward and keep your back neutral; pull your elbows back and bring the bar toward your lower ribs.","Lower the weight to the start without jerking; do not rotate your torso during the pull."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/landmine-row.webp"]}},{"id":"atlas-lateral-band-walk","name":"Lateral Band Walk","equipment":"band","primaryMuscles":["abductors"],"secondaryMuscles":["glutes"],"category":"isolation","instructions":["Place a light band above your knees; set your feet hip-width apart and soften your knees.","Keeping the shallow squat position, take small, controlled steps to the side.","Keep the band tense as you bring your feet back together; travel equally in both directions."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/lateral-band-walk.webp"]}},{"id":"atlas-lateral-hand-resisted-neck-isometric","name":"Lateral Hand-Resisted Neck Isometric","equipment":"bodyweight","primaryMuscles":["neck"],"secondaryMuscles":[],"category":"isolation","isBodyweight":true,"instructions":["Sit upright and keep your head neutral; lightly place your palm beside your temple.","Apply very light resistance with your hand without moving your head; hold briefly and keep breathing.","Release and switch to the other side; stop immediately if you feel pain, numbness or dizziness."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/lateral-hand-resisted-neck-isometric.webp"]}},{"id":"atlas-lateral-lunge","name":"Lateral Lunge","equipment":"bodyweight","primaryMuscles":["adductors"],"secondaryMuscles":["quads","glutes"],"category":"compound","isBodyweight":true,"instructions":["Stand upright with your feet hip-width apart; leave room to step to the side.","Take a wide step to one side and bend that knee, sending your hips back; keep your other leg comfortably straight.","Push through the bent leg to return to the center; let your knee track in the same direction as your toes."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/lateral-lunge.webp"]}},{"id":"atlas-lateral-step-down","name":"Lateral Step-Down","equipment":"bodyweight","primaryMuscles":["quads"],"secondaryMuscles":["glutes"],"category":"compound","isBodyweight":true,"instructions":["Stand sideways on a low stable step with one foot near the edge.","Bend the standing knee and lower the free heel toward the floor beside the step.","Tap lightly and press through the step foot to return; track the knee over the toes."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/lateral-step-down.webp"]}},{"id":"atlas-lateral-step-up","name":"Lateral Step-Up","equipment":"bodyweight","primaryMuscles":["quads","glutes"],"secondaryMuscles":["abductors"],"category":"compound","isBodyweight":true,"instructions":["Stand sideways next to a low, sturdy box and place the nearer foot fully on top.","Push through the elevated foot to step up, keeping your knee aligned with your toes.","Step back down slowly and repeat; switch sides after the set."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/lateral-step-up.webp"]}},{"id":"atlas-leg-press-calf-raise","name":"Leg Press Calf Raise (Machine)","equipment":"machine","primaryMuscles":["calves"],"secondaryMuscles":[],"category":"isolation","instructions":["Load the leg press lightly; place the toes on the lower part of the platform and let the heels hang free.","Without locking the knees, push through the toes to raise the heels.","Lower the heels under control; keep safe contact with the platform and work in a pain-free range."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/leg-press-calf-raise.webp"]}},{"id":"atlas-lever-deadlift","name":"Lever Deadlift (Machine)","equipment":"machine","primaryMuscles":["glutes","hamstrings"],"secondaryMuscles":["quads","lower_back","forearms"],"category":"compound","instructions":["Choose a manageable load, stand centered on the platform with feet about hip-width apart, and grip the handles; brace your trunk and keep your spine neutral.","Hinge at the hips and bend your knees enough to reach the start position. Drive through the platform and extend your hips and knees together, keeping the handles close.","Stand tall without leaning back, then lower the lever arms smoothly by hinging and bending your knees until you reach the start position; do not let the plates bounce."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/lever-deadlift.webp"]}},{"id":"atlas-lying-cable-leg-curl","name":"Lying Leg Curl (Cable)","equipment":"cable","primaryMuscles":["hamstrings"],"secondaryMuscles":["calves"],"category":"isolation","instructions":["Place a bench in front of a low pulley, attach an ankle cuff, and lie face down with the cuff on one ankle and both hips supported on the bench.","Keeping your thigh against the bench, bend the working knee and draw your heel toward your buttock without lifting your hip.","Straighten the knee slowly against the cable, then repeat on the other leg."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/lying-cable-leg-curl.webp"]}},{"id":"atlas-lying-cable-triceps-extension","name":"Lying Triceps Extension (Cable)","equipment":"cable","primaryMuscles":["triceps"],"secondaryMuscles":[],"category":"isolation","instructions":["Place a flat bench in front of a low pulley, attach a straight bar, and lie face up with your head nearest the stack; plant your feet and hold the bar over your upper chest with elbows bent.","Keep your upper arms steady and extend your elbows to raise the bar above your chest; avoid swinging your shoulders or forcefully locking your elbows.","Bend your elbows slowly to return the bar toward your forehead while keeping your upper arms in place and the cable under control."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/lying-cable-triceps-extension.webp"]}},{"id":"atlas-lying-leg-curls","name":"Lying Leg Curls (Machine)","equipment":"machine","primaryMuscles":["hamstrings"],"secondaryMuscles":["calves"],"category":"isolation","instructions":["Lie face down on the machine and set the pad just above the ankles.","Keeping the hips on the bench, bend the knees and bring the heels toward the buttocks under control.","Straighten the legs slowly without dropping the weight."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/lying-leg-curls.webp"]}},{"id":"atlas-lying-overhead-dumbbell-triceps-extension","name":"Lying Overhead Triceps Extension (Dumbbell)","equipment":"dumbbell","primaryMuscles":["triceps"],"secondaryMuscles":["forearms"],"category":"isolation","instructions":["Lie on a flat bench and hold one dumbbell securely with both hands above your shoulders.","Bend your elbows to lower the weight beside and slightly behind your head while keeping your upper arms mostly still.","Extend your elbows to return the dumbbell above your shoulders; use a load you can control safely."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/lying-overhead-dumbbell-triceps-extension.webp"]}},{"id":"atlas-machine-decline-chest-press","name":"Decline Chest Press (Machine)","equipment":"machine","primaryMuscles":["chest"],"secondaryMuscles":["triceps","shoulders"],"category":"compound","instructions":["Adjust the seat so the handles begin near mid-chest; sit back against the pad and secure the seat belt if fitted.","Press the handles forward along the machine's path, keeping your wrists straight and stopping before the elbows lock.","Bring the handles back slowly until you feel a comfortable chest stretch; keep your shoulders against the pad."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/machine-decline-chest-press.webp"]}},{"id":"atlas-machine-glute-kickback","name":"Glute Kickback (Machine)","equipment":"machine","primaryMuscles":["glutes"],"secondaryMuscles":["hamstrings"],"category":"compound","instructions":["Set the pedal and resistance; rest your chest and forearms on the support, keep one foot planted and place the other foot on the pedal.","Without arching your lower back or turning your pelvis, press the pedal back by extending the working hip.","Return the leg slowly to the start, then complete the set on the other side."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/machine-glute-kickback.webp"]}},{"id":"atlas-machine-hip-thrust","name":"Hip Thrust (Machine)","equipment":"machine","primaryMuscles":["glutes"],"secondaryMuscles":["hamstrings"],"category":"compound","instructions":["Set the back against the support, bring the machine pad to the crease of the hips and plant the feet on the floor.","Keeping the ribs down, lift the hips until the shoulders, hips and knees are in line.","Squeeze the glutes with a brief pause and lower under control without over-arching the lower back."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/machine-hip-thrust.webp"]}},{"id":"atlas-machine-kneeling-leg-curl","name":"Kneeling Leg Curl (Machine)","equipment":"machine","primaryMuscles":["hamstrings"],"secondaryMuscles":[],"category":"compound","instructions":["Kneel on the support pad, lean forward onto the thigh and forearm pads, and set the roller just above the working ankle.","Keep your hips and back steady as you bend the working knee, drawing the heel toward your glute.","Extend the knee slowly without letting the weight stack rest; complete controlled repetitions before switching legs."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/machine-kneeling-leg-curl.webp"]}},{"id":"atlas-machine-lateral-raise","name":"Lateral Raise (Machine)","equipment":"machine","primaryMuscles":["shoulders"],"secondaryMuscles":[],"category":"isolation","instructions":["Adjust the seat so the pads sit just above your elbows; sit upright with your arms slightly bent and shoulders relaxed.","Press your elbows outward to raise the pads until your upper arms are near shoulder height; avoid shrugging.","Lower the pads slowly to the start position while keeping your torso still."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/machine-lateral-raise.webp"]}},{"id":"atlas-machine-low-row","name":"Low Row (Machine)","equipment":"machine","primaryMuscles":["lats","back"],"secondaryMuscles":["biceps"],"category":"compound","instructions":["Set the seat so you can reach the handles with your chest supported and feet firmly on the rests.","Keeping your chest against the pad, pull the handles low toward your lower ribs with your elbows close to your sides.","Extend your arms slowly to return; let the shoulders reach forward without losing contact with the pad."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/machine-low-row.webp"]}},{"id":"atlas-machine-pullover","name":"Machine Pullover","equipment":"machine","primaryMuscles":["lats"],"secondaryMuscles":["chest"],"category":"compound","instructions":["Sit in the machine and place your upper arms on the pads; keep your ribs down and your back supported.","With your elbows slightly bent, pull the arms down in a controlled arc.","Slowly release the resistance and raise your arms back to a comfortable shoulder range; do not overstretch."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/machine-pullover.webp"]}},{"id":"atlas-meadows-row","name":"Meadows Row","equipment":"barbell","primaryMuscles":["lats"],"secondaryMuscles":["back","biceps","forearms","lower_back"],"category":"compound","instructions":["Secure one end of the bar in a landmine pivot and load the free sleeve. Stand side-on in a split stance with the foot opposite the working arm forward; hinge at the hips, brace your free hand on the front thigh, and grip the loaded sleeve overhand.","Let the working shoulder reach forward without rounding your lower back. Keeping your torso still, drive the elbow up and out and row the sleeve along the bar's arc toward your lower chest.","Lower the bar under control to a comfortable stretch without twisting or dropping the plates. Finish one side, then switch arms."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/meadows-row.webp"]}},{"id":"atlas-medicine-ball-overhead-slam","name":"Medicine Ball Overhead Slam","equipment":"other","primaryMuscles":["glutes","quads","lats","shoulders"],"secondaryMuscles":["abs"],"category":"compound","instructions":["Hold a non-bouncing medicine ball with both hands and raise it overhead.","Brace your trunk, hinge slightly and drive the ball down in front of your feet.","Retrieve the ball only after it stops moving; use a slam-rated ball and clear space."],"formCues":[],"media":{}},{"id":"atlas-neck-extension-isometric","name":"Neck Extension Isometric","equipment":"bodyweight","primaryMuscles":["neck"],"secondaryMuscles":[],"category":"isolation","isBodyweight":true,"instructions":["Sit upright and keep your head neutral; lightly place both hands behind your head.","Press very lightly against your hands without moving your head backward; do not hold your breath.","Release after a short time; stop immediately if you feel pain, numbness or dizziness."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/neck-extension-isometric.webp"]}},{"id":"atlas-neck-flexion-isometric","name":"Neck Flexion Isometric","equipment":"bodyweight","primaryMuscles":["neck"],"secondaryMuscles":[],"category":"isolation","isBodyweight":true,"instructions":["Sit upright, keep your head neutral and lightly place your palm on your forehead.","Press very lightly against your hand without moving your head forward; breathe comfortably.","Release after a short time; stop immediately if you feel pain, numbness or dizziness."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/neck-flexion-isometric.webp"]}},{"id":"atlas-neck-rotation-isometric","name":"Neck Rotation Isometric","equipment":"bodyweight","primaryMuscles":["neck"],"secondaryMuscles":[],"category":"isolation","isBodyweight":true,"instructions":["Sit upright and keep your head neutral; lightly place your palm beside your temple.","Press very lightly toward your hand without turning your head; keep breathing comfortably.","Release after a short time and try the other side; stop if you feel pain, numbness or dizziness."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/neck-rotation-isometric.webp"]}},{"id":"atlas-neutral-grip-lat-pulldown","name":"Neutral-Grip Lat Pulldown (Cable)","equipment":"cable","primaryMuscles":["lats"],"secondaryMuscles":["biceps","back"],"category":"compound","instructions":["Sit at the pulldown station and secure your thighs under the pads. Hold a close parallel-grip attachment with your palms facing one another and reach overhead without shrugging.","Keep your torso tall with a small stable lean, then drive your elbows down beside your body and bring the handle toward the upper chest.","Extend your arms slowly overhead, keeping the torso steady and allowing the cable to return under control."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/neutral-grip-lat-pulldown.webp"]}},{"id":"atlas-neutral-grip-pull-up","name":"Neutral-Grip Pull-Up","equipment":"other","primaryMuscles":["lats"],"secondaryMuscles":["biceps","back"],"category":"compound","instructions":["Grip the parallel-handle bar with your palms facing each other; hang without swinging.","Pull your elbows down and toward your body, bringing your chin up to handle level.","Extend your arms under control and return to the start; do not squeeze your shoulders toward your ears."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/neutral-grip-pull-up.webp"]}},{"id":"atlas-nordic-hamstring-curl","name":"Nordic Hamstring Curl","equipment":"bodyweight","primaryMuscles":["hamstrings"],"secondaryMuscles":["glutes","calves"],"category":"isolation","isBodyweight":true,"instructions":["Kneel and anchor the ankles under a secure support; keep the body in a straight line from the knees to the head.","Lean slowly forward without bending at the hips; catch yourself with the hands near the floor when needed.","Work only within the range you can control and use the hands for support to return to the start; do not force it and fall."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/nordic-hamstring-curl.webp"]}},{"id":"atlas-one-arm-dumbbell-row","name":"Single-Arm Row (Dumbbell)","equipment":"dumbbell","primaryMuscles":["back"],"secondaryMuscles":["lats","biceps"],"category":"compound","instructions":["Support one hand and knee on a bench; keep the back flat and hold the dumbbell in the working hand.","Pull the elbow toward the hip to bring the dumbbell beside the torso; do not rotate the torso.","Lower the dumbbell under control beneath the shoulder; work both sides."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/one-arm-dumbbell-row.webp"]}},{"id":"atlas-one-arm-flat-bench-dumbbell-flye","name":"One-Arm Flat Bench Flye (Dumbbell)","equipment":"dumbbell","primaryMuscles":["chest"],"secondaryMuscles":["shoulders"],"category":"compound","instructions":["Lie on a flat bench with feet planted and hold one light dumbbell above the working-side chest with a soft elbow bend; let the other arm rest by your side.","Keep your shoulders and hips on the bench and lower the dumbbell outward in a controlled arc only as far as feels comfortable.","Bring the dumbbell back above the chest without changing the elbow bend, then repeat on the other side; use a light load and avoid forcing a deep stretch."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/one-arm-flat-bench-dumbbell-flye.webp"]}},{"id":"atlas-overhead-dumbbell-shrug","name":"Overhead Shrug (Dumbbell)","equipment":"dumbbell","primaryMuscles":["traps"],"secondaryMuscles":["shoulders"],"category":"isolation","instructions":["Stand stable with two light dumbbells held overhead and elbows straight but not forced.","Raise the shoulder blades slightly toward the ears without bending the elbows or arching the back.","Lower the shoulder blades under control; use a load you can keep stable overhead."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/overhead-dumbbell-shrug.webp"]}},{"id":"atlas-overhead-machine-triceps-extension","name":"Overhead Triceps Extension (Machine)","equipment":"machine","primaryMuscles":["triceps"],"secondaryMuscles":["forearms"],"category":"isolation","instructions":["Set the seat and starting lever according to the machine placard. Sit with your back supported and hold the rotating handle; bring your upper arms beside your head with elbows bent.","Keeping your upper arms steady and wrists neutral, extend your elbows to raise the handle overhead without forcefully locking out or arching your back.","Bend your elbows slowly to return the handle behind your head. Use the machine's start assist as directed and choose a load you can control."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/overhead-machine-triceps-extension.webp"]}},{"id":"atlas-pec-deck-fly","name":"Pec Deck Fly (Machine)","equipment":"machine","primaryMuscles":["chest"],"secondaryMuscles":["shoulders"],"category":"compound","instructions":["Adjust the seat so the handles or pads align around mid-chest height.","With a soft bend in the elbows, bring the arms together in front of your chest.","Return slowly until you feel a comfortable chest stretch; avoid forcing the arms far behind you."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/pec-deck-fly.webp"]}},{"id":"atlas-pendlay-row","name":"Pendlay Row","equipment":"barbell","primaryMuscles":["back"],"secondaryMuscles":["lats","biceps"],"category":"compound","instructions":["Set the bar on the floor and hinge until your torso is nearly parallel, with a neutral spine.","Grip the bar and row it toward the lower chest while keeping the torso angle steady.","Lower the bar to the floor between repetitions and reset your brace."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/pendlay-row.webp"]}},{"id":"atlas-pendulum-squat","name":"Pendulum Squat (Machine)","equipment":"machine","primaryMuscles":["quads"],"secondaryMuscles":["glutes","hamstrings"],"category":"compound","instructions":["Position your shoulders under the pads, place both feet on the platform, and release the machine's safety lock as directed by its placard.","Bend your knees and hips to lower the sled under control, keeping your feet planted and knees aligned with your toes.","Push through the platform to rise; stop short of locking the knees, then engage the safety before stepping out."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/pendulum-squat.webp"]}},{"id":"atlas-pistol-squat","name":"Pistol Squat","equipment":"bodyweight","primaryMuscles":["quads","glutes"],"secondaryMuscles":["abs","calves"],"category":"compound","isBodyweight":true,"instructions":["Stand on one foot and extend the other leg forward; reach the arms out to balance.","Bend the standing knee and hip to lower only as far as you can keep the heel planted and torso controlled.","Press through the whole foot to stand; use a box or hand support until the full range is steady."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/pistol-squat.webp"]}},{"id":"atlas-plate-front-raise","name":"Plate Front Raise","equipment":"other","primaryMuscles":["shoulders"],"secondaryMuscles":[],"category":"isolation","instructions":["Hold a light weight plate in both hands in front of your thighs; keep your knees soft.","Keeping your elbows slightly bent, raise the plate forward to shoulder height.","Lower the plate slowly without swinging your torso; stop the movement if shoulder pain appears."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/plate-front-raise.webp"]}},{"id":"atlas-plate-loaded-assisted-nordic-hamstring-curl","name":"Plate-Loaded Assisted Nordic Hamstring Curl (Machine)","equipment":"machine","primaryMuscles":["hamstrings"],"secondaryMuscles":["glutes","calves"],"category":"isolation","instructions":["Set assistance according to the machine placard; on this counterbalanced model, adding weight increases assistance. Adjust the torso pad and secure your ankles beneath the rollers.","Keep your body straight from knees through shoulders and slowly lean forward from the knees, resisting the descent with your hamstrings.","Use your hamstrings to curl back to kneeling under control; increase assistance if you cannot control the full range."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/plate-loaded-assisted-nordic-hamstring-curl.webp"]}},{"id":"atlas-plate-loaded-ground-base-high-pull","name":"Plate-Loaded Ground Base High Pull (Machine)","equipment":"machine","primaryMuscles":["traps","shoulders"],"secondaryMuscles":["quads","glutes","hamstrings","biceps","forearms","abs"],"category":"compound","instructions":["Load both independent arms evenly. Stand with feet planted, hold the long handles near thigh level, and set a stable athletic stance with hips hinged and knees bent.","Drive through your feet and extend your hips and knees as you pull the handles close to your body toward the lower chest; let the elbows lead without rising above shoulder level.","Lower the handles under control to the start. Begin with a light load, avoid jerking the arms, and stop if the movement causes shoulder pain."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/plate-loaded-ground-base-high-pull.webp"]}},{"id":"atlas-plate-loaded-ground-base-jammer-press","name":"Plate-Loaded Ground Base Jammer Press (Machine)","equipment":"machine","primaryMuscles":["chest","shoulders"],"secondaryMuscles":["triceps","abs","quads","glutes"],"category":"compound","instructions":["Load the independent arms evenly. Stand in a stable split stance with the handles near upper-chest height, wrists straight, and knees softly bent.","Brace your trunk and press the handles forward and upward along the machine's path while keeping your feet planted and torso controlled.","Let the handles return slowly to the start without letting the arms pull your shoulders forward. Use a load you can control and keep clear of the moving arms."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/plate-loaded-ground-base-jammer-press.webp"]}},{"id":"atlas-plate-loaded-iso-lateral-d-y-row","name":"Plate-Loaded Iso-Lateral D.Y. Row (Machine)","equipment":"machine","primaryMuscles":["lats","back"],"secondaryMuscles":["biceps","traps"],"category":"compound","instructions":["Adjust the seat and chest pad so your chest stays supported; place your feet on the rests and take the underhand handles with straight wrists.","Pull the handles down and back toward your lower ribs by driving your elbows behind you; keep your chest on the pad.","Let the independent arms travel forward slowly until your shoulders reach a comfortable stretch; avoid jerking or lifting your chest."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/plate-loaded-iso-lateral-d-y-row.webp"]}},{"id":"atlas-plate-loaded-iso-lateral-decline-chest-press","name":"Plate-Loaded Iso-Lateral Decline Chest Press (Machine)","equipment":"machine","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"category":"compound","instructions":["Adjust the seat so the handles begin near the lower chest; brace your back against the pad and secure your feet.","Press the independent handles forward and slightly downward, keeping your wrists straight and elbows softly bent.","Let the handles return slowly until your elbows are comfortably behind your torso; keep the plates controlled."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/plate-loaded-iso-lateral-decline-chest-press.webp"]}},{"id":"atlas-plate-loaded-iso-lateral-front-lat-pulldown","name":"Plate-Loaded Iso-Lateral Front Lat Pulldown (Machine)","equipment":"machine","primaryMuscles":["lats"],"secondaryMuscles":["biceps","back","forearms"],"category":"compound","instructions":["Load both arms evenly, adjust the seat and thigh pads, sit upright, and grasp the overhead handles with an underhand grip.","Keeping your torso steady, pull the handles down and slightly back toward your upper chest by driving your elbows toward your sides.","Allow the arms to rise overhead slowly under control without letting the plates drop between repetitions."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/plate-loaded-iso-lateral-front-lat-pulldown.webp"]}},{"id":"atlas-plate-loaded-iso-lateral-high-row","name":"Plate-Loaded Iso-Lateral High Row (Machine)","equipment":"machine","primaryMuscles":["back","lats"],"secondaryMuscles":["traps","biceps"],"category":"compound","instructions":["Load both independent arms evenly; adjust the seat and thigh pad so you can reach the handles comfortably and stay stable, then brace your feet.","Take the fixed overhand grips and pull each arm down and back toward your upper ribs, keeping your torso steady and elbows moving down and behind you.","Control the arms as they return forward to a comfortable stretch; do not let the plates drop."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/plate-loaded-iso-lateral-high-row.webp"]}},{"id":"atlas-plate-loaded-iso-lateral-horizontal-bench-press","name":"Plate-Loaded Iso-Lateral Horizontal Bench Press (Machine)","equipment":"machine","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"category":"compound","instructions":["Set the seat so the handles start around mid-chest; brace your back against the pad and plant your feet.","Press both independent handles forward at chest height, keeping your wrists straight and elbows softly bent at the finish.","Return the handles slowly until you feel a comfortable chest stretch; keep both arms controlled."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/plate-loaded-iso-lateral-horizontal-bench-press.webp"]}},{"id":"atlas-plate-loaded-iso-lateral-incline-press","name":"Plate-Loaded Iso-Lateral Incline Press (Machine)","equipment":"machine","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"category":"compound","instructions":["Adjust the seat and back pad so the handles begin near upper-chest level; place your feet firmly on the rests.","Press both independent handles upward and forward without locking your elbows or lifting your back from the pad.","Lower the handles slowly until you feel a comfortable chest stretch; keep both sides controlled."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/plate-loaded-iso-lateral-incline-press.webp"]}},{"id":"atlas-plate-loaded-iso-lateral-leg-curl","name":"Plate-Loaded Iso-Lateral Leg Curl (Machine)","equipment":"machine","primaryMuscles":["hamstrings"],"secondaryMuscles":["calves"],"category":"isolation","instructions":["Load both arms evenly, lie face down, and align your knees with the pivots; place the roller just above your ankles and hold the stabilizing handles.","Keep your hips and torso on the pads and curl your heels toward your buttocks without arching your lower back.","Lower the independent arms slowly until your knees are nearly straight, keeping the plates under control."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/plate-loaded-iso-lateral-leg-curl.webp"]}},{"id":"atlas-plate-loaded-iso-lateral-leg-extension","name":"Plate-Loaded Iso-Lateral Leg Extension (Machine)","equipment":"machine","primaryMuscles":["quads"],"secondaryMuscles":[],"category":"isolation","instructions":["Load both arms evenly, align your knees with the pivots, adjust the back pad, and secure the thigh belt; place the shin rollers just above the ankles.","Keep your back against the pad and extend one or both knees smoothly until the legs are nearly straight; do not snap the knees into lockout.","Lower the independent arms slowly to a comfortable bend, keeping the plates under control."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/plate-loaded-iso-lateral-leg-extension.webp"]}},{"id":"atlas-plate-loaded-iso-lateral-low-row","name":"Plate-Loaded Iso-Lateral Low Row (Machine)","equipment":"machine","primaryMuscles":["lats","back"],"secondaryMuscles":["biceps","forearms"],"category":"compound","instructions":["Load both independent arms evenly; adjust the seat and chest pad so your chest stays supported and your feet are braced.","Take the overhand handles and pull them low toward your waist, keeping your chest on the pad and elbows close to your sides.","Let the arms travel forward slowly to a comfortable stretch without letting the plates drop."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/plate-loaded-iso-lateral-low-row.webp"]}},{"id":"atlas-plate-loaded-iso-lateral-row","name":"Plate-Loaded Iso-Lateral Row (Machine)","equipment":"machine","primaryMuscles":["lats","back"],"secondaryMuscles":["biceps","forearms"],"category":"compound","instructions":["Load both arms evenly and adjust the seat and chest pad so you can reach the selected handles with your chest supported and feet braced.","Keep your chest on the pad and pull the independent handles toward your lower ribs, guiding your elbows back without shrugging.","Let the arms return forward slowly until you feel a comfortable back stretch; keep the plates under control."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/plate-loaded-iso-lateral-row.webp"]}},{"id":"atlas-plate-loaded-iso-lateral-super-incline-press","name":"Plate-Loaded Iso-Lateral Super Incline Press (Machine)","equipment":"machine","primaryMuscles":["shoulders"],"secondaryMuscles":["chest","triceps"],"category":"compound","instructions":["Adjust the seat so the handles start near upper-chest level; brace your back against the pad and plant your feet.","Press the independent handles up and forward along the steep path without arching your back or locking your elbows.","Lower the handles slowly to the start position, keeping your shoulders down and both arms controlled."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/plate-loaded-iso-lateral-super-incline-press.webp"]}},{"id":"atlas-plate-loaded-iso-lateral-wide-chest-press","name":"Plate-Loaded Iso-Lateral Wide Chest Press (Machine)","equipment":"machine","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"category":"compound","instructions":["Load both independent arms evenly. Set the seat so the handles begin around mid-chest, keep your back against the pad, and plant your feet firmly.","Start with the handles wide and elbows comfortably bent; press forward and slightly inward along the machine's path without snapping the elbows straight.","Return the handles slowly until you feel a comfortable chest stretch. Do not force the wide start position or let the shoulders roll forward."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/plate-loaded-iso-lateral-wide-chest-press.webp"]}},{"id":"atlas-plate-loaded-iso-lateral-wide-pulldown","name":"Plate-Loaded Iso-Lateral Wide Pulldown (Machine)","equipment":"machine","primaryMuscles":["lats"],"secondaryMuscles":["back","biceps"],"category":"compound","instructions":["Set the thigh pads snugly, sit tall, and grasp the wide handles with the grip specified by the machine.","Pull your elbows down and slightly back toward your upper ribs while keeping your torso steady.","Return the handles overhead slowly without letting the plates settle between repetitions."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/plate-loaded-iso-lateral-wide-pulldown.webp"]}},{"id":"atlas-plate-loaded-machine-gripper","name":"Plate-Loaded Gripper (Machine)","equipment":"machine","primaryMuscles":["forearms"],"secondaryMuscles":[],"category":"isolation","instructions":["Choose a comfortable pronated or supinated handle position, sit upright, and set a light load that lets you keep your wrists straight.","Close the handles by flexing your fingers; keep your wrists still and avoid leaning your body into the squeeze.","Let the handles open slowly under control and stop before your grip slips."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/plate-loaded-machine-gripper.webp"]}},{"id":"atlas-plate-loaded-machine-shrug","name":"Plate-Loaded Shrug (Machine)","equipment":"machine","primaryMuscles":["traps"],"secondaryMuscles":["forearms"],"category":"isolation","instructions":["Choose the seated or standing setup, set the machine stops if present, and hold the side handles with your arms straight.","Raise your shoulders vertically toward your ears without bending your elbows or rolling your shoulders.","Lower your shoulders slowly to the start position while keeping the plates under control."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/plate-loaded-machine-shrug.webp"]}},{"id":"atlas-plate-loaded-reverse-lunge","name":"Plate-Loaded Reverse Lunge (Machine)","equipment":"machine","primaryMuscles":["quads","glutes"],"secondaryMuscles":["adductors","hamstrings"],"category":"compound","instructions":["Follow the machine placard to set the shoulder pad and starting position. Place the front foot on the fixed platform and the rear foot on the sliding platform; hold the handles and brace your torso.","Bend both knees and lower under control as the rear platform glides back along its inclined guide. Keep the front foot planted and the front knee aligned with the toes.","Press through the front foot to return to the start while guiding the handles smoothly. Complete the repetitions on one side, then switch; use a load you can control."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/plate-loaded-reverse-lunge.webp"]}},{"id":"atlas-plate-loaded-seated-dip","name":"Plate-Loaded Seated Dip (Machine)","equipment":"machine","primaryMuscles":["triceps"],"secondaryMuscles":["chest","shoulders"],"category":"compound","instructions":["Choose the face-in setup, adjust the seat so the handles are within comfortable reach, plant your feet, and secure the thigh restraint if present.","Keep your torso against the support and press the handles down until your elbows are nearly straight; do not snap them into lockout.","Let the handles rise slowly until your elbows bend comfortably, keeping the plates under control."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/plate-loaded-seated-dip.webp"]}},{"id":"atlas-plate-loaded-super-fly","name":"Plate-Loaded Super Fly (Machine)","equipment":"machine","primaryMuscles":["chest"],"secondaryMuscles":["shoulders"],"category":"isolation","instructions":["Load both sides evenly, choose a flat or decline path, and set the range stop before sitting; adjust the seat so the handles start around mid-chest.","With your back supported and elbows softly bent, bring the handles together in a smooth arc without shrugging.","Open your arms slowly to a comfortable chest stretch; do not force your elbows far behind your torso."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/plate-loaded-super-fly.webp"]}},{"id":"atlas-plate-loaded-super-squat-press","name":"Plate-Loaded Super Squat Press (Machine)","equipment":"machine","primaryMuscles":["quads"],"secondaryMuscles":["glutes","hamstrings"],"category":"compound","instructions":["Load both sides evenly and set the machine safety; place your shoulders and back against the pads and both feet securely on the platforms.","Bend your hips and knees to lower into a comfortable squat while keeping your heels planted and knees tracking over your toes.","Drive through the platforms to stand, stop before locking your knees, then engage the safety before stepping off."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/plate-loaded-super-squat-press.webp"]}},{"id":"atlas-plate-loaded-tibia-dorsi-flexion","name":"Plate-Loaded Tibia Dorsi-Flexion (Machine)","equipment":"machine","primaryMuscles":["calves"],"secondaryMuscles":[],"category":"isolation","instructions":["Sit with your lower back supported, place your thighs under the restraint, and position the padded lever over the front of your shoe; begin with a light load.","Keep your knee still and lift your forefoot toward your shin by moving at the ankle.","Lower the lever slowly until you feel a comfortable stretch; avoid bouncing or forcing the ankle range."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/plate-loaded-tibia-dorsi-flexion.webp"]}},{"id":"atlas-plate-pinch","name":"Plate Pinch","equipment":"other","primaryMuscles":["forearms"],"secondaryMuscles":[],"category":"isolation","instructions":["Pinch two weight plates together with your fingertips, smooth sides facing outward.","Keeping your shoulders relaxed, continue gripping the plates beside you for a controlled period of time.","Lower the plates safely without dropping them on your feet; if you are about to lose your grip, put them down on the floor."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/plate-pinch.webp"]}},{"id":"atlas-plate-pinch-carry","name":"Plate Pinch Carry","equipment":"other","primaryMuscles":["forearms"],"secondaryMuscles":[],"category":"compound","instructions":["Pinch a light plate at your side with fingers on one face and thumb on the other.","Stand tall and walk with short steps, keeping the plate clear of your leg.","Set it down safely before your grip fails; change hands."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/plate-pinch-carry.webp"]}},{"id":"atlas-pogo-hops","name":"Pogo Hops","equipment":"bodyweight","primaryMuscles":["calves"],"secondaryMuscles":[],"category":"isolation","isBodyweight":true,"instructions":["Stand tall with the feet hip-width apart and the knees slightly softened.","Make small, rhythmic hops from the ankles, touching the floor lightly with the forefoot.","Continue with soft landings without bending the knees deeply; stop if you feel discomfort."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/pogo-hops.webp"]}},{"id":"atlas-prone-cobra-hold","name":"Prone Cobra Hold","equipment":"bodyweight","primaryMuscles":["lower_back"],"secondaryMuscles":["back","traps"],"category":"compound","isBodyweight":true,"instructions":["Lie face down with your arms beside your body and rest your forehead comfortably on the floor.","Keeping your neck neutral, lift your chest and hands slightly; gently draw your shoulder blades down and back.","Hold briefly and lower under control; if you feel discomfort in your lower back, reduce the lift height or stop."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/prone-cobra-hold.webp"]}},{"id":"atlas-prone-incline-y-raise","name":"Prone Incline Y Raise","equipment":"dumbbell","primaryMuscles":["back"],"secondaryMuscles":["traps","shoulders"],"category":"isolation","instructions":["Lie face down on an incline bench with light dumbbells; extend your arms in a Y shape in front of your head.","With your thumbs pointing up, raise your arms under control; keep your neck and torso still.","Lower the dumbbells slowly; if you feel pinching in your shoulders, reduce the weight or stop the movement."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/prone-incline-y-raise.webp"]}},{"id":"atlas-prone-reverse-hyperextension","name":"Prone Reverse Hyperextension","equipment":"bodyweight","primaryMuscles":["lower_back"],"secondaryMuscles":["glutes","hamstrings"],"category":"compound","isBodyweight":true,"instructions":["Lie face down with hips supported on a stable bench; hold its sides and keep spine neutral.","With knees softly bent, lift legs until they align with your torso.","Lower slowly without swinging or arching the lower back."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/prone-reverse-hyperextension.webp"]}},{"id":"atlas-prone-snow-angel","name":"Prone Snow Angel","equipment":"bodyweight","primaryMuscles":["back"],"secondaryMuscles":["shoulders"],"category":"compound","isBodyweight":true,"instructions":["Lie face down on a bench with your chest supported and arms beside your hips.","Keeping elbows straight, sweep both arms outward and overhead into a comfortable Y.","Lower along the same path without shrugging or arching your lower back."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/prone-snow-angel.webp"]}},{"id":"atlas-prone-t-raise","name":"Prone T Raise","equipment":"dumbbell","primaryMuscles":["back"],"secondaryMuscles":["shoulders","traps"],"category":"isolation","instructions":["Lie chest-down on a bench with light dumbbells hanging below the shoulders.","Raise the arms outward into a T without lifting the torso or shrugging.","Lower slowly to the hanging position."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/prone-t-raise.webp"]}},{"id":"atlas-prone-trap-3-raise","name":"Prone Trap-3 Raise","equipment":"dumbbell","primaryMuscles":["traps"],"secondaryMuscles":["shoulders","back"],"category":"isolation","instructions":["Lie face down on an incline bench with light dumbbells; let your arms hang in a Y shape in front of your head.","With your thumbs pointing up, raise your arms under control along the Y line; keep your neck neutral.","Lower the dumbbells slowly; if you feel pinching in your shoulders, reduce the load or stop."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/prone-trap-3-raise.webp"]}},{"id":"atlas-prone-w-raise","name":"Prone W Raise","equipment":"bodyweight","primaryMuscles":["back"],"secondaryMuscles":["shoulders","traps"],"category":"compound","isBodyweight":true,"instructions":["Lie face down and bend elbows beside the ribs into a W.","Draw the shoulder blades together and lift hands and elbows slightly.","Lower with control and relax the neck."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/prone-w-raise.webp"]}},{"id":"atlas-quadruped-adductor-rockback","name":"Quadruped Adductor Rockback","equipment":"bodyweight","primaryMuscles":["adductors"],"secondaryMuscles":[],"category":"mobility","isBodyweight":true,"instructions":["Start on hands and knees and extend one leg to the side with foot flat.","Keep your back long and shift hips toward heels to a mild inner-thigh stretch.","Return forward within a comfortable pain-free range; switch sides."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/quadruped-adductor-rockback.webp"]}},{"id":"atlas-quadruped-fire-hydrant","name":"Quadruped Fire Hydrant","equipment":"bodyweight","primaryMuscles":["abductors"],"secondaryMuscles":["glutes"],"category":"isolation","isBodyweight":true,"instructions":["Get on your hands and knees; place your hands under your shoulders and your knees under your hips.","Keeping your knee bent, lift one leg out to the side; keep your pelvis parallel to the floor and your torso still.","Slowly lower the knee and switch sides; work in a pain-free range without rotating your lower back sideways."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/quadruped-fire-hydrant.webp"]}},{"id":"atlas-recumbent-bike","name":"Recumbent Bike","equipment":"machine","primaryMuscles":["quads"],"secondaryMuscles":["calves","glutes","hamstrings"],"category":"cardio","instructions":["Sit back against the backrest and adjust the seat so your knee stays slightly bent when the far pedal reaches the bottom of its stroke; adjust while the pedals are stopped.","Place the balls of your feet on the pedals and secure the straps if fitted. Hold the side handles and pedal smoothly without locking your knees or rocking in the seat.","Start at a comfortable resistance, ease your pace down before stopping, and wait for the pedals to settle before stepping off."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/recumbent-bike.webp"]}},{"id":"atlas-reverse-crunch","name":"Reverse Crunch","equipment":"bodyweight","primaryMuscles":["abs"],"secondaryMuscles":[],"category":"compound","isBodyweight":true,"instructions":["Lie on your back and bend your knees; place your arms on the floor beside your torso.","Brace your abs, bring your knees toward your chest and lift your pelvis slightly off the floor.","Lower your legs back to the start in a controlled way without swinging them."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/reverse-crunch.webp"]}},{"id":"atlas-reverse-grip-triceps-pushdown","name":"Reverse Grip Triceps Pushdown (Cable)","equipment":"cable","primaryMuscles":["triceps"],"secondaryMuscles":[],"category":"isolation","instructions":["Attach a straight bar to a high pulley and grip it with your palms facing up; keep your elbows close to your torso.","Keeping your upper arms still, extend your elbows and push the bar down.","Bend your arms under control to return to the start; keep your wrists in a comfortable position."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/reverse-grip-triceps-pushdown.webp"]}},{"id":"atlas-reverse-hyperextension","name":"Reverse Hyperextension (Machine)","equipment":"machine","primaryMuscles":["lower_back"],"secondaryMuscles":["glutes","hamstrings"],"category":"compound","instructions":["Lie face down on the reverse-hyper bench with your hips supported at the edge of the pad.","Raise your legs under control until they are in line with your torso; do not over-arch your lower back.","Lower your legs slowly; work within a small, pain-free range."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/reverse-hyperextension.webp"]}},{"id":"atlas-reverse-lunge","name":"Reverse Lunge","equipment":"bodyweight","primaryMuscles":["quads","glutes"],"secondaryMuscles":["hamstrings"],"category":"compound","isBodyweight":true,"instructions":["Stand upright and step one foot back.","Lower both knees under control, return and change sides."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/reverse-lunge.webp"]}},{"id":"atlas-reverse-lunge-knee-drive","name":"Reverse Lunge to Knee Drive","equipment":"bodyweight","primaryMuscles":["glutes","quads"],"secondaryMuscles":["abs"],"category":"compound","isBodyweight":true,"instructions":["Stand tall and step one foot back into a comfortable reverse lunge.","Push through the front foot and bring the rear knee toward hip height without leaning back.","Return to the lunge with control; complete the side and switch."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/reverse-lunge-knee-drive.webp"]}},{"id":"atlas-reverse-nordic-curl","name":"Reverse Nordic Curl","equipment":"bodyweight","primaryMuscles":["quads"],"secondaryMuscles":["abs"],"category":"isolation","isBodyweight":true,"instructions":["Kneel with a pad under the knees; keep the hips open and the torso straight.","Keeping the hips in line, lean the torso back slightly from the knees.","Squeeze the front of the thighs to return upright; start with a small range and stop if the knees hurt."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/reverse-nordic-curl.webp"]}},{"id":"atlas-reverse-plank-leg-lift","name":"Reverse-Plank Leg Lift","equipment":"bodyweight","primaryMuscles":["glutes"],"secondaryMuscles":["hamstrings","shoulders"],"category":"compound","isBodyweight":true,"instructions":["Sit with hands behind you and feet planted; lift your hips into a reverse plank.","Keep your trunk steady and raise one straight leg a short distance.","Lower the leg, then switch sides while keeping hips lifted if comfortable."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/reverse-plank-leg-lift.webp"]}},{"id":"atlas-reverse-sled-drag","name":"Reverse Sled Drag","equipment":"other","primaryMuscles":["quads"],"secondaryMuscles":["calves","glutes"],"category":"cardio","instructions":["Face the sled and hold the straps with light tension, knees slightly bent.","Take short backward steps away from the sled while pulling it along the floor.","Keep a steady pace and upright torso; choose a load that allows smooth steps."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/reverse-sled-drag.webp"]}},{"id":"atlas-romanian-deadlift-from-deficit","name":"Romanian Deadlift from Deficit","equipment":"barbell","primaryMuscles":["hamstrings"],"secondaryMuscles":["glutes","lower_back"],"category":"compound","instructions":["Stand on a low, stable platform with both feet fully supported, holding the bar in front of your thighs. Use a light load and keep a slight bend in your knees.","Push your hips back and lower the bar close along your legs while keeping your back neutral. Stop when your hamstrings limit the motion or before your back rounds; the bar does not need to reach the floor.","Drive your hips forward to return to standing without leaning back at the top."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/romanian-deadlift-from-deficit.webp"]}},{"id":"atlas-rowing-machine","name":"Indoor Rowing","equipment":"machine","primaryMuscles":["quads","glutes","hamstrings"],"secondaryMuscles":["lats","back","abs","shoulders","biceps","forearms","triceps","calves"],"category":"cardio","instructions":["Adjust the foot straps over the widest part of your feet and sit on the sliding seat. Reach to the catch with arms straight, shins near vertical, and a comfortable hip hinge; keep your back neutral.","Drive by pressing through the footplates with your legs first. As the legs extend, swing your torso open from the hips, then draw the handle to your lower ribs with relaxed shoulders and flat wrists.","For recovery, extend your arms first, hinge your torso forward, then bend your knees and slide toward the flywheel smoothly. Keep the return controlled and begin at an easy pace."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/rowing-machine.webp"]}},{"id":"atlas-scapular-pull-up","name":"Scapular Pull-Up","equipment":"bodyweight","primaryMuscles":["traps"],"secondaryMuscles":["lats","back"],"category":"compound","isBodyweight":true,"instructions":["Hang from a sturdy bar with your arms straight and your shoulders away from your ears.","Without bending your elbows, pull your shoulder blades down to raise your body a very small amount.","Return under control to a relaxed hang; repeat in a small range without swinging."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/scapular-pull-up.webp"]}},{"id":"atlas-seal-row","name":"Seal Row","equipment":"dumbbell","primaryMuscles":["back"],"secondaryMuscles":["lats","biceps"],"category":"compound","instructions":["Lie face down on a high bench with your chest supported and your arms hanging down; hold light dumbbells.","Pull your elbows back and raise the dumbbells toward the bench; do not lift your torso off the support.","Lower the weights under control and do not shrug your shoulders toward your ears."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/seal-row.webp"]}},{"id":"atlas-seated-active-neck-rotation","name":"Seated Active Neck Rotation","equipment":"bodyweight","primaryMuscles":["neck"],"secondaryMuscles":[],"category":"mobility","isBodyweight":true,"instructions":["Sit tall with shoulders relaxed and eyes forward.","Turn the head gently toward one side within a comfortable range while the torso stays still.","Return to center and repeat on the other side; stop if pain, numbness, or dizziness occurs."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/seated-active-neck-rotation.webp"]}},{"id":"atlas-seated-back-extension","name":"Seated Back Extension (Machine)","equipment":"machine","primaryMuscles":["lower_back"],"secondaryMuscles":["glutes","hamstrings"],"category":"compound","instructions":["Adjust the machine so your hips can hinge freely and the torso pad makes comfortable contact.","Lean your torso forward from the hips; keeping your back neutral, extend back up to an upright position under control.","Return to the start without taking your torso past upright; stop if you feel pain."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/seated-back-extension.webp"]}},{"id":"atlas-seated-band-hip-abduction","name":"Seated Band Hip Abduction","equipment":"band","primaryMuscles":["abductors"],"secondaryMuscles":["glutes"],"category":"isolation","instructions":["Sit upright with feet flat and a light loop band just above the knees.","Move both knees outward against the band without lifting the feet or leaning back.","Bring the knees inward slowly without letting the band snap them together."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/seated-band-hip-abduction.webp"]}},{"id":"atlas-seated-cable-chest-press","name":"Seated Chest Press (Cable)","equipment":"cable","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"category":"compound","instructions":["Set two cable pulleys around mid-chest height. Sit upright on a backed bench between them, plant your feet, and hold one handle beside each side of your chest.","Keep your back against the support and press both handles forward at chest height until your elbows are almost straight; keep your wrists neutral.","Return the handles slowly toward your chest without letting the cables pull your shoulders forward or arching your lower back."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/seated-cable-chest-press.webp"]}},{"id":"atlas-seated-close-grip-cable-row","name":"Seated Close-Grip Row (Cable)","equipment":"cable","primaryMuscles":["back"],"secondaryMuscles":["lats","biceps"],"category":"compound","instructions":["Place your feet on the platform, bend your knees slightly and grip the handle.","Without swinging your torso, pull your elbows back and bring the handle toward your lower ribs.","Extend your arms under control without letting your shoulders drop forward."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/seated-close-grip-cable-row.webp"]}},{"id":"atlas-seated-decline-cable-press","name":"Seated Decline Press (Cable)","equipment":"cable","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"category":"compound","instructions":["Sit with your back against the support, feet planted, and one handle just below each side of your chest; keep wrists neutral and shoulder blades down and back.","Press the handles forward and down toward your thighs while keeping your back and shoulder blades supported.","Stop before locking your elbows, then slowly return the handles toward your lower chest without rounding your shoulders."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/seated-decline-cable-press.webp"]}},{"id":"atlas-seated-dumbbell-calf-raise","name":"Seated Calf Raise (Dumbbell)","equipment":"dumbbell","primaryMuscles":["calves"],"secondaryMuscles":[],"category":"isolation","instructions":["Sit on a bench; place the toes on a low, stable raised surface and bend the knees to about a right angle.","Place the dumbbell securely just above the knees and raise the heels in a controlled way.","Pause briefly and lower the heels slowly; do not press the weight into the kneecaps and do not bounce."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/seated-dumbbell-calf-raise.webp"]}},{"id":"atlas-seated-dumbbell-finger-curl","name":"Seated Finger Curl (Dumbbell)","equipment":"dumbbell","primaryMuscles":["forearms"],"secondaryMuscles":[],"category":"isolation","instructions":["Sit with forearms supported on the thighs, palms up, and light dumbbells held securely.","Let the handles roll toward the fingertips without releasing them, then close the fingers firmly around the handles.","Return slowly; use a load you can control throughout."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/seated-dumbbell-finger-curl.webp"]}},{"id":"atlas-seated-dumbbell-shoulder-press","name":"Seated Shoulder Press (Dumbbell)","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps"],"category":"compound","instructions":["Sit on a bench with back support and hold the dumbbells at shoulder height, with your wrists above your elbows.","Keeping your torso still, press the dumbbells overhead.","Lower the dumbbells under control to shoulder height; do not over-arch your lower back."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/seated-dumbbell-shoulder-press.webp"]}},{"id":"atlas-seated-dumbbell-wrist-curl","name":"Seated Wrist Curl (Dumbbell)","equipment":"dumbbell","primaryMuscles":["forearms"],"secondaryMuscles":[],"category":"isolation","instructions":["Sit and rest your forearms on your thighs, letting your wrists hang freely in front of your knees.","Grip the dumbbells; with your forearms still, curl your wrists upward under control.","Lower the weight slowly and keep the movement within a pain-free range."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/seated-dumbbell-wrist-curl.webp"]}},{"id":"atlas-seated-high-back-row","name":"Seated High Back Row (Cable)","equipment":"cable","primaryMuscles":["back"],"secondaryMuscles":["lats","biceps","shoulders"],"category":"compound","instructions":["Sit facing a low cable with your knees softly bent and feet braced. Hold a wide straight bar with an overhand grip and keep your back tall.","Pull the bar toward your upper chest with your elbows traveling out to the sides; keep your torso steady and avoid shrugging.","Straighten your arms slowly to return the weight under control without rounding your back."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/seated-high-back-row.webp"]}},{"id":"atlas-seated-hip-adduction","name":"Seated Hip Adduction (Machine)","equipment":"machine","primaryMuscles":["adductors"],"secondaryMuscles":[],"category":"isolation","instructions":["Adjust the machine to your body and place the insides of your knees on the pads.","Lean back against the support and bring the pads together in a controlled way.","Resist the pull of the weight and slowly open your legs back to the start."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/seated-hip-adduction.webp"]}},{"id":"atlas-seated-incline-cable-press","name":"Seated Incline Press (Cable)","equipment":"cable","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"category":"compound","instructions":["Sit with your back against the incline support, feet planted, and one handle beside each side of your upper chest; keep wrists neutral and shoulder blades down and back.","Press the handles forward and upward toward forehead height without arching your lower back or rounding your shoulders.","Stop just short of locking the elbows, pause briefly, then return the handles slowly to the upper chest."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/seated-incline-cable-press.webp"]}},{"id":"atlas-seated-machine-biceps-curl","name":"Seated Biceps Curl (Machine)","equipment":"machine","primaryMuscles":["biceps"],"secondaryMuscles":["forearms"],"category":"isolation","instructions":["Adjust the seat so your elbows line up with the machine pivot; sit upright and place your upper arms on the angled pad.","Keeping your wrists neutral and upper arms on the pad, curl the handles toward your chest without rocking your torso.","Lower the handles slowly until your arms are nearly straight, without locking your elbows."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/seated-machine-biceps-curl.webp"]}},{"id":"atlas-seated-machine-crunch","name":"Seated Crunch (Machine)","equipment":"machine","primaryMuscles":["abs"],"secondaryMuscles":[],"category":"compound","instructions":["Adjust the seat and resistance; sit with hips against the back of the seat, feet planted and hands on the handles.","Keep your hips seated and curl your rib cage gently toward your pelvis as the handles move down.","Return slowly without jerking the weight or pulling with your arms; keep your neck relaxed."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/seated-machine-crunch.webp"]}},{"id":"atlas-seated-machine-leg-press","name":"Seated Leg Press (Machine)","equipment":"machine","primaryMuscles":["quads"],"secondaryMuscles":["glutes","hamstrings"],"category":"compound","instructions":["Adjust the seat so your back and hips remain supported and your knees are comfortably bent at the start; place both feet on the footplate.","Press the footplate away through your whole feet without lifting your hips from the seat.","Bend your knees under control to return the footplate, stopping before your lower back or pelvis rolls away from the pad."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/seated-machine-leg-press.webp"]}},{"id":"atlas-seated-machine-row","name":"Seated Row (Machine)","equipment":"machine","primaryMuscles":["lats","back"],"secondaryMuscles":["biceps"],"category":"compound","instructions":["Adjust the seat and chest pad so the handles are near mid-torso height; plant your feet on the rests and reach for the handles.","Keep your chest against the pad and pull the handles horizontally toward your lower ribs, driving your elbows behind you.","Extend your arms slowly without letting the weight stack pull your torso forward."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/seated-machine-row.webp"]}},{"id":"atlas-seated-machine-triceps-extension","name":"Seated Triceps Extension (Machine)","equipment":"machine","primaryMuscles":["triceps"],"secondaryMuscles":[],"category":"isolation","instructions":["Adjust the seat so your elbows align with the machine pivots; rest your upper arms on the pads and hold the handles with neutral wrists.","Keep the upper arms supported and extend the elbows to move the handles forward and down without locking out.","Bend the elbows slowly to return the handles, keeping your back against the support."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/seated-machine-triceps-extension.webp"]}},{"id":"atlas-seated-neck-cars","name":"Seated Neck CARs","equipment":"bodyweight","primaryMuscles":["neck"],"secondaryMuscles":[],"category":"mobility","isBodyweight":true,"instructions":["Sit tall with shoulders relaxed and gaze forward.","Slowly turn the head and trace a gentle arc with the chin without forcing range.","Return to center and reverse; stop for pain, dizziness or unusual symptoms."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/seated-neck-cars.webp"]}},{"id":"atlas-seated-one-arm-cable-row","name":"Seated One-Arm Row (Cable)","equipment":"cable","primaryMuscles":["back","lats"],"secondaryMuscles":["biceps","shoulders"],"category":"compound","instructions":["Sit at a low cable row station and brace both feet on the footplates. Hold a single handle in one hand with your knees slightly bent and back neutral; let the working arm reach forward under tension.","Keep your torso steady and elbow close to your side as you pull the handle toward your lower ribs or abdomen. Pause briefly without twisting your body.","Extend the working arm forward under control. Complete the set on this side, then switch hands."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/seated-one-arm-cable-row.webp"]}},{"id":"atlas-selectorized-arc-leg-press","name":"Selectorized Arc Leg Press (Machine)","equipment":"machine","primaryMuscles":["quads","glutes"],"secondaryMuscles":["hamstrings"],"category":"compound","instructions":["Adjust the seat carriage and depth-assist handle while seated to set a comfortable start depth. Place your feet about shoulder-width apart on the footplate and keep your back and hips supported.","Press through your whole foot to extend your hips and knees along the curved path; stop before your knees lock.","Bend your knees and hips slowly to return the footplate along the arc to your selected depth, keeping your back and pelvis supported."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/selectorized-arc-leg-press.webp"]}},{"id":"atlas-selectorized-dual-axis-chest-press","name":"Selectorized Dual-Axis Chest Press (Machine)","equipment":"machine","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"category":"compound","instructions":["Set the weight stack and seat so the handles begin around mid-chest; while seated, adjust the starting depth to a comfortable range. Keep your back supported and feet planted.","Press the handles forward and let the independent arms move inward along their natural path. Keep your wrists straight and stop before your elbows lock.","Return the handles slowly, allowing the arms to open until you feel a comfortable chest stretch; keep the weight stack under control."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/selectorized-dual-axis-chest-press.webp"]}},{"id":"atlas-selectorized-dual-axis-lat-pulldown","name":"Selectorized Dual-Axis Lat Pulldown (Machine)","equipment":"machine","primaryMuscles":["lats"],"secondaryMuscles":["biceps","back","forearms"],"category":"compound","instructions":["Set the weight stack and seat; position your thighs securely under the angled pads and reach overhead to grip the handles comfortably.","Keep your torso steady and pull the independent handles down and slightly outward, driving your elbows toward your sides until the handles reach shoulder or upper-chest level.","Let the handles rise overhead slowly along their path, keeping the weight stack controlled and shoulders relaxed."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/selectorized-dual-axis-lat-pulldown.webp"]}},{"id":"atlas-selectorized-triceps-press","name":"Selectorized Triceps Press (Machine)","equipment":"machine","primaryMuscles":["triceps"],"secondaryMuscles":["chest","shoulders"],"category":"compound","instructions":["Set the weight stack and seat so you can reach the handles while sitting with your back supported and feet planted. Grip the rotating handles comfortably with elbows bent.","Keep your back against the pad and press the handles down and slightly forward until your elbows are nearly straight; do not snap them into lockout.","Let the handles rise slowly as your elbows bend, keeping the weight stack under control."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/selectorized-triceps-press.webp"]}},{"id":"atlas-side-crunch","name":"Side Crunch","equipment":"bodyweight","primaryMuscles":["abs"],"secondaryMuscles":[],"category":"compound","isBodyweight":true,"instructions":["Lie on your side with knees bent and hips stacked; place your upper hand lightly by your head or torso.","Brace your trunk and lift your rib cage toward your hip in a short side crunch.","Lower slowly and repeat, then switch sides; keep the movement small and controlled."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/side-crunch.webp"]}},{"id":"atlas-side-lying-dumbbell-shoulder-external-rotation","name":"Side-Lying Shoulder External Rotation (Dumbbell)","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":[],"category":"isolation","instructions":["Lie on your side with your working elbow bent about 90 degrees and tucked against your ribs; place a small folded towel between the elbow and torso and hold a very light dumbbell.","Keeping your elbow and upper arm still, rotate your forearm upward away from your abdomen through a comfortable range; do not roll your torso backward.","Lower the dumbbell slowly to the start position. Use a light load and stop if the movement causes pain."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/side-lying-dumbbell-shoulder-external-rotation.webp"]}},{"id":"atlas-side-lying-hip-abduction","name":"Side-Lying Hip Abduction","equipment":"bodyweight","primaryMuscles":["abductors"],"secondaryMuscles":["glutes"],"category":"isolation","isBodyweight":true,"instructions":["Lie on your side and support your head with your arm; keep your top leg straight and your torso stable.","Lift your top leg from the hip in a controlled way; try not to turn your foot forward.","Slowly lower your leg and work both sides."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/side-lying-hip-abduction.webp"]}},{"id":"atlas-side-lying-hip-adduction","name":"Side-Lying Hip Adduction","equipment":"bodyweight","primaryMuscles":["adductors"],"secondaryMuscles":["glutes"],"category":"isolation","isBodyweight":true,"instructions":["Lie on your side; bend your top leg and place that foot on the floor in front of your bottom leg.","Keeping your bottom leg straight, lift it off the floor in a controlled way.","Slowly lower your leg; work both sides without rolling your hips backward."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/side-lying-hip-adduction.webp"]}},{"id":"atlas-side-lying-thoracic-windmill","name":"Side-Lying Thoracic Windmill","equipment":"bodyweight","primaryMuscles":["back"],"secondaryMuscles":["shoulders","abs"],"category":"mobility","isBodyweight":true,"instructions":["Lie on your side with hips and knees bent and stacked; extend both arms in front.","Keep the knees together and sweep the top arm in a wide arc toward the floor behind you.","Rotate through the upper back only; keep the head comfortable and return to the start."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/side-lying-thoracic-windmill.webp"]}},{"id":"atlas-side-plank-hip-abduction","name":"Side Plank Hip Abduction","equipment":"bodyweight","primaryMuscles":["abductors"],"secondaryMuscles":["glutes","abs"],"category":"compound","isBodyweight":true,"instructions":["Get into a forearm plank position; start with your bottom knee on the floor if needed.","Stack your hips and lift your top leg upward in a controlled way.","Lower the leg and switch sides; work within the range where you can keep your lower back from rotating."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/side-plank-hip-abduction.webp"]}},{"id":"atlas-side-plank-reach-through","name":"Side Plank Reach-Through","equipment":"bodyweight","primaryMuscles":["abs"],"secondaryMuscles":["shoulders"],"category":"compound","isBodyweight":true,"instructions":["Set a forearm side plank with your elbow below your shoulder and hips lifted.","Reach the top arm under your torso and rotate only as far as you can control.","Open your chest and return the arm upward; switch sides after the set."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/side-plank-reach-through.webp"]}},{"id":"atlas-side-plank-star","name":"Side-Plank Star","equipment":"bodyweight","primaryMuscles":["abductors"],"secondaryMuscles":["abs","glutes"],"category":"compound","isBodyweight":true,"instructions":["Lie on your side with supporting elbow below shoulder and legs stacked.","Lift hips, then raise the top leg and reach the upper arm if stable.","Lower with control; bend the knees for an easier version."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/side-plank-star.webp"]}},{"id":"atlas-side-v-up","name":"Side V-Up","equipment":"bodyweight","primaryMuscles":["abs"],"secondaryMuscles":[],"category":"compound","isBodyweight":true,"instructions":["Lie on one side with legs together and the lower arm extended for support; brace your trunk.","Lift both legs and your upper body toward each other in a controlled side crunch.","Lower smoothly to the start, repeat, then switch sides; use a smaller range if needed."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/side-v-up.webp"]}},{"id":"atlas-single-arm-cable-crossover","name":"Single-Arm Crossover (Cable)","equipment":"cable","primaryMuscles":["chest"],"secondaryMuscles":["shoulders"],"category":"compound","instructions":["Set a single cable pulley high and attach one handle. Stand in a staggered stance with the working side away from the pulley; hold the handle with a soft bend in your elbow.","Keeping your torso steady, let the working arm open outward to about shoulder height, then pull the handle inward across the front of your chest without rotating your body.","Return the arm outward under control to a comfortable stretch. Complete the repetitions, then turn around and work the other side."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/single-arm-cable-crossover.webp"]}},{"id":"atlas-single-arm-cable-lateral-raise","name":"Single-Arm Lateral Raise (Cable)","equipment":"cable","primaryMuscles":["shoulders"],"secondaryMuscles":["traps"],"category":"isolation","instructions":["Use a low pulley; stand sideways to the cable and grip the handle with your far hand.","Keeping your elbow slightly bent, raise your arm out to the side up to shoulder height.","Lower your arm slowly without swinging your torso; reduce the range if you feel pinching in the shoulder."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/single-arm-cable-lateral-raise.webp"]}},{"id":"atlas-single-arm-cable-pushdown","name":"Single-Arm Pushdown (Cable)","equipment":"cable","primaryMuscles":["triceps"],"secondaryMuscles":[],"category":"isolation","instructions":["Set the cable to the upper position and grip the single handle; keep your elbow fixed at your side.","Extend your elbow and push the handle down; do not move your upper arm or shoulder.","Raise your forearm back to the start under control; work both arms equally."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/single-arm-cable-pushdown.webp"]}},{"id":"atlas-single-arm-cable-row","name":"Single-Arm Row (Cable)","equipment":"cable","primaryMuscles":["lats"],"secondaryMuscles":["back","biceps"],"category":"compound","instructions":["Set a single cable handle around lower-chest height. Face the pulley in a stable split stance with your working arm extended and torso upright.","Pull the handle toward your lower ribs by driving your elbow back close to your side; keep your shoulders and hips square.","Return the handle slowly until your arm is extended again without letting the cable rotate your torso; repeat on the other side."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/single-arm-cable-row.webp"]}},{"id":"atlas-single-arm-dumbbell-chest-press","name":"Single-Arm Chest Press (Dumbbell)","equipment":"dumbbell","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps","abs"],"category":"compound","instructions":["Lie on a flat bench with feet planted; hold one dumbbell beside the chest and keep the free hand safely at your side.","Press the dumbbell above the chest while keeping both shoulders and hips level.","Lower under control and repeat; switch arms and use a load that lets you resist torso rotation."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/single-arm-dumbbell-chest-press.webp"]}},{"id":"atlas-single-arm-dumbbell-clean","name":"Single-Arm Clean (Dumbbell)","equipment":"dumbbell","primaryMuscles":["glutes","quads","traps"],"secondaryMuscles":["hamstrings","shoulders","abs"],"category":"compound","instructions":["Place one dumbbell just outside your working foot. Set your feet about hip-width apart, hinge and bend your knees to grip it with a neutral spine.","Drive through the floor and extend your hips and knees; keep the dumbbell close, shrug, and guide it to your shoulder as you rotate your elbow forward, catching with a slight knee bend.","Stand tall, then lower the dumbbell smoothly to the floor and reset before switching hands."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/single-arm-dumbbell-clean.webp"]}},{"id":"atlas-single-arm-high-cable-row","name":"Single-Arm High Row (Cable)","equipment":"cable","primaryMuscles":["lats"],"secondaryMuscles":["biceps","back"],"category":"compound","instructions":["Stand facing a high pulley and reach one arm up to take the handle.","Pull the elbow down toward the lower ribs while keeping the torso steady.","Extend the arm upward under control; repeat on the other side."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/single-arm-high-cable-row.webp"]}},{"id":"atlas-single-arm-iso-lateral-machine-row","name":"Single-Arm Iso-Lateral Row (Machine)","equipment":"machine","primaryMuscles":["lats"],"secondaryMuscles":["back","biceps"],"category":"compound","instructions":["Sit against the chest pad, plant your feet, and grasp both independent handles; keep the non-working hand braced on its handle.","Pull one elbow toward your hip without rotating your torso or lifting your chest from the pad.","Extend that arm slowly, then repeat on the other side; keep the plates controlled throughout."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/single-arm-iso-lateral-machine-row.webp"]}},{"id":"atlas-single-arm-kneeling-lat-pulldown","name":"Single-Arm Kneeling Lat Pulldown (Cable)","equipment":"cable","primaryMuscles":["lats"],"secondaryMuscles":["biceps","back"],"category":"compound","instructions":["Attach a single handle to the high pulley; kneel beside the machine and grip the handle with your upper hand.","Keeping your torso upright and still, pull your elbow down toward your ribs.","Extend your arm back up under control; work both sides."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/single-arm-kneeling-lat-pulldown.webp"]}},{"id":"atlas-single-arm-overhead-dumbbell-triceps-extension","name":"Single-Arm Overhead Triceps Extension (Dumbbell)","equipment":"dumbbell","primaryMuscles":["triceps"],"secondaryMuscles":["shoulders"],"category":"isolation","instructions":["Stand tall with one light dumbbell overhead and the upper arm beside the ear; bend the elbow to lower it behind the head.","Extend the elbow until the arm is nearly straight, without arching the back.","Lower slowly behind the head and switch arms after the set."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/single-arm-overhead-dumbbell-triceps-extension.webp"]}},{"id":"atlas-single-dumbbell-suitcase-march","name":"Single-Suitcase March (Dumbbell)","equipment":"dumbbell","primaryMuscles":["abs"],"secondaryMuscles":["forearms"],"category":"compound","instructions":["Hold one dumbbell at your side and stand tall.","Lift the opposite knee to about hip height without leaning toward the weight.","Lower the foot quietly and alternate sides while keeping your trunk steady."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/single-dumbbell-suitcase-march.webp"]}},{"id":"atlas-single-leg-box-squat","name":"Single-Leg Box Squat","equipment":"bodyweight","primaryMuscles":["quads"],"secondaryMuscles":["glutes"],"category":"compound","isBodyweight":true,"instructions":["Stand on one leg in front of a stable box and extend the free leg forward.","Reach your hips back and lightly touch the box without dropping onto it.","Press through the planted foot to stand; use a higher box to scale."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/single-leg-box-squat.webp"]}},{"id":"atlas-single-leg-dumbbell-calf-raise","name":"Single-Leg Calf Raise (Dumbbell)","equipment":"dumbbell","primaryMuscles":["calves"],"secondaryMuscles":[],"category":"isolation","instructions":["Stand with the ball of one foot on a stable step and hold a dumbbell at your side; use a support lightly if needed for balance.","Lower your heel below the step under control, keeping your standing knee softly extended.","Press through the ball of your foot to rise onto your toes, then lower slowly; complete the set and switch sides."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/single-leg-dumbbell-calf-raise.webp"]}},{"id":"atlas-single-leg-glute-bridge","name":"Single Leg Glute Bridge","equipment":"bodyweight","primaryMuscles":["glutes"],"secondaryMuscles":["hamstrings"],"category":"compound","isBodyweight":true,"instructions":["Lie on your back with one foot planted on the floor; extend the other leg and keep the hips level.","Drive through the heel on the floor to lift the hips, forming a straight line from shoulder to knee.","Lower the hips under control; do not over-arch the lower back and work both sides."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/single-leg-glute-bridge.webp"]}},{"id":"atlas-single-leg-hip-thrust","name":"Single-Leg Hip Thrust","equipment":"bodyweight","primaryMuscles":["glutes"],"secondaryMuscles":["hamstrings"],"category":"compound","isBodyweight":true,"instructions":["Rest the upper back on a stable bench, plant one foot, and keep the other knee raised.","Drive through the planted foot to lift the hips until the torso and thigh approach a straight line.","Lower the hips under control without letting the pelvis twist; switch legs."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/single-leg-hip-thrust.webp"]}},{"id":"atlas-single-leg-leg-extension","name":"Single-Leg Leg Extension (Machine)","equipment":"machine","primaryMuscles":["quads"],"secondaryMuscles":[],"category":"isolation","instructions":["Adjust the seat so the knee aligns with the machine pivot and the shin pad rests just above the ankle.","Keep your back against the seat and extend one knee until the leg is nearly straight; do not forcefully lock it.","Lower the pad slowly, finish your repetitions on that leg, then switch sides."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/single-leg-leg-extension.webp"]}},{"id":"atlas-single-leg-leg-press","name":"Single-Leg Leg Press (Machine)","equipment":"machine","primaryMuscles":["quads"],"secondaryMuscles":["glutes","hamstrings"],"category":"compound","instructions":["Set the seat and safety stops, then place one foot flat near the center of the platform; keep the other leg clear of the moving sled.","Release the stops and lower the platform slowly until the working knee bends within a comfortable range without your pelvis lifting.","Press through the whole foot without locking the knee, then return under control and re-engage the stops before changing sides."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/single-leg-leg-press.webp"]}},{"id":"atlas-single-leg-romanian-deadlift","name":"Single-Leg Romanian Deadlift","equipment":"dumbbell","primaryMuscles":["glutes"],"secondaryMuscles":["hamstrings","lower_back"],"category":"compound","instructions":["Hold the dumbbells at your sides and balance on one foot; keep the knee slightly soft.","Hinge at the hips while extending the free leg backward; keep the back neutral and the hips facing the floor.","Drive through the standing foot to return upright; you may use support for balance and should work both sides equally."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/single-leg-romanian-deadlift.webp"]}},{"id":"atlas-single-leg-seated-leg-curl","name":"Single-Leg Seated Leg Curl (Machine)","equipment":"machine","primaryMuscles":["hamstrings"],"secondaryMuscles":[],"category":"isolation","instructions":["Adjust the seat and pads so the knee aligns with the pivot, the thigh is secured, and the lower-leg pad rests above the ankle.","Keep your hips against the seat and curl one heel down and back, bending the working knee.","Extend the working leg slowly without letting the weight stack drop; finish that side, then switch legs."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/single-leg-seated-leg-curl.webp"]}},{"id":"atlas-sissy-squat","name":"Sissy Squat","equipment":"bodyweight","primaryMuscles":["quads"],"secondaryMuscles":["calves"],"category":"compound","isBodyweight":true,"instructions":["Hold a stable support lightly and stand with feet hip-width apart.","Keep your hips extended, raise your heels and let both knees travel forward as your torso leans back in one line.","Bend only as far as you can control, then straighten the knees to return."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/sissy-squat.webp"]}},{"id":"atlas-sit-up","name":"Sit-Up","equipment":"bodyweight","primaryMuscles":["abs"],"secondaryMuscles":[],"category":"compound","isBodyweight":true,"instructions":["Lie on a mat with knees bent and feet planted; cross your arms over your chest.","Brace your abdomen and curl your torso toward your thighs without pulling on your head.","Lower with control until your upper back returns to the mat."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/sit-up.webp"]}},{"id":"atlas-sled-push","name":"Sled Push","equipment":"other","primaryMuscles":["quads","glutes"],"secondaryMuscles":["hamstrings","calves"],"category":"cardio","instructions":["Load a sled with a manageable weight and stand behind it with both hands on the handles.","Brace your trunk, lean forward with a long spine, and drive through short, steady steps to push the sled.","Slow down gradually at the end of the lane; reduce the load if your posture or steps become uneven."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/sled-push.webp"]}},{"id":"atlas-slider-leg-curl","name":"Slider Leg Curl","equipment":"other","primaryMuscles":["hamstrings"],"secondaryMuscles":["glutes"],"category":"isolation","instructions":["Lie on your back with sliders or a towel under the heels and lift the hips into a bridge position.","With the hips staying up, drag the heels toward you and bend the knees.","Extend the legs slowly; if the lower back drops, shorten the range or lower the hips to the floor."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/slider-leg-curl.webp"]}},{"id":"atlas-sliding-lateral-lunge","name":"Sliding Lateral Lunge","equipment":"other","primaryMuscles":["adductors"],"secondaryMuscles":["quads","glutes"],"category":"compound","instructions":["Place one foot on a sliding disc and set your feet hip-width apart; keep your torso balanced.","Slide the disc foot out to the side as you send your hips back toward the other foot; track the support knee in the direction of the foot.","Push off the support foot and pull the sliding leg back to the center; work both sides in control."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/sliding-lateral-lunge.webp"]}},{"id":"atlas-smith-machine-bulgarian-split-squat","name":"Bulgarian Split Squat (Smith Machine)","equipment":"smith_machine","primaryMuscles":["quads","glutes"],"secondaryMuscles":["hamstrings"],"category":"compound","instructions":["Set the safety stops and place a stable bench behind you. Position the Smith bar across your upper back, not your neck; place the top of one foot on the bench and set the front foot far enough forward to keep its heel down.","Keeping most of your weight over the front foot, bend both knees and lower under control; let the front knee track in line with your toes.","Press through the front foot to return to the start. Rack the bar securely before switching legs and use a load you can control."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/smith-machine-bulgarian-split-squat.webp"]}},{"id":"atlas-smith-machine-close-grip-bench-press","name":"Close-Grip Bench Press (Smith Machine)","equipment":"smith_machine","primaryMuscles":["triceps"],"secondaryMuscles":["chest","shoulders"],"category":"compound","instructions":["Set a flat bench beneath the Smith bar, take a shoulder-width grip, and place the safety stops just below your comfortable bottom position.","Unrack the bar and lower it under control toward the lower chest, keeping wrists over elbows and elbows close to the torso.","Press smoothly without bouncing or forcefully locking the elbows, then rotate the bar securely into its hooks."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/smith-machine-close-grip-bench-press.webp"]}},{"id":"atlas-smith-machine-deadlift","name":"Smith Machine Deadlift","equipment":"smith_machine","primaryMuscles":["glutes","hamstrings"],"secondaryMuscles":["quads","lower_back"],"category":"compound","instructions":["Set the Smith bar at its lowest usable height near your lower shins and place the safety stops just below the planned bottom position; load both sides evenly and check the hooks.","Stand with the bar over midfoot, bend your hips and knees to grip it, brace, and keep your back neutral. Push through the floor and extend your knees and hips together as the bar stays close to your legs.","Stand tall without leaning back, then lower the bar along the same path under control and re-hook it securely before stepping away."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/smith-machine-deadlift.webp"]}},{"id":"atlas-smith-machine-decline-bench-press","name":"Decline Bench Press (Smith Machine)","equipment":"smith_machine","primaryMuscles":["chest"],"secondaryMuscles":["triceps","shoulders"],"category":"compound","instructions":["Set a decline bench beneath the Smith bar, secure your feet under the upper-end pads, and position the safety stops just below your comfortable bottom range.","Unrack the bar and lower it under control toward the lower chest, keeping your wrists stacked over your elbows and your shoulders on the bench.","Press the guided bar back up without bouncing or forcefully locking your elbows, then rotate it securely into its hooks."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/smith-machine-decline-bench-press.webp"]}},{"id":"atlas-smith-machine-front-squat","name":"Front Squat (Smith Machine)","equipment":"smith_machine","primaryMuscles":["quads"],"secondaryMuscles":["glutes","adductors"],"category":"compound","instructions":["Set the bar near shoulder height and the safety stops at a depth you can control. Stand facing the bar and rest it across the front of your shoulders with your elbows pointing forward; rotate the bar to release the hooks.","Brace your torso and squat with your heels planted, knees tracking with your toes, and elbows lifted; descend only as far as you can keep your posture steady.","Drive through your feet to stand while keeping the bar on the front shoulders, then rotate the bar into the hooks before stepping away."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/smith-machine-front-squat.webp"]}},{"id":"atlas-smith-machine-hip-thrust","name":"Hip Thrust (Smith Machine)","equipment":"smith_machine","primaryMuscles":["glutes"],"secondaryMuscles":["hamstrings"],"category":"compound","instructions":["Place a stable bench so your upper back rests against its edge; sit under the Smith bar and position its pad across the hip crease. Set the bar low enough to begin safely and confirm the hooks engage securely.","With feet flat and knees bent, brace your trunk and drive through the floor to raise your hips until your torso and thighs align; avoid arching your lower back.","Lower the bar under control, then re-hook it securely before leaving the position."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/smith-machine-hip-thrust.webp"]}},{"id":"atlas-smith-machine-incline-bench-press","name":"Incline Bench Press (Smith Machine)","equipment":"smith_machine","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"category":"compound","instructions":["Set the bench to a modest incline beneath the bar and position the safety stops just below your comfortable bottom range.","Unrack the bar and lower it under control toward the upper chest, keeping wrists stacked over elbows.","Press up without bouncing, then rotate the bar securely back into its hooks."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/smith-machine-incline-bench-press.webp"]}},{"id":"atlas-smith-machine-pistol-squat","name":"Pistol Squat (Smith Machine)","equipment":"smith_machine","primaryMuscles":["quads"],"secondaryMuscles":["glutes","hamstrings","calves"],"category":"compound","instructions":["Set the safety stops just below your controlled squat depth. Place the bar across your upper traps, not your neck, and stand with the working foot flat slightly in front of the bar path.","Lift the free leg forward and lower by bending the working hip and knee; keep the heel planted and the knee tracking with the toes.","Press through the whole working foot to stand while keeping the free leg raised. Rehook the bar securely before changing sides; start with a light load."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/smith-machine-pistol-squat.webp"]}},{"id":"atlas-smith-machine-reverse-lunge","name":"Reverse Lunge (Smith Machine)","equipment":"smith_machine","primaryMuscles":["quads","glutes"],"secondaryMuscles":["hamstrings","abs"],"category":"compound","instructions":["Set the bar and safety stops at a suitable height; stand under the bar across your upper back and unrack it by turning the hooks clear.","Step one foot backward and lower under control until both knees bend comfortably; keep the front foot planted and front knee aligned with the toes.","Push through the front foot to return to standing, repeat on the other side, then turn the bar into the hooks securely."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/smith-machine-reverse-lunge.webp"]}},{"id":"atlas-smith-machine-romanian-deadlift","name":"Romanian Deadlift (Smith Machine)","equipment":"smith_machine","primaryMuscles":["hamstrings","glutes"],"secondaryMuscles":["lower_back"],"category":"compound","instructions":["Set the Smith bar at about hip height, load both sides evenly, and set the safety stops just below your planned range. Stand with feet hip-width and the bar against the front of your thighs.","Unlock the bar and hinge at the hips, keeping your knees softly bent, spine neutral, and bar close as it travels down the guide rails along your legs.","Stop when you feel a comfortable hamstring stretch, then press through your feet and extend your hips to stand. Re-rack the bar before changing the setup."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/smith-machine-romanian-deadlift.webp"]}},{"id":"atlas-smith-machine-shoulder-press","name":"Shoulder Press (Smith Machine)","equipment":"smith_machine","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps"],"category":"compound","instructions":["Place an upright bench under the Smith bar. Set the bar near shoulder height and the safety stops just below the bottom of your comfortable range. Sit with your back supported, feet planted, and hands slightly wider than shoulder width.","Unrack the bar and press it overhead along the rails; keep your wrists straight, elbows slightly forward, and torso against the pad without over-arching your lower back.","Lower the bar slowly to the front of your shoulders, then engage the hooks before changing the setup. Use a load you can control."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/smith-machine-shoulder-press.webp"]}},{"id":"atlas-smith-machine-standing-calf-raise","name":"Standing Calf Raise (Smith Machine)","equipment":"smith_machine","primaryMuscles":["calves"],"secondaryMuscles":[],"category":"isolation","instructions":["Rest the Smith bar on the upper back and place the front of the feet on a low, stable platform.","Lower the heels in a controlled way to create a comfortable stretch in the calves, then rise onto the toes.","Squeeze briefly at the very top and lower the heels slowly; do not bounce."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/smith-machine-standing-calf-raise.webp"]}},{"id":"atlas-sorensen-hold","name":"Sorensen Hold (Machine)","equipment":"machine","primaryMuscles":["lower_back"],"secondaryMuscles":["glutes","hamstrings"],"category":"compound","instructions":["Adjust the Roman chair pad below your hip crease and secure your ankles safely under the supports.","Hold your torso in line with your legs with your arms crossed over your chest; keep your lower back neutral.","Hold this position for a short, comfortable time and come out under control; do not over-arch your lower back, and stop if you feel pain."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/sorensen-hold.webp"]}},{"id":"atlas-spanish-squat","name":"Spanish Squat","equipment":"band","primaryMuscles":["quads"],"secondaryMuscles":["glutes"],"category":"compound","instructions":["Place a wide, sturdy band behind the knees and anchor it securely to a fixed point.","Keep the torso upright and the heels down, then bend the knees and squat in a controlled way.","Push through the soles of the feet to stand; check that the band does not slip and release it if you feel discomfort."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/spanish-squat.webp"]}},{"id":"atlas-stability-ball-leg-curl","name":"Stability Ball Leg Curl","equipment":"other","primaryMuscles":["hamstrings"],"secondaryMuscles":["glutes"],"category":"isolation","instructions":["Lie on your back with the heels on a stability ball and lift the hips into a bridge position.","Pull the ball toward you with the heels and bend the knees; keep the hips up as long as you can control them.","Extend the legs slowly; if the lower back drops, reduce the range of motion."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/stability-ball-leg-curl.webp"]}},{"id":"atlas-stability-ball-rollout","name":"Stability Ball Rollout","equipment":"other","primaryMuscles":["abs"],"secondaryMuscles":["shoulders"],"category":"compound","instructions":["Kneel and place your forearms on the stability ball; brace your abs and keep your lower back neutral.","Keeping your torso in a straight line, roll the ball forward in a controlled way.","Return without letting your lower back sag; use only as much range as you can control."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/stability-ball-rollout.webp"]}},{"id":"atlas-stair-climber","name":"Stair Climber (Step Mill)","equipment":"machine","primaryMuscles":["quads"],"secondaryMuscles":["glutes","hamstrings","calves"],"category":"cardio","instructions":["Step onto the machine using its entry procedure, select an easy pace, and stand upright with your full feet on the moving steps.","Climb continuously with controlled steps, keeping your torso tall and using the handrails lightly for balance rather than leaning heavily on them.","Use the machine's stop or recovery control to slow down before stepping off; follow its step-assist and auto-stop instructions."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/stair-climber.webp"]}},{"id":"atlas-standing-band-good-morning","name":"Standing Band Good Morning","equipment":"band","primaryMuscles":["hamstrings"],"secondaryMuscles":["glutes","lower_back"],"category":"compound","instructions":["Stand on the middle of a resistance band and place it securely across your upper back.","With knees softly bent, push your hips back and tip forward with a neutral spine.","Drive the hips forward to stand tall; use a band that allows smooth control."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/standing-band-good-morning.webp"]}},{"id":"atlas-standing-band-hip-abduction","name":"Standing Band Hip Abduction","equipment":"band","primaryMuscles":["abductors"],"secondaryMuscles":["glutes"],"category":"isolation","instructions":["Put a light band around your ankles; lightly hold onto a stable object for balance.","Keeping your torso upright, open one leg out to the side; point your toes forward.","Bring your leg back against the resistance of the band in a controlled way; do not lean your hips sideways and switch sides."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/standing-band-hip-abduction.webp"]}},{"id":"atlas-standing-band-leg-curl","name":"Standing Band Leg Curl","equipment":"band","primaryMuscles":["hamstrings"],"secondaryMuscles":[],"category":"isolation","instructions":["Anchor a light band low, loop it around one ankle, and hold a stable support.","Keep the thigh mostly still while bending the knee to draw the heel toward the buttock.","Lower the foot slowly against the band; repeat on the other leg."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/standing-band-leg-curl.webp"]}},{"id":"atlas-standing-band-pallof-press","name":"Standing Band Pallof Press","equipment":"band","primaryMuscles":["abs"],"secondaryMuscles":[],"category":"compound","instructions":["Anchor a band at chest height to your side and hold it at your chest.","Brace your abdomen and press both hands forward without turning.","Return slowly, then turn around to train the other side."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/standing-band-pallof-press.webp"]}},{"id":"atlas-standing-band-shoulder-external-rotation","name":"Standing Band Shoulder External Rotation","equipment":"band","primaryMuscles":["shoulders"],"secondaryMuscles":["back"],"category":"isolation","instructions":["Stand tall with elbows bent 90 degrees and close to your sides.","Rotate one forearm outward against the band without moving the elbow.","Return slowly and repeat on the other side."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/standing-band-shoulder-external-rotation.webp"]}},{"id":"atlas-standing-band-shoulder-internal-rotation","name":"Standing Band Shoulder Internal Rotation","equipment":"band","primaryMuscles":["shoulders"],"secondaryMuscles":[],"category":"isolation","instructions":["Anchor a light band at elbow height and stand side-on with the working arm nearest the anchor; bend the elbow to 90 degrees and keep it against the ribs.","Rotate the forearm inward across the abdomen without turning the torso or moving the elbow.","Return slowly to the start; use light tension and stop if the shoulder feels painful."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/standing-band-shoulder-internal-rotation.webp"]}},{"id":"atlas-standing-barbell-ab-rollout","name":"Standing Ab Rollout (Barbell)","equipment":"barbell","primaryMuscles":["abs"],"secondaryMuscles":["shoulders","lats","glutes"],"category":"compound","instructions":["Stand with feet about hip-width and a lightly loaded barbell with round plates on the floor. Hinge forward, grip the bar at shoulder width and brace your trunk with a neutral back.","Keeping your legs and feet planted, roll the bar forward under control until your body forms a long line and your torso approaches parallel with the floor; keep your hips from sagging.","Pull the bar back toward your feet while maintaining a tight trunk, then return to standing with control. This is an advanced variation; learn the kneeling rollout first and only use a range you can reverse safely."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/standing-barbell-ab-rollout.webp"]}},{"id":"atlas-standing-bent-knee-calf-raise","name":"Standing Bent-Knee Calf Raise","equipment":"bodyweight","primaryMuscles":["calves"],"secondaryMuscles":[],"category":"isolation","isBodyweight":true,"instructions":["Stand near a wall for balance with knees softly bent.","Rise onto the balls of both feet while keeping the knee bend.","Pause, then lower heels slowly without bouncing."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/standing-bent-knee-calf-raise.webp"]}},{"id":"atlas-standing-cable-chest-press","name":"Standing Chest Press (Cable)","equipment":"cable","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"category":"compound","instructions":["Set two cable pulleys around mid-chest height. Face away from them, hold a handle in each hand, and step into a stable staggered stance with elbows bent.","Brace your torso and press both handles forward at chest height without twisting or leaning back.","Return the handles slowly until your hands are beside your chest; keep your wrists neutral and shoulders relaxed."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/standing-cable-chest-press.webp"]}},{"id":"atlas-standing-cable-row","name":"Standing Row (Cable)","equipment":"cable","primaryMuscles":["back"],"secondaryMuscles":["lats","biceps","shoulders"],"category":"compound","instructions":["Set a cable pulley at chest height and attach a neutral-grip handle. Stand facing the pulley with feet hip-width apart, knees soft, and arms extended to hold the handle.","Keep your torso upright and pull the handle toward your lower ribs, drawing your elbow close to your side without rocking backward.","Straighten your arm slowly and let the shoulder blade move forward under control before the next repetition."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/standing-cable-row.webp"]}},{"id":"atlas-standing-dumbbell-reverse-curl","name":"Standing Reverse Curl (Dumbbell)","equipment":"dumbbell","primaryMuscles":["forearms"],"secondaryMuscles":["biceps"],"category":"compound","instructions":["Stand tall with a dumbbell in each hand and palms facing your thighs.","Keep wrists straight and elbows near your sides as you curl the weights upward.","Lower slowly without swinging your shoulders."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/standing-dumbbell-reverse-curl.webp"]}},{"id":"atlas-standing-landmine-press","name":"Standing Two-Arm Landmine Press","equipment":"barbell","primaryMuscles":["shoulders","chest"],"secondaryMuscles":["triceps","abs"],"category":"compound","instructions":["Secure one end of a barbell in a landmine base. Face the anchored end, hold the free sleeve with both hands at upper-chest height, and stand with a stable hip-width stance.","Brace your trunk and press the bar diagonally forward and upward along its arc, keeping your torso tall rather than leaning back.","Bend your elbows and lower the sleeve under control to the upper chest."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/standing-landmine-press.webp"]}},{"id":"atlas-standing-machine-hip-abduction","name":"Standing Hip Abduction (Machine)","equipment":"machine","primaryMuscles":["abductors"],"secondaryMuscles":["glutes"],"category":"isolation","instructions":["Set the resistance, stand with both feet on the machine's foot platforms, and place the pads against the outside of your knees. Hold the handles and lean back with your arms extended; keep your knees bent.","Keeping your feet planted and torso steady, press both knees outward against the pads without twisting your hips.","Pause briefly, then let the pads return slowly until your knees are near the start position."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/standing-machine-hip-abduction.webp"]}},{"id":"atlas-standing-machine-hip-thrust","name":"Standing Hip Thrust (Machine)","equipment":"machine","primaryMuscles":["glutes"],"secondaryMuscles":["hamstrings"],"category":"compound","instructions":["Follow the machine placard to set the start angle, footrests and pelvic roller. Stand on both footrests, position the roller at your pelvis and hold the handles.","Keep your knees softly bent and your trunk braced. Hinge at the hips to move your pelvis back under control without rounding your back.","Drive your hips forward against the roller until you stand tall with a neutral spine. Do not lean back; return slowly to the hinged start."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/standing-machine-hip-thrust.webp"]}},{"id":"atlas-standing-machine-leg-curl","name":"Standing Leg Curl (Machine)","equipment":"machine","primaryMuscles":["hamstrings"],"secondaryMuscles":["calves"],"category":"compound","instructions":["Adjust the machine so its pivot aligns with your knee and the roller rests just above your ankle; hold the support handles.","Keep your thigh against the pad and curl your heel toward your glute without swinging your hip.","Lower the weight slowly until your knee is nearly straight, keeping tension on the stack."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/standing-machine-leg-curl.webp"]}},{"id":"atlas-standing-wall-calf-stretch","name":"Standing Wall Calf Stretch","equipment":"bodyweight","primaryMuscles":["calves"],"secondaryMuscles":[],"category":"mobility","isBodyweight":true,"instructions":["Place both hands on a wall, step one foot back, and keep the back heel grounded with toes pointing forward.","Bend the front knee and lean gently toward the wall until you feel a mild stretch in the rear calf.","Hold without bouncing, then switch legs; keep the rear heel down."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/standing-wall-calf-stretch.webp"]}},{"id":"atlas-step-up","name":"Step-Up","equipment":"bodyweight","primaryMuscles":["quads","glutes"],"secondaryMuscles":["calves"],"category":"compound","isBodyweight":true,"instructions":["Place one foot securely on a stable platform.","Push through that foot to stand on the platform, then descend."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/step-up.webp"]}},{"id":"atlas-stiff-leg-deadlift","name":"Stiff-Leg Deadlift","equipment":"barbell","primaryMuscles":["hamstrings"],"secondaryMuscles":["glutes","lower_back"],"category":"compound","instructions":["Stand holding the bar in front of your thighs with knees softly bent, not locked, and your spine neutral.","Push your hips back and lower the bar close to your legs until you feel a hamstring stretch you can control.","Drive your hips forward to stand tall; avoid rounding your back or leaning backward at the top."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/stiff-leg-deadlift.webp"]}},{"id":"atlas-stir-the-pot","name":"Stir the Pot","equipment":"other","primaryMuscles":["abs"],"secondaryMuscles":["shoulders"],"category":"compound","instructions":["Kneel behind a stability ball and place your forearms on top; step your feet back into a steady plank.","Brace your trunk and make small, controlled circles with your forearms around the ball, keeping hips level.","Reverse the circles, then stop before your lower back arches or your shoulders lose control."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/stir-the-pot.webp"]}},{"id":"atlas-suitcase-carry","name":"Suitcase Carry","equipment":"dumbbell","primaryMuscles":["abs"],"secondaryMuscles":["forearms","glutes"],"category":"compound","instructions":["Hold one dumbbell at your side with a firm grip and stand tall with shoulders level.","Walk a controlled distance without leaning toward or away from the weight.","Set the dumbbell down safely, switch hands, and repeat while keeping the torso upright."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/suitcase-carry.webp"]}},{"id":"atlas-sumo-squat","name":"Sumo Squat","equipment":"bodyweight","primaryMuscles":["adductors"],"secondaryMuscles":["quads","glutes"],"category":"compound","isBodyweight":true,"instructions":["Set your feet wide apart and turn your toes comfortably outward; keep your torso upright.","As you lower your hips, let your knees track in the same direction as your toes.","Drive through the soles of your feet to stand up; do not let your knees collapse inward and stay at a pain-free depth."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/sumo-squat.webp"]}},{"id":"atlas-superman","name":"Superman","equipment":"bodyweight","primaryMuscles":["lower_back"],"secondaryMuscles":["glutes","hamstrings"],"category":"compound","isBodyweight":true,"instructions":["Lie face down with your arms extended forward; bring your forehead close to the floor and keep your neck neutral.","Without compressing your lower back, lift the opposite arm and leg slightly; keep the movement small and controlled.","Lower slowly and switch sides; if you feel discomfort in your lower back, reduce the lift height or stop."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/superman.webp"]}},{"id":"atlas-supine-medicine-ball-chest-pass","name":"Supine Medicine Ball Chest Pass","equipment":"other","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"category":"compound","instructions":["Lie on a flat bench with feet planted and hold a light medicine ball over the chest; have a partner stand clear of the ball path.","Bend the elbows to bring the ball toward the chest, then press and toss it straight upward to the partner.","Let the partner return the ball into both hands and absorb it by bending the elbows; use a light ball and a clear area."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/supine-medicine-ball-chest-pass.webp"]}},{"id":"atlas-t-bar-row","name":"T-Bar Row","equipment":"barbell","primaryMuscles":["back"],"secondaryMuscles":["lats","biceps"],"category":"compound","instructions":["Anchor one end of the bar in a sturdy landmine sleeve and attach a suitable close handle.","Hinge forward at the hips and keep your back neutral; pull your elbows back and bring the handle toward your torso.","Lower the bar without jerking; do not rotate your torso during the pull."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/t-bar-row.webp"]}},{"id":"atlas-tibialis-raise","name":"Tibialis Raise","equipment":"bodyweight","primaryMuscles":["calves"],"secondaryMuscles":[],"category":"isolation","isBodyweight":true,"instructions":["Lean your back against a wall with the heels on the floor and the feet placed comfortably forward.","Without lifting the heels, raise the toes and forefoot toward the shins.","Lower the forefoot slowly; start with small, controlled repetitions."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/tibialis-raise.webp"]}},{"id":"atlas-tiptoe-farmer-carry","name":"Tiptoe Farmer Carry","equipment":"dumbbell","primaryMuscles":["calves"],"secondaryMuscles":["forearms","traps"],"category":"compound","instructions":["Stand tall with a manageable dumbbell in each hand and clear walking space.","Rise onto the balls of the feet and take short controlled steps without letting the ankles roll.","Lower the heels when needed, reset balance, and continue only while the path remains clear."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/tiptoe-farmer-carry.webp"]}},{"id":"atlas-toes-to-bar","name":"Toes-to-Bar","equipment":"bodyweight","primaryMuscles":["abs"],"secondaryMuscles":["forearms"],"category":"compound","isBodyweight":true,"instructions":["Hang from a secure bar with a firm grip and legs together.","Brace your trunk and lift your straight legs until your toes reach the bar without swinging.","Lower slowly to a controlled hang; stop if your grip becomes insecure."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/toes-to-bar.webp"]}},{"id":"atlas-torso-rotation-machine","name":"Torso Rotation (Machine)","equipment":"machine","primaryMuscles":["abs"],"secondaryMuscles":["lower_back"],"category":"compound","instructions":["Adjust the seat so the chest pads sit across your upper chest, choose a starting direction and resistance, then sit with your feet on the platforms and hold the handles.","Keep your chest against the pads and your thighs braced against the restraints; rotate your torso toward the opposite side through a controlled range.","Return slowly to the selected start position, then adjust the machine to train the other direction."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/torso-rotation-machine.webp"]}},{"id":"atlas-treadmill-running","name":"Treadmill Running","equipment":"machine","primaryMuscles":["quads"],"secondaryMuscles":["calves","glutes","hamstrings"],"category":"cardio","instructions":["Clip the treadmill safety tether to your clothing. Begin at a slow belt speed from the side rails or at a walk, and make sure your footing is stable.","Gradually increase speed to a sustainable run. Stay near the center of the belt with an upright torso, relaxed shoulders, and a natural arm swing.","Slow down to a walk before ending the workout. Wait for the belt to stop before stepping onto the side rails and dismounting."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/treadmill-running.webp"]}},{"id":"atlas-treadmill-walking","name":"Treadmill Walking","equipment":"machine","primaryMuscles":["quads"],"secondaryMuscles":["calves","glutes","hamstrings"],"category":"cardio","instructions":["Clip the treadmill safety tether to your clothing. Stand on the side rails while the belt begins at a slow speed, then step onto the walking surface when steady.","Walk upright near the center of the belt at a comfortable pace, letting your arms swing naturally and keeping your steps controlled.","Reduce speed before ending the workout. Wait for the belt to stop before stepping onto the side rails and dismounting."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/treadmill-walking.webp"]}},{"id":"atlas-two-dumbbell-hang-clean","name":"Two-Hang Clean (Dumbbell)","equipment":"dumbbell","primaryMuscles":["glutes","quads","traps"],"secondaryMuscles":["hamstrings"],"category":"compound","instructions":["Stand with dumbbells beside your thighs and soften your knees.","Hinge slightly, then extend your hips and knees briskly to guide the dumbbells to shoulder height.","Catch the weights at your shoulders with control and lower to the hang position."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/two-dumbbell-hang-clean.webp"]}},{"id":"atlas-upright-stationary-bike","name":"Stationary Bike (Upright)","equipment":"machine","primaryMuscles":["quads"],"secondaryMuscles":["calves","glutes","hamstrings"],"category":"cardio","instructions":["Adjust the seat so your knee remains slightly bent when the pedal is at its lowest point; make adjustments while off the bike. Place the balls of your feet over the pedals and secure straps if fitted.","Hold the handlebars comfortably, brace your torso, and pedal smoothly through a full circle without rocking your hips or locking your knees.","Choose a comfortable resistance and cadence, then ease your pace down before stopping and dismounting."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/upright-stationary-bike.webp"]}},{"id":"atlas-v-squat","name":"V-Squat Machine","equipment":"machine","primaryMuscles":["quads"],"secondaryMuscles":["glutes","hamstrings","adductors"],"category":"compound","instructions":["Load both sides evenly. Set your back and shoulders against the pads, place both feet securely on the platform, and follow the machine placard to release the safety.","Bend your hips and knees to lower along the machine's arc; keep your heels planted and knees tracking with your toes.","Push through the platform to stand without snapping your knees straight, then engage the safety before stepping off."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/v-squat.webp"]}},{"id":"atlas-v-up","name":"V-Up","equipment":"bodyweight","primaryMuscles":["abs"],"secondaryMuscles":[],"category":"compound","isBodyweight":true,"instructions":["Lie on your back with legs straight and arms extended overhead.","Brace your abdomen and lift your torso and legs together, reaching toward your toes.","Lower slowly without dropping the legs or arching your lower back."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/v-up.webp"]}},{"id":"atlas-vertical-leg-press","name":"Vertical Leg Press (Machine)","equipment":"machine","primaryMuscles":["quads"],"secondaryMuscles":["glutes","hamstrings"],"category":"compound","instructions":["Load both sides evenly. Lie back with your head, back, and hips supported; place your feet shoulder-width on the platform and release the safety only as the machine placard directs.","Bend your knees to lower the platform toward you under control, stopping at a depth that keeps your hips and lower back supported.","Press through the whole foot without snapping the knees straight; engage both safety stops before getting out."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/vertical-leg-press.webp"]}},{"id":"atlas-waiter-curl","name":"Waiter Curl","equipment":"dumbbell","primaryMuscles":["biceps"],"secondaryMuscles":["forearms"],"category":"isolation","instructions":["Hold a light dumbbell upright by supporting one end from below with both palms; bring your elbows closer to your torso.","Keeping your elbows fixed, curl the dumbbell toward your chest under control.","Lower the weight slowly; keep your wrists comfortable and straight."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/waiter-curl.webp"]}},{"id":"atlas-walking-lunge","name":"Walking Lunge","equipment":"bodyweight","primaryMuscles":["quads"],"secondaryMuscles":["glutes"],"category":"compound","isBodyweight":true,"instructions":["Stand tall and take a balanced step forward; do not place the feet on one line.","Bend both knees under control to lower; keep the front knee over the ankle and toes.","Drive through the front foot to stand and continue with the other leg; start with in-place lunges if needed."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/walking-lunge.webp"]}},{"id":"atlas-wall-ball-shot","name":"Wall-Ball Shot","equipment":"other","primaryMuscles":["quads","glutes"],"secondaryMuscles":["shoulders","abs","calves"],"category":"compound","instructions":["Stand facing a clear wall target, holding a light medicine ball at the upper chest with feet about shoulder-width apart.","Squat under control, then drive through the feet and hips to stand as you throw the ball toward the target.","Catch the rebound softly at chest height and descend into the next squat; begin with a light ball and clear space."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/wall-ball-shot.webp"]}},{"id":"atlas-wall-sit","name":"Wall Sit","equipment":"bodyweight","primaryMuscles":["quads"],"secondaryMuscles":["glutes"],"category":"compound","isBodyweight":true,"instructions":["Stand with the back against a wall and feet a comfortable step in front.","Slide down to a comfortable seated position with knees tracking over feet.","Hold while breathing normally, then push through the feet to stand; stop if knee pain occurs."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/wall-sit.webp"]}},{"id":"atlas-wall-slide","name":"Wall Slide","equipment":"bodyweight","primaryMuscles":["shoulders"],"secondaryMuscles":["back"],"category":"mobility","isBodyweight":true,"instructions":["Stand with your back lightly against a wall and your feet a short step forward; begin with elbows bent in a comfortable W.","Keep the forearms near the wall as you slide the hands upward into a comfortable overhead reach.","Lower slowly to the starting position while keeping the ribs controlled and shoulders relaxed."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/wall-slide.webp"]}},{"id":"atlas-weighted-dip","name":"Weighted Dip","equipment":"bodyweight","primaryMuscles":["chest","triceps"],"secondaryMuscles":["shoulders"],"category":"compound","isBodyweight":true,"instructions":["Secure a small plate to a dip belt and grip the parallel bars at the top position.","Bend your elbows to lower smoothly to a shoulder-comfortable depth while keeping the plate from swinging.","Press through the bars to return to the top; use bodyweight until you can control the full range."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/weighted-dip.webp"]}},{"id":"atlas-weighted-pull-up","name":"Weighted Pull-Up","equipment":"bodyweight","primaryMuscles":["lats","back"],"secondaryMuscles":["biceps","forearms"],"category":"compound","isBodyweight":true,"instructions":["Secure a small plate to a dip belt, grip the bar overhand slightly wider than your shoulders, and hang with arms extended.","Brace your trunk and pull your elbows down until your chin reaches bar height without swinging.","Lower under control to the full hang; start with bodyweight if you cannot maintain a smooth path."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/weighted-pull-up.webp"]}},{"id":"atlas-weighted-push-up","name":"Weighted Push-Up","equipment":"bodyweight","primaryMuscles":["chest"],"secondaryMuscles":["triceps","shoulders","abs"],"category":"compound","isBodyweight":true,"instructions":["Wear a fitted weighted vest and set up in a high plank with hands just wider than shoulder width.","Lower your chest toward the floor while keeping your body aligned from shoulders to heels.","Press the floor away to return to the top; use a lighter vest or a regular push-up if alignment changes."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/weighted-push-up.webp"]}},{"id":"atlas-wide-grip-barbell-bench-press","name":"Wide-Grip Bench Press (Barbell)","equipment":"barbell","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"category":"compound","instructions":["Set a flat bench in a rack with safety arms below your chest; lie down, plant your feet and grip the bar wider than shoulder width, where your forearms can stay near vertical at the bottom.","Unrack the bar and lower it under control to the mid-to-lower chest, keeping wrists over elbows and your upper back and hips in contact with the bench.","Press the bar above the chest without bouncing, then return slowly; use a spotter for heavy attempts."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/wide-grip-barbell-bench-press.webp"]}},{"id":"atlas-wide-grip-lat-pulldown","name":"Wide-Grip Lat Pulldown (Cable)","equipment":"cable","primaryMuscles":["lats"],"secondaryMuscles":["biceps","back"],"category":"compound","instructions":["Secure the thigh pad and grip the bar slightly wider than your shoulders.","Keeping your torso upright, pull your elbows down and out to the sides; bring the bar toward your upper chest.","Do not pull the bar behind your head; extend your arms back to the start under control."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/wide-grip-lat-pulldown.webp"]}},{"id":"atlas-wide-grip-pull-up","name":"Wide-Grip Pull-Up","equipment":"bodyweight","primaryMuscles":["lats"],"secondaryMuscles":["back","biceps","forearms"],"category":"compound","isBodyweight":true,"instructions":["Hang from a secure bar with an overhand grip slightly wider than shoulder width; brace your torso and keep your legs quiet.","Drive your elbows down and out to raise your chin to bar height without swinging or shrugging.","Lower under control to a comfortable overhead reach; do not force an excessively wide or painful grip."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/wide-grip-pull-up.webp"]}},{"id":"atlas-wrist-roller","name":"Wrist Roller","equipment":"other","primaryMuscles":["forearms"],"secondaryMuscles":[],"category":"isolation","instructions":["Attach a light weight to the rope on a roller handle; hold the handle in front of you at shoulder height with both hands.","Turn your wrists alternately to wind the rope and slowly raise the weight.","Unwind the rope in the opposite direction under control to lower the weight; keep the load light and do not let go."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/wrist-roller.webp"]}},{"id":"atlas-yates-row","name":"Yates Row","equipment":"barbell","primaryMuscles":["lats"],"secondaryMuscles":["back","biceps","forearms","lower_back"],"category":"compound","instructions":["Stand with feet about hip-width and grip the bar with palms facing forward. Soften your knees, hinge at the hips to a torso angle you can hold steadily, and let the bar hang below your shoulders.","Keep your torso still and the bar close as you draw your elbows back and row the bar toward your lower abdomen.","Lower the bar slowly until your arms are extended comfortably, maintaining the hip hinge and straight wrists. Start with a load you can control."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/yates-row.webp"]}},{"id":"atlas-zercher-squat","name":"Zercher Squat","equipment":"barbell","primaryMuscles":["quads","glutes"],"secondaryMuscles":["back","abs"],"category":"compound","instructions":["Set the bar in a rack around lower-chest height and secure it in the crooks of your elbows.","Brace your trunk, stand with feet about shoulder-width apart and squat while keeping heels grounded.","Drive through the floor to stand; use a light load and safeties while learning the hold."],"formCues":[],"media":{"motionUrls":["https://raw.githubusercontent.com/yagizerentunay/open-exercise-atlas/d46835681c450c1fb76d77e5e0cd74e799076e5e/media/exercises/zercher-squat.webp"]}}];
